window.KH_SURA(13, {"sura": "الرعد", "n": 13, "ayat": {"1": "المر تِلْكَ آيَاتُ الْكِتَابِ وَالَّذِي أُنْزِلَ إِلَيْكَ مِنْ رَبِّكَ الْحَقُّ وَلَكِنَّ أَكْثَرَ النَّاسِ لَا يُؤْمِنُونَ", "2": "اللَّهُ الَّذِي رَفَعَ السَّمَاوَاتِ بِغَيْرِ عَمَدٍ تَرَوْنَهَا ثُمَّ اسْتَوَى عَلَى الْعَرْشِ وَسَخَّرَ الشَّمْسَ وَالْقَمَرَ كُلٌّ يَجْرِي لِأَجَلٍ مُسَمًّى يُدَبِّرُ الْأَمْرَ يُفَصِّلُ الْآيَاتِ لَعَلَّكُمْ بِلِقَاءِ رَبِّكُمْ تُوقِنُونَ", "3": "وَهُوَ الَّذِي مَدَّ الْأَرْضَ وَجَعَلَ فِيهَا رَوَاسِيَ وَأَنْهَارًا وَمِنْ كُلِّ الثَّمَرَاتِ جَعَلَ فِيهَا زَوْجَيْنِ اثْنَيْنِ يُغْشِي اللَّيْلَ النَّهَارَ إِنَّ فِي ذَلِكَ لَآيَاتٍ لِقَوْمٍ يَتَفَكَّرُونَ", "4": "وَفِي الْأَرْضِ قِطَعٌ مُتَجَاوِرَاتٌ وَجَنَّاتٌ مِنْ أَعْنَابٍ وَزَرْعٌ وَنَخِيلٌ صِنْوَانٌ وَغَيْرُ صِنْوَانٍ يُسْقَى بِمَاءٍ وَاحِدٍ وَنُفَضِّلُ بَعْضَهَا عَلَى بَعْضٍ فِي الْأُكُلِ إِنَّ فِي ذَلِكَ لَآيَاتٍ لِقَوْمٍ يَعْقِلُونَ", "5": "وَإِنْ تَعْجَبْ فَعَجَبٌ قَوْلُهُمْ أَإِذَا كُنَّا تُرَابًا أَإِنَّا لَفِي خَلْقٍ جَدِيدٍ أُولَئِكَ الَّذِينَ كَفَرُوا بِرَبِّهِمْ وَأُولَئِكَ الْأَغْلَالُ فِي أَعْنَاقِهِمْ وَأُولَئِكَ أَصْحَابُ النَّارِ هُمْ فِيهَا خَالِدُونَ", "6": "وَيَسْتَعْجِلُونَكَ بِالسَّيِّئَةِ قَبْلَ الْحَسَنَةِ وَقَدْ خَلَتْ مِنْ قَبْلِهِمُ الْمَثُلَاتُ وَإِنَّ رَبَّكَ لَذُو مَغْفِرَةٍ لِلنَّاسِ عَلَى ظُلْمِهِمْ وَإِنَّ رَبَّكَ لَشَدِيدُ الْعِقَابِ", "7": "وَيَقُولُ الَّذِينَ كَفَرُوا لَوْلَا أُنْزِلَ عَلَيْهِ آيَةٌ مِنْ رَبِّهِ إِنَّمَا أَنْتَ مُنْذِرٌ وَلِكُلِّ قَوْمٍ هَادٍ", "8": "اللَّهُ يَعْلَمُ مَا تَحْمِلُ كُلُّ أُنْثَى وَمَا تَغِيضُ الْأَرْحَامُ وَمَا تَزْدَادُ وَكُلُّ شَيْءٍ عِنْدَهُ بِمِقْدَارٍ", "9": "عَالِمُ الْغَيْبِ وَالشَّهَادَةِ الْكَبِيرُ الْمُتَعَالِ", "10": "سَوَاءٌ مِنْكُمْ مَنْ أَسَرَّ الْقَوْلَ وَمَنْ جَهَرَ بِهِ وَمَنْ هُوَ مُسْتَخْفٍ بِاللَّيْلِ وَسَارِبٌ بِالنَّهَارِ", "11": "لَهُ مُعَقِّبَاتٌ مِنْ بَيْنِ يَدَيْهِ وَمِنْ خَلْفِهِ يَحْفَظُونَهُ مِنْ أَمْرِ اللَّهِ إِنَّ اللَّهَ لَا يُغَيِّرُ مَا بِقَوْمٍ حَتَّى يُغَيِّرُوا مَا بِأَنْفُسِهِمْ وَإِذَا أَرَادَ اللَّهُ بِقَوْمٍ سُوءًا فَلَا مَرَدَّ لَهُ وَمَا لَهُمْ مِنْ دُونِهِ مِنْ وَالٍ", "12": "هُوَ الَّذِي يُرِيكُمُ الْبَرْقَ خَوْفًا وَطَمَعًا وَيُنْشِئُ السَّحَابَ الثِّقَالَ", "13": "وَيُسَبِّحُ الرَّعْدُ بِحَمْدِهِ وَالْمَلَائِكَةُ مِنْ خِيفَتِهِ وَيُرْسِلُ الصَّوَاعِقَ فَيُصِيبُ بِهَا مَنْ يَشَاءُ وَهُمْ يُجَادِلُونَ فِي اللَّهِ وَهُوَ شَدِيدُ الْمِحَالِ", "14": "لَهُ دَعْوَةُ الْحَقِّ وَالَّذِينَ يَدْعُونَ مِنْ دُونِهِ لَا يَسْتَجِيبُونَ لَهُمْ بِشَيْءٍ إِلَّا كَبَاسِطِ كَفَّيْهِ إِلَى الْمَاءِ لِيَبْلُغَ فَاهُ وَمَا هُوَ بِبَالِغِهِ وَمَا دُعَاءُ الْكَافِرِينَ إِلَّا فِي ضَلَالٍ", "15": "وَلِلَّهِ يَسْجُدُ مَنْ فِي السَّمَاوَاتِ وَالْأَرْضِ طَوْعًا وَكَرْهًا وَظِلَالُهُمْ بِالْغُدُوِّ وَالْآصَالِ", "16": "قُلْ مَنْ رَبُّ السَّمَاوَاتِ وَالْأَرْضِ قُلِ اللَّهُ قُلْ أَفَاتَّخَذْتُمْ مِنْ دُونِهِ أَوْلِيَاءَ لَا يَمْلِكُونَ لِأَنْفُسِهِمْ نَفْعًا وَلَا ضَرًّا قُلْ هَلْ يَسْتَوِي الْأَعْمَى وَالْبَصِيرُ أَمْ هَلْ تَسْتَوِي الظُّلُمَاتُ وَالنُّورُ أَمْ جَعَلُوا لِلَّهِ شُرَكَاءَ خَلَقُوا كَخَلْقِهِ فَتَشَابَهَ الْخَلْقُ عَلَيْهِمْ قُلِ اللَّهُ خَالِقُ كُلِّ شَيْءٍ وَهُوَ الْوَاحِدُ الْقَهَّارُ", "17": "أَنْزَلَ مِنَ السَّمَاءِ مَاءً فَسَالَتْ أَوْدِيَةٌ بِقَدَرِهَا فَاحْتَمَلَ السَّيْلُ زَبَدًا رَابِيًا وَمِمَّا يُوقِدُونَ عَلَيْهِ فِي النَّارِ ابْتِغَاءَ حِلْيَةٍ أَوْ مَتَاعٍ زَبَدٌ مِثْلُهُ كَذَلِكَ يَضْرِبُ اللَّهُ الْحَقَّ وَالْبَاطِلَ فَأَمَّا الزَّبَدُ فَيَذْهَبُ جُفَاءً وَأَمَّا مَا يَنْفَعُ النَّاسَ فَيَمْكُثُ فِي الْأَرْضِ كَذَلِكَ يَضْرِبُ اللَّهُ الْأَمْثَالَ", "18": "لِلَّذِينَ اسْتَجَابُوا لِرَبِّهِمُ الْحُسْنَى وَالَّذِينَ لَمْ يَسْتَجِيبُوا لَهُ لَوْ أَنَّ لَهُمْ مَا فِي الْأَرْضِ جَمِيعًا وَمِثْلَهُ مَعَهُ لَافْتَدَوْا بِهِ أُولَئِكَ لَهُمْ سُوءُ الْحِسَابِ وَمَأْوَاهُمْ جَهَنَّمُ وَبِئْسَ الْمِهَادُ", "19": "أَفَمَنْ يَعْلَمُ أَنَّمَا أُنْزِلَ إِلَيْكَ مِنْ رَبِّكَ الْحَقُّ كَمَنْ هُوَ أَعْمَى إِنَّمَا يَتَذَكَّرُ أُولُو الْأَلْبَابِ", "20": "الَّذِينَ يُوفُونَ بِعَهْدِ اللَّهِ وَلَا يَنْقُضُونَ الْمِيثَاقَ", "21": "وَالَّذِينَ يَصِلُونَ مَا أَمَرَ اللَّهُ بِهِ أَنْ يُوصَلَ وَيَخْشَوْنَ رَبَّهُمْ وَيَخَافُونَ سُوءَ الْحِسَابِ", "22": "وَالَّذِينَ صَبَرُوا ابْتِغَاءَ وَجْهِ رَبِّهِمْ وَأَقَامُوا الصَّلَاةَ وَأَنْفَقُوا مِمَّا رَزَقْنَاهُمْ سِرًّا وَعَلَانِيَةً وَيَدْرَءُونَ بِالْحَسَنَةِ السَّيِّئَةَ أُولَئِكَ لَهُمْ عُقْبَى الدَّارِ", "23": "جَنَّاتُ عَدْنٍ يَدْخُلُونَهَا وَمَنْ صَلَحَ مِنْ آبَائِهِمْ وَأَزْوَاجِهِمْ وَذُرِّيَّاتِهِمْ وَالْمَلَائِكَةُ يَدْخُلُونَ عَلَيْهِمْ مِنْ كُلِّ بَابٍ", "24": "سَلَامٌ عَلَيْكُمْ بِمَا صَبَرْتُمْ فَنِعْمَ عُقْبَى الدَّارِ", "25": "وَالَّذِينَ يَنْقُضُونَ عَهْدَ اللَّهِ مِنْ بَعْدِ مِيثَاقِهِ وَيَقْطَعُونَ مَا أَمَرَ اللَّهُ بِهِ أَنْ يُوصَلَ وَيُفْسِدُونَ فِي الْأَرْضِ أُولَئِكَ لَهُمُ اللَّعْنَةُ وَلَهُمْ سُوءُ الدَّارِ", "26": "اللَّهُ يَبْسُطُ الرِّزْقَ لِمَنْ يَشَاءُ وَيَقْدِرُ وَفَرِحُوا بِالْحَيَاةِ الدُّنْيَا وَمَا الْحَيَاةُ الدُّنْيَا فِي الْآخِرَةِ إِلَّا مَتَاعٌ", "27": "وَيَقُولُ الَّذِينَ كَفَرُوا لَوْلَا أُنْزِلَ عَلَيْهِ آيَةٌ مِنْ رَبِّهِ قُلْ إِنَّ اللَّهَ يُضِلُّ مَنْ يَشَاءُ وَيَهْدِي إِلَيْهِ مَنْ أَنَابَ", "28": "الَّذِينَ آمَنُوا وَتَطْمَئِنُّ قُلُوبُهُمْ بِذِكْرِ اللَّهِ أَلَا بِذِكْرِ اللَّهِ تَطْمَئِنُّ الْقُلُوبُ", "29": "الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ طُوبَى لَهُمْ وَحُسْنُ مَآبٍ", "30": "كَذَلِكَ أَرْسَلْنَاكَ فِي أُمَّةٍ قَدْ خَلَتْ مِنْ قَبْلِهَا أُمَمٌ لِتَتْلُوَ عَلَيْهِمُ الَّذِي أَوْحَيْنَا إِلَيْكَ وَهُمْ يَكْفُرُونَ بِالرَّحْمَنِ قُلْ هُوَ رَبِّي لَا إِلَهَ إِلَّا هُوَ عَلَيْهِ تَوَكَّلْتُ وَإِلَيْهِ مَتَابِ", "31": "وَلَوْ أَنَّ قُرْآنًا سُيِّرَتْ بِهِ الْجِبَالُ أَوْ قُطِّعَتْ بِهِ الْأَرْضُ أَوْ كُلِّمَ بِهِ الْمَوْتَى بَلْ لِلَّهِ الْأَمْرُ جَمِيعًا أَفَلَمْ يَيْأَسِ الَّذِينَ آمَنُوا أَنْ لَوْ يَشَاءُ اللَّهُ لَهَدَى النَّاسَ جَمِيعًا وَلَا يَزَالُ الَّذِينَ كَفَرُوا تُصِيبُهُمْ بِمَا صَنَعُوا قَارِعَةٌ أَوْ تَحُلُّ قَرِيبًا مِنْ دَارِهِمْ حَتَّى يَأْتِيَ وَعْدُ اللَّهِ إِنَّ اللَّهَ لَا يُخْلِفُ الْمِيعَادَ", "32": "وَلَقَدِ اسْتُهْزِئَ بِرُسُلٍ مِنْ قَبْلِكَ فَأَمْلَيْتُ لِلَّذِينَ كَفَرُوا ثُمَّ أَخَذْتُهُمْ فَكَيْفَ كَانَ عِقَابِ", "33": "أَفَمَنْ هُوَ قَائِمٌ عَلَى كُلِّ نَفْسٍ بِمَا كَسَبَتْ وَجَعَلُوا لِلَّهِ شُرَكَاءَ قُلْ سَمُّوهُمْ أَمْ تُنَبِّئُونَهُ بِمَا لَا يَعْلَمُ فِي الْأَرْضِ أَمْ بِظَاهِرٍ مِنَ الْقَوْلِ بَلْ زُيِّنَ لِلَّذِينَ كَفَرُوا مَكْرُهُمْ وَصُدُّوا عَنِ السَّبِيلِ وَمَنْ يُضْلِلِ اللَّهُ فَمَا لَهُ مِنْ هَادٍ", "34": "لَهُمْ عَذَابٌ فِي الْحَيَاةِ الدُّنْيَا وَلَعَذَابُ الْآخِرَةِ أَشَقُّ وَمَا لَهُمْ مِنَ اللَّهِ مِنْ وَاقٍ", "35": "مَثَلُ الْجَنَّةِ الَّتِي وُعِدَ الْمُتَّقُونَ تَجْرِي مِنْ تَحْتِهَا الْأَنْهَارُ أُكُلُهَا دَائِمٌ وَظِلُّهَا تِلْكَ عُقْبَى الَّذِينَ اتَّقَوْا وَعُقْبَى الْكَافِرِينَ النَّارُ", "36": "وَالَّذِينَ آتَيْنَاهُمُ الْكِتَابَ يَفْرَحُونَ بِمَا أُنْزِلَ إِلَيْكَ وَمِنَ الْأَحْزَابِ مَنْ يُنْكِرُ بَعْضَهُ قُلْ إِنَّمَا أُمِرْتُ أَنْ أَعْبُدَ اللَّهَ وَلَا أُشْرِكَ بِهِ إِلَيْهِ أَدْعُو وَإِلَيْهِ مَآبِ", "37": "وَكَذَلِكَ أَنْزَلْنَاهُ حُكْمًا عَرَبِيًّا وَلَئِنِ اتَّبَعْتَ أَهْوَاءَهُمْ بَعْدَ مَا جَاءَكَ مِنَ الْعِلْمِ مَا لَكَ مِنَ اللَّهِ مِنْ وَلِيٍّ وَلَا وَاقٍ", "38": "وَلَقَدْ أَرْسَلْنَا رُسُلًا مِنْ قَبْلِكَ وَجَعَلْنَا لَهُمْ أَزْوَاجًا وَذُرِّيَّةً وَمَا كَانَ لِرَسُولٍ أَنْ يَأْتِيَ بِآيَةٍ إِلَّا بِإِذْنِ اللَّهِ لِكُلِّ أَجَلٍ كِتَابٌ", "39": "يَمْحُو اللَّهُ مَا يَشَاءُ وَيُثْبِتُ وَعِنْدَهُ أُمُّ الْكِتَابِ", "40": "وَإِنْ مَا نُرِيَنَّكَ بَعْضَ الَّذِي نَعِدُهُمْ أَوْ نَتَوَفَّيَنَّكَ فَإِنَّمَا عَلَيْكَ الْبَلَاغُ وَعَلَيْنَا الْحِسَابُ", "41": "أَوَلَمْ يَرَوْا أَنَّا نَأْتِي الْأَرْضَ نَنْقُصُهَا مِنْ أَطْرَافِهَا وَاللَّهُ يَحْكُمُ لَا مُعَقِّبَ لِحُكْمِهِ وَهُوَ سَرِيعُ الْحِسَابِ", "42": "وَقَدْ مَكَرَ الَّذِينَ مِنْ قَبْلِهِمْ فَلِلَّهِ الْمَكْرُ جَمِيعًا يَعْلَمُ مَا تَكْسِبُ كُلُّ نَفْسٍ وَسَيَعْلَمُ الْكُفَّارُ لِمَنْ عُقْبَى الدَّارِ", "43": "وَيَقُولُ الَّذِينَ كَفَرُوا لَسْتَ مُرْسَلًا قُلْ كَفَى بِاللَّهِ شَهِيدًا بَيْنِي وَبَيْنَكُمْ وَمَنْ عِنْدَهُ عِلْمُ الْكِتَابِ"}, "units": [{"aya": 1, "title": "سبب نزول: ﴿تلك آيات الكتاب﴾", "tabari": {"page": "13/406", "sarih": 0, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "﴿تلك آيات الكتاب﴾. يقول تعالى ذكره: تلك التي قصصت عليك خبرها، آيات الكتاب الذي أنزلته قبل هذا الكتاب الذي أنزلته إليك، إلى من أنزلته إليه من رسلي قبلك.", "taqdim": 1, "n_athar": 0, "qailun": [], "athar": []}, {"n": 2, "t": "عنى بذلك التوراة والإنجيل", "taqdim": 0, "n_athar": 2, "qailun": [["قتادة", "تابعي"], ["مجاهد", "تابعي"]], "athar": [38524, 38527, 38529, 38530, 38533, 38535]}]}, "mawaqif": [{"taliq": 3476, "mi": 0, "aya": 1, "alam": "ابن جرير", "fil": "وجه", "kind": "توجيه", "ref": "13/ 407", "qawl": "مجاهد وقتادة", "nass": "هذا هو الصحيح المطابق لتفسير مجاهد، وقتادة", "qawaid": [], "tabi": ""}, {"taliq": 3476, "mi": 0, "aya": 1, "alam": "ابن كثير", "fil": "وبنحوه", "kind": "موافقة", "ref": "8/ 101", "qawl": "", "nass": "هذا هو الصحيح المطابق لتفسير مجاهد، وقتادة", "qawaid": [], "tabi": "ابن جرير"}, {"taliq": 3476, "mi": 0, "aya": 1, "alam": "ابن جرير", "fil": "ذكر", "kind": "نقل", "ref": "", "qawl": "", "nass": "الخفض على العطف به على {الكتاب}، فيكون معنى الكلام حينئذ: تلك آيات التوراة والإنجيل والقرآن، ثم يبتدئ {الحق}، بمعنى: ذلك الحق، فيكون رفعه بمضمر من الكلام قد استغنى بدلالة الظاهر عليه منه", "qawaid": [], "tabi": ""}], "mushid": {"i": 1, "imgs": ["013_001_1.png"], "pages": [302], "n": 2, "rajih": [], "daif": [], "match": true}, "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 2, "title": "في تأويل قوله: ﴿رفع السماوات بغير عمد ترونها﴾", "tabari": {"page": "13/408", "sarih": 1, "tarjih": "وأولى الأقوال في ذلك بالصحة أن يقال كما قال الله جل ثناؤه: ﴿الله الذي رفع السماوات بغير عمد ترونها﴾. فهى مرفوعة بغير عمد نراها، كما قال ربنا جل ثناؤه، ولا خبر بغير ذلك، ولا حجة يجب التسليم لها بقول سواه.", "how": "صاغ الصواب بلفظه (عموم أو جمع أو قول مستقل)", "aqwal": [{"n": 1, "t": "تأويل ذلك: الله الذي رفع السماوات بعمد لا ترونها", "taqdim": 0, "n_athar": 7, "qailun": [["عكرمة", "تابعي"], ["مجاهد", "تابعي"], ["ابن عباس", "صحابي"]], "athar": [38539, 38540, 38541, 38542, 38550, 38552, 38554, 38555, 38559]}, {"n": 2, "t": "بل هي مرفوعة بغير عمد", "taqdim": 0, "n_athar": 2, "qailun": [["إياس بن معاوية", "تابعي"], ["قتادة", "تابعي"]], "athar": [38545, 38547, 38548, 38556, 38561]}]}, "mawaqif": [{"taliq": 3478, "mi": 1, "aya": 2, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "13/ 411", "qawl": "", "nass": "أن يقال كما قال الله -جل ثناؤه-: {الله الذي رفع السماوات بغير عمد ترونها}، فهي مرفوعة بغير عمد نراها، كما قال ربنا -جل ثناؤه-، ولا خبر بغير ذلك، ولا حجة يجب التسليم لها بقول سواه", "qawaid": ["ظاهر الآية ولفظها"], "tabi": ""}, {"taliq": 3478, "mi": 1, "aya": 2, "alam": "ابن عطية", "fil": "وجه", "kind": "توجيه", "ref": "5/ 169", "qawl": "الأول", "nass": "العمد", "qawaid": ["القرآن والنظائر", "الدلالة العقلية"], "tabi": ""}, {"taliq": 3478, "mi": 1, "aya": 2, "alam": "ابن كثير", "fil": "وكذا", "kind": "موافقة", "ref": "8/ 102", "qawl": "", "nass": "وهذا هو اللائق بالسياق، … فعلى هذا يكون قوله: {ترونها} تأكيدا لنفي ذلك، أي: هي مرفوعة بغير عمد كما ترونها، وهذا هو الأكمل في القدرة", "qawaid": [], "tabi": "ابن عطية"}, {"taliq": 3478, "mi": 1, "aya": 2, "alam": "ابن عطية", "fil": "انتقد", "kind": "نقد", "ref": "5/ 170", "qawl": "الأول", "nass": "وهذا كله ضعيف", "qawaid": [], "tabi": ""}], "mushid": {"i": 2, "imgs": ["013_002_1.png"], "pages": [302], "n": 2, "rajih": [], "daif": [], "match": true}, "mawsua": {"taliq": 3478, "masala": "معنى: {رفع السماوات بغير عمد ترونها}", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "الله الذي رفع السماوات بعمد لا ترونها", "ashab": "", "athar": []}, {"n": 2, "t": "رفع السماوات بغير عمد", "ashab": "", "athar": []}]}, "tags": {"m": {"1": [["ابن عطية", "w"], ["ابن كثير", "q"], ["ابن عطية", "d"]]}, "t": {"1": [["ابن عطية", "w"], ["ابن كثير", "q"], ["ابن عطية", "d"]]}, "gen": [["ابن جرير", "رجّح ولم يتعيّن القول آليًّا"]], "rules": {"ابن جرير": ["ظاهر الآية ولفظها"]}, "rulesD": {}}}, {"aya": 4, "title": "في وجه تذكيره إذا قرئ كذلك، وإنما ذلك خبر عن الجنات والأعناب والنخيل والزرع أنها تسقى بماء واحد", "tabari": {"page": "13/427", "sarih": 1, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "إذا قرئ ذلك بالتاء، فذلك على \"الأعناب\"، كما ذكر \"الأنعام\" في قوله: ﴿مما في بطونه﴾ [النحل: ٦٦]. وأنث بعد فقال: ﴿وعليها وعلى الفلك تحملون﴾ [المؤمنون: ٢٢، غافر: ٨٠]. فمن قال: ﴿يسقى﴾ بالياء جعل. \"الأعناب\" مما يذكر ويؤنث، مثل \"الأنعام\"", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}, {"n": 2, "t": "من قال: (تسقى). ذهب إلى تأنيث الزرع والجنات والنخيل، ومن ذكر ذهب إلى النبت : ذلك كله يسقى بماء واحد، أكله مختلف، حامض وحلو. ففى هذا آية", "taqdim": 0, "n_athar": 7, "qailun": [["مجاهد", "تابعي"], ["الضحاك", "تابعي"], ["ابن شوذب", ""]], "athar": [38590, 38591, 38592, 38593, 38599, 38600, 38605, 38606, 38609, 38610, 38617, 38618, 38620, 38627, 38629]}]}, "mawaqif": [], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 5, "title": "معنى: {وأولئك الأغلال في أعناقهم}", "mawsua": {"taliq": 3483, "masala": "معنى: {وأولئك الأغلال في أعناقهم}", "sigha": "ذكر احتمالين", "nasib": "ابن عطية", "aqwal": [{"n": 1, "t": "الحقيقة، وأنه أخبر عن كون الأغلال في أعناقهم في الآخرة، فهي كقوله تعالى: {إذ الأغلال في أعناقهم والسلاسل} [غافر: 71]", "ashab": "", "athar": []}, {"n": 2, "t": "أن يكون مجازا، وأنه أخبر عن كونهم مغللين عن الإيمان، فهي إذا تجري مجرى الطبع والختم على القلوب، وهي كقوله تعالى: {إنا جعلنا في أعناقهم أغلالا فهي إلى الأذقان فهم مقمحون} [يس: 8]». ثم نقل عن بعض الناس أن: «الأغلال هنا عبارة عن الأعمال، أي: أعمالهم الفاسدة في أعناقهم كالأغلال", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 3483, "mi": 1, "aya": 5, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "5/ 177", "qawl": "", "nass": "الحقيقة، وأنه أخبر عن كون الأغلال في أعناقهم في الآخرة، فهي كقوله تعالى: {إذ الأغلال في أعناقهم والسلاسل} [غافر: 71]", "qawaid": [], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 7, "title": "سبب نزول: ﴿ويقول الذين كفروا لولا أنزل عليه آية من ربه إنما أنت منذر ولكل قوم هاد﴾", "tabari": {"page": "13/439", "sarih": 0, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "يقول تعالى ذكره: ﴿ويقول الذين كفروا﴾ يا محمد، من قومك: ﴿لولا أنزل عليه آية من ربه﴾: هلا أنزل على محمد آية من ربه. يعنون: علامة وحجة له على نبوته، وذلك قولهم: ﴿لولا أنزل عليه كنز أو جاء معه ملك﴾ [هود:١٢]. يقول الله له: ﴿إنما أنت منذر﴾ لهم، تنذرهم بأس الله أن يحل بهم على شركهم، ﴿ولكل قوم هاد﴾. يقول: ولكل قوم إمام يأتمون به، وهاد يتقدمهم، فيهديهم إما إلى خير، وإما إلى شر، وأصله من هادى الفرس: وهو عنق", "taqdim": 1, "n_athar": 4, "qailun": [["قتادة", "تابعي"], ["أبي الضحى", "تابعي"]], "athar": [38659, 38673, 38675, 38683]}, {"n": 2, "t": "عنى بالهادي في هذا الموضع: الله", "taqdim": 0, "n_athar": 6, "qailun": [["سعيد بن جبير", "تابعي"], ["مجاهد", "تابعي"], ["ابن عباس", "صحابي"]], "athar": [38661, 38664, 38667, 38668, 38669, 38670, 38672, 38677, 38678]}, {"n": 3, "t": "الهادى في هذا الموضع، معناه: نبي", "taqdim": 0, "n_athar": 6, "qailun": [["مجاهد", "تابعي"], ["قتادة", "تابعي"], ["ابن زيد", "تابع التابعين"]], "athar": [38659, 38677, 38678, 38683, 38688]}, {"n": 4, "t": "بل عنى به: ولكل قوم قائد", "taqdim": 0, "n_athar": 3, "qailun": [["أبي صالح", "تابعي"], ["أبي العالية", "تابعي"], ["يحيى بن رافع", ""]], "athar": [38671, 38680, 38681, 38682]}, {"n": 5, "t": "هو علي بن أبى طالب، ﵁", "taqdim": 0, "n_athar": 1, "qailun": [], "athar": []}, {"n": 6, "t": "معناه: لكل قوم داع", "taqdim": 0, "n_athar": 1, "qailun": [["ابن عباس", "صحابي"]], "athar": [38661, 38664, 38667, 38668, 38669, 38670]}]}, "mawaqif": [{"taliq": 3485, "mi": 1, "aya": 7, "alam": "ابن عطية", "fil": "وجه", "kind": "توجيه", "ref": "5/ 179", "qawl": "الأول", "nass": "فيكون هذا المعنى يجري مع قوله عليه الصلاة والسلام: «بعثت إلى الأحمر والأسود", "qawaid": [], "tabi": ""}, {"taliq": 3485, "mi": 1, "aya": 7, "alam": "ابن جرير", "fil": "بين", "kind": "بيان", "ref": "13/ 443", "qawl": "", "nass": "ولكل قوم إمام يأتمون به، وهاد يتقدمهم، فيهديهم إما إلى خير، وإما إلى شر", "qawaid": ["اللغة", "عدم الدليل على غيره"], "tabi": ""}, {"taliq": 3485, "mi": 1, "aya": 7, "alam": "ابن عطية", "fil": "رجح", "kind": "ترجيح", "ref": "5/ 180", "qawl": "الأول", "nass": "والقول الأول أرجح ما تؤول في هذه الآية", "qawaid": ["لم يذكر مستندًا"], "tabi": ""}, {"taliq": 3485, "mi": 1, "aya": 7, "alam": "ابن تيمية", "fil": "رجح", "kind": "ترجيح", "ref": "4/ 82، 83", "qawl": "الثالث", "nass": "والصحيح: أن معناها: إنما أنت نذير كما أرسل من قبلك نذير، ولكل أمة نذير يهديهم، أي: يدعوهم، كما في قوله: {وإن من أمة إلا خلا فيها نذير} [فاطر: 24]، وهذا قول جماعة من المفسرين، مثل: قتادة، وعكرمة، وأبي الضحى، وعبد الرحمن بن زيد …", "qawaid": ["القرآن والنظائر", "اللغة"], "tabi": ""}], "mushid": {"i": 3, "imgs": ["013_003_1.png"], "pages": [302], "n": 6, "rajih": [], "daif": [], "match": true}, "mawsua": {"taliq": 3485, "masala": "المعني ب «الهاد»", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "هو رسول الله صلى الله عليه وسلم", "ashab": "", "athar": []}, {"n": 2, "t": "هو الله عز وجل", "ashab": "", "athar": []}, {"n": 3, "t": "معناه: نبي", "ashab": "", "athar": []}, {"n": 4, "t": "هو علي بن أبي طالب", "ashab": "", "athar": []}, {"n": 5, "t": "معناه: لكل قوم قائد", "ashab": "", "athar": []}, {"n": 6, "t": "معناه: لكل قوم داع", "ashab": "", "athar": []}]}, "tags": {"m": {"1": [["ابن عطية", "w"], ["ابن عطية", "r"]], "3": [["ابن تيمية", "r"]]}, "t": {"1": [["ابن عطية", "w"], ["ابن عطية", "r"]], "3": [["ابن تيمية", "r"]]}, "gen": [], "rules": {"ابن عطية": ["لم يذكر مستندًا"], "ابن تيمية": ["القرآن والنظائر", "اللغة"]}, "rulesD": {}}}, {"aya": 11, "title": "تأويل: ﴿من بين يديه ومن خلفه﴾", "tabari": {"page": "13/460", "sarih": 0, "tarjih": "وأولى التأويلين في ذلك بالصواب قول من قال: الهاء في قوله: ﴿له معقبات﴾. من ذكر \"من\" التي في قوله: ﴿ومن هو مستخف بالليل﴾. وأن المعقبات من بين يديه ومن خلفه، هي حرسه وجلاوزته كما قال ذلك من ذكرنا قوله.", "how": "رجّح قول فريق («قول من قال…»)", "aqwal": [{"n": 1, "t": "﴿من بين يديه ومن خلفه﴾. [يعنى بقوله: ﴿من بين يديه﴾: من قدام هذا المستخفى بالليل، والسارب بالنهار، ﴿ومن خلفه﴾] : من وراء ظهره.", "taqdim": 1, "n_athar": 14, "qailun": [["الحسن في هذه الآية", "تابعي"], ["كنانة العدوي", "تابعي"], ["مجاهد", "تابعي"], ["ابن عباس", "صحابي"], ["إبراهيم في هذه الآية", ""], ["إبراهيم", "تابعي"], ["أبى صالح", "تابعي"], ["قتادة", "تابعي"], ["ابن جريج", "تابع التابعين"]], "athar": [38747, 38748, 38750, 38751, 38754, 38756, 38757, 38758, 38759, 38760, 38761, 38762, 38763, 38764, 38765, 38766, 38769, 38770, 38771, 38772, 38779, 38780, 38785, 38786, 38787, 38788, 38789, 38790, 38791, 38795, 38796, 38797, 38798, 38801, 38802, 38805, 38806, 38807, 38814]}, {"n": 2, "t": "بل عنى بالمعقبات في هذا الموضع: الحرس الذي يتعاقب على الأمير", "taqdim": 0, "n_athar": 5, "qailun": [["ابن عباس", "صحابي"], ["شرقي", ""]], "athar": [38748, 38751, 38756, 38757, 38758, 38759, 38760, 38761, 38762, 38763, 38765, 38766, 38785, 38786, 38787, 38788, 38789, 38790, 38791, 38805, 38814]}]}, "mawaqif": [], "mushid": {"i": 4, "imgs": ["013_004_1.png"], "pages": [303], "n": 2, "rajih": [], "daif": [], "match": true}, "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 11, "title": "في معنى قوله: ﴿من أمر الله﴾", "tabari": {"page": "13/462", "sarih": 1, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "حفظهم إياه: من أمره. وقال بعضهم: ﴿يحفظونه من أمر الله﴾: بأمر الله", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}, {"n": 2, "t": "الذين يحفظونه هم الملائكة. ووجه قوله: بأمر الله. إلى معنى: أن حفظها إياه من أمر الله", "taqdim": 0, "n_athar": 6, "qailun": [["ابن عباس", "صحابي"], ["سعيد بن جبير", "تابعي"], ["مجاهد", "تابعي"], ["ابن جريج", "تابع التابعين"], ["إبراهيم", "تابعي"]], "athar": [38748, 38751, 38756, 38757, 38758, 38759, 38760, 38761, 38762, 38763, 38764, 38765, 38766, 38768, 38769, 38770, 38771, 38772, 38785, 38786, 38787, 38788, 38789, 38790, 38791, 38794, 38795, 38796, 38797, 38801, 38802, 38805, 38806, 38814]}, {"n": 3, "t": "عنى بذلك: يحفظونه بأمر الله", "taqdim": 0, "n_athar": 3, "qailun": [["قتادة", "تابعي"], ["مجاهد", "تابعي"]], "athar": [38747, 38750, 38770, 38771, 38772, 38780, 38796, 38797, 38798, 38807]}, {"n": 4, "t": "تحفظه الحرس من بنى آدم من أمر الله", "taqdim": 0, "n_athar": 2, "qailun": [["ابن عباس", "صحابي"], ["عكرمة", "تابعي"]], "athar": [38748, 38751, 38756, 38757, 38758, 38759, 38760, 38761, 38762, 38763, 38765, 38766, 38785, 38786, 38787, 38788, 38789, 38790, 38791, 38805, 38814]}, {"n": 5, "t": "معنى ذلك: يحفظونه من أمر الله، وأمر الله: الجن ومن يبغى أذاه ومكروهه قبل مجئ قضاء الله، فإذا جاء قضاؤه خلوا بينه وبينه", "taqdim": 0, "n_athar": 5, "qailun": [["إبراهيم", "تابعي"], ["مجاهد", "تابعي"], ["كعب الأحبار", "تابعي"], ["أبي مجلز", "تابعي"], ["أبي أمامة", "صحابي"]], "athar": [38755, 38769, 38770, 38771, 38772, 38784, 38792, 38793, 38795, 38796, 38797, 38806]}, {"n": 6, "t": "معنى ذلك: يحفظون عليه من الله", "taqdim": 0, "n_athar": 2, "qailun": [["ابن جريج", "تابع التابعين"], ["ابن زيد", "تابع التابعين"]], "athar": [38752, 38764, 38801, 38802, 38804]}]}, "mawaqif": [{"taliq": 3494, "mi": 0, "aya": 11, "alam": "ابن جرير", "fil": "وجه", "kind": "توجيه", "ref": "13/ 467", "qawl": "ابن جريج", "nass": "يعني ابن جريج بقوله: يحفظون عليه: الملائكة الموكلة بابن آدم، بحفظ حسناته وسيئاته، وهي المعقبات عندنا، تحفظ على ابن آدم حسناته وسيئاته من أمر الله، وعلى هذا القول يجب أن يكون معنى قوله: {من أمر الله}: أن الحفظة من أمر الله، أو تحفظ بأمر الله، ويجب أن تكون الهاء التي في قوله: {يحفظونه} وحدت وذكرت، وهي مراد بها الحسنات والسيئات، لأنها كناية عن ذكر", "qawaid": [], "tabi": ""}, {"taliq": 3494, "mi": 0, "aya": 11, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "5/ 187", "qawl": "", "nass": "أن يكون بمعنى: يحرسونه، ويذبون عنه، فالضمير معمول ليحفظ", "qawaid": [], "tabi": ""}, {"taliq": 3494, "mi": 0, "aya": 11, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "5/ 187", "qawl": "", "nass": "من جعل {يحفظونه} بمعنى: يحرسونه، كان معنى قوله: {من أمر الله} يراد به: المعقبات", "qawaid": [], "tabi": ""}, {"taliq": 3495, "mi": 0, "aya": 11, "alam": "ابن جرير", "fil": "انتقد", "kind": "نقد", "ref": "13/ 470", "qawl": "ابن زيد", "nass": "وهذا القول الذي قاله ابن زيد في تأويل هذه الآية قول بعيد من تأويل الآية، مع خلافه أقوال من ذكرنا قوله من أهل التأويل، وذلك أنه جعل الهاء في قوله: {له معقبات} من ذكر رسول الله صلى الله عليه وسلم، ولم يجر له في الآية التي قبلها ولا في التي قبل الأخرى ذكر", "qawaid": ["أقوال السلف", "السياق"], "tabi": ""}, {"taliq": 3495, "mi": 0, "aya": 11, "alam": "ابن عطية", "fil": "ووافقه", "kind": "موافقة", "ref": "5/ 185", "qawl": "", "nass": "وهذه الآية وإن كانت ألفاظها تنطبق على معنى القصة فيضعف القول أن النبي صلى الله عليه وسلم لم يتقدم له ذكر فيعود الضمير في {له} عليه", "qawaid": [], "tabi": "ابن جرير"}], "mushid": {"i": 6, "imgs": ["013_006_1.png", "013_006_2.png"], "pages": [303, 304], "n": 2, "rajih": [], "daif": [], "match": false}, "tags": {"m": {}, "t": {"6": [["ابن جرير", "d"], ["ابن عطية", "q"]]}, "gen": [], "rules": {}, "rulesD": {"ابن جرير": ["أقوال السلف", "السياق"]}}}, {"aya": 11, "title": "في معنى قوله: ﴿ومن هو مستخف بالليل وسارب بالنهار﴾", "tabari": {"page": "13/472", "sarih": 1, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "معنى قوله: ﴿ومن هو مستخف بالليل﴾: ومن هو ظاهر بالليل، من قولهم: خفيت الشئ، إذا أظهرته، وكما قال امرؤ القيس :", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}, {"n": 2, "t": "إنما معنى ذلك ﴿ومن هو مستخف﴾، أي مستتر بالليل، من الاستخفاء، ﴿وسارب بالنهار﴾، وذاهب بالنهار، من قولهم: سربت الإبل إلى الرعى. وذلك ذهابها إلى المراعى، وخروجها إليها وقيل: إن السروب بالعشي، والسروح بالغداة", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}]}, "mawaqif": [], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 11, "title": "في تأنيث \"معقبات\"، وهى صفة لغير الإناث", "tabari": {"page": "13/472", "sarih": 1, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "إنما أنثت لكثرة ذلك منها، نحو نسابة وعلامة، ثم ذكر؛ لأن المعنى مذكر، فقال: يحفظونه", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}, {"n": 2, "t": "إنما هي ملائكة معقبة، ثم جمعت معقبات، فهو جمع جمع، ثم قيل: يحفظونه؛ لأنه للملائكة", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}]}, "mawaqif": [], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 11, "title": "في معناه", "tabari": {"page": "13/474", "sarih": 1, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "معناه: له معقبات من أمر الله يحفظونه، وليس من أمره، إنما هو تقديم وتأخير. قال: ويكون يحفظونه ذلك الحفظ من أمر الله وبإذنه، كما تقول للرجل: أجبتك من دعائك إياى، وبدعائك إياى", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}, {"n": 2, "t": "معنى ذلك: يحفظونه عن أمر الله، كما قالوا: أطعمنى من جوع وعن جوع، وكسانى من عرى وعن عرى", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}]}, "mawaqif": [], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 11, "title": "معنى: {له معقبات} في هذه الآية من جهتين: الأولى: اختلف في مرجع الضمير في {له}", "mawsua": {"taliq": 3492, "masala": "معنى: {له معقبات} في هذه الآية من جهتين: الأولى: اختلف في مرجع الضمير في {له}", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "أنها ترجع إلى الله تعالى", "ashab": "", "athar": []}, {"n": 2, "t": "أنها ترجع إلى النبي صلى الله عليه وسلم", "ashab": "", "athar": []}, {"n": 3, "t": "أنها ترجع إلى الملك من ملوك الدنيا. والثانية: اختلف في معنى: «المعقبات» على قولين: الأول: الملائكة التي تتعقب على العبد لحفظه وحفظ أعماله. الثاني: الحرس الذي يتعاقب على الأمير", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 3492, "mi": 1, "aya": 11, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "13/ 461 - 462", "qawl": "", "nass": "الهاء في قوله: {له معقبات} من ذكر", "qawaid": ["اللغة", "السياق"], "tabi": ""}, {"taliq": 3492, "mi": 1, "aya": 11, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "5/ 184 - 185", "qawl": "بعود الضمير", "nass": "", "qawaid": [], "tabi": ""}, {"taliq": 3492, "mi": 1, "aya": 11, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "", "qawl": "", "nass": "في {له} للعبد المؤمن، على معنى: جعل الله له", "qawaid": ["الدلالة العقلية"], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [["ابن جرير", "رجّح ولم يتعيّن القول آليًّا"]], "rules": {"ابن جرير": ["اللغة", "السياق"]}, "rulesD": {}}}, {"aya": 13, "title": "تأويل: ﴿ويرسل الصواعق فيصيب بها من يشاء﴾", "tabari": {"page": "13/480", "sarih": 0, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "وأما قوله: ﴿ويرسل الصواعق فيصيب بها من يشاء﴾، فقد بينا معنى الصاعقة فيما مضى، بما أغنى عن إعادته، بما فيه الكفاية من الشواهد، وذكرنا ما فيها من الرواية .", "taqdim": 1, "n_athar": 4, "qailun": [["مجاهد", "تابعي"], ["أنس بن مالك", "صحابي"]], "athar": [38846, 38869, 38893, 38894, 38895]}, {"n": 2, "t": "نزلت في رجل من الكفار أنكر القرآن، وكذب النبي ﷺ", "taqdim": 0, "n_athar": 1, "qailun": [["قتادة", "تابعي"]], "athar": [38873, 38900]}, {"n": 3, "t": "نزلت في أربد أخى لبيد بن ربيعة، وكان هم بقتل رسول الله ﷺ هو وعامر بن الطفيل", "taqdim": 0, "n_athar": 1, "qailun": [["ابن جريج", "تابع التابعين"]], "athar": [38874]}]}, "mawaqif": [{"taliq": 3500, "mi": 0, "aya": 13, "alam": "ابن جرير", "fil": "وجه", "kind": "توجيه", "ref": "13/ 484 - 485", "qawl": "ابن عباس", "nass": "والقول الذي ذكرناه عن قتادة في تأويل المحال أنه الحيلة، والقول الذي ذكره ابن جريج عن ابن عباس يدلان على أنهما كانا يقرآن: (وهو شديد المحال) بفتح الميم؛ لأن الحيلة لا يأتي مصدرها محالا -بكسر الميم-، ولكن قد يأتي على تقدير المفعلة منها، فيكون محالة، ومن ذلك قولهم: المرء يعجز لا محالة. والمحالة في هذا الموضع: المفعلة من الحيلة، فأما بكسر الميم فلا تكون إلا مصدرا من: ماحلت فلانا أماحله محالا، والمماحلة بعيدة المعنى من الحيلة، ولا أعلم أحدا قرأه بفتح الميم", "qawaid": ["أقوال السلف"], "tabi": ""}], "mushid": {"i": 7, "imgs": ["013_007_1.png"], "pages": [304], "n": 3, "rajih": [], "daif": [], "match": true}, "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 14, "title": "تأويل: ﴿لا يستجيبون لهم بشيء﴾", "tabari": {"page": "13/489", "sarih": 0, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "﴿لا يستجيبون لهم بشيء﴾. يقول: لا تجيب هذه الآلهة التي يدعوها هؤلاء المشركون آلهة، بشيء يريدونه، من نفع أو دفع ضر ، ﴿إلا كباسط كفيه إلى الماء﴾. يقول: لا ينفع داعى الآلهة دعاؤه إياها، إلا كما ينفع باسط كفيه إلى الماء بسطه إياهما إليه من غير أن يرفعه إليه في إناء ، ولكن ليرتفع إليه بدعائه إياه ، وإشارته إليه، وقبضه عليه، والعرب تضرب لمن سعى فيما لا يدركه مثلا بالقابض على الماء، كما قال بعضهم :", "taqdim": 1, "n_athar": 6, "qailun": [["مجاهد", "تابعي"], ["قتادة", "تابعي"]], "athar": [38907, 38914, 38915, 38916]}, {"n": 2, "t": "معنى ذلك: والذين يدعون من دونه لا يستجيبون لهم بشيء، إلا كباسط كفيه إلى الماء؛ ليتناول خياله فيه، وما هو ببالغ ذلك", "taqdim": 0, "n_athar": 1, "qailun": [["ابن عباس", "صحابي"]], "athar": [38906, 38912, 38913, 38922]}, {"n": 3, "t": "ثنى أبى، قال: ثنى عمى، قال: ثنى أبى، عن أبيه، عن ابن عباس قوله: ﴿والذين يدعون من دونه لا يستجيبون لهم بشيء﴾ إلى: ﴿وما دعاء الكافرين إلا في ضلال﴾. يقول: مثل الأوثان الذين يعبدون من دون الله، كمثل رجل قد بلغه العطش، حتى كربه الموت، وكفاه في الماء قد وضعهما لا يبلغان فاه. يقول الله: لا تستجيب له الآلهة، ولا تنفع الذين يعبدونها، حتى يبلغ كفا هذا فاه، وما هما ببالغتين فاه أبدا", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}, {"n": 4, "t": "ثنا محمد بن ثور، عن معمر، عن قتادة: ﴿إلا كباسط كفيه إلى الماء ليبلغ فاه﴾ وليس الماء ببالغ فاه ما قام باسطا كفيه لا يقبضهما، ﴿وما هو ببالغه وما دعاء الكافرين إلا في ضلال﴾. قال: هذا مثل ضربه الله لمن اتخذ من دون الله إلها أنه غير نافعه، ولا يدفع عنه سوءا، حتى يموت على ذلك", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}]}, "mawaqif": [], "mushid": {"i": 8, "imgs": ["013_008_1.png"], "pages": [304], "n": 4, "rajih": [1], "daif": [], "match": true}, "tags": {"m": {}, "t": {"1": [["ابن جرير", "r"]]}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 17, "title": "تأويل: ﴿أنزل من السماء ماء فسالت أودية بقدرها فاحتمل السيل زبدا رابيا ومما يوقدون عليه في النار اب﴾", "tabari": {"page": "13/504", "sarih": 0, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "وعنى بقوله: ﴿رابيا﴾: عاليا منتفخا، من قولهم: ربا الشئ يربو ربوا فهو راب. ومنه قيل للنشز من الأرض كهيئة الأكمة: رابية. ومنه قول الله تعالى: ﴿اهتزت وربت﴾ [الحج: ٥]، [فصلت: ٣٩].", "taqdim": 1, "n_athar": 12, "qailun": [["ابن عباس", "صحابي"], ["ابن جريج", "تابع التابعين"], ["مجاهد", "تابعي"], ["قتادة", "تابعي"], ["ابن زيد", "تابع التابعين"], ["عطاء", "تابعي"]], "athar": [38955, 38956, 38957, 38958, 38959, 38960, 38962, 38963, 38964, 38965, 38968]}, {"n": 2, "t": "﴿فيذهب جفاء﴾ بمعنى جفئا؛ لأنه مصدر من قول القائل: جفأ الوادى غثاءه جفاء . فخرج مخرج الاسم وهو مصدر. كذلك تفعل العرب في مصدر كل ما كان من فعل شيء اجتمع بعضه إلى بعض كالقماش والدقاق والحطام والغثاء. تخرجه على مذهب الاسم، كما فعلت ذلك في قولهم: أعطيته عطاء، بمعنى الإعطاء. ولو أريد من القماش المصدر على الصحة لقيل: قد قمشته قمشا", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}]}, "mawaqif": [], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 20, "title": "الآية يحتمل", "mawsua": {"taliq": 3509, "masala": "الآية يحتمل", "sigha": "ذكر احتمالين", "nasib": "ابن عطية", "aqwal": [{"n": 1, "t": "ما", "ashab": "قتادة: من أن يراد به جنس المواثيق", "athar": []}, {"n": 2, "t": "أن يشير إلى ميثاق معين، وهو الذي أخذه الله على عباده وقت مسحه على ظهر أبيهم آدم عليه السلام", "ashab": "مقاتل", "athar": [38991]}]}, "mawaqif": [{"taliq": 3509, "mi": 1, "aya": 20, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "5/ 199", "qawl": "مقاتل", "nass": "", "qawaid": [], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 28, "title": "معنى ذكر الله الوارد في الآية", "mawsua": {"taliq": 3519, "masala": "معنى ذكر الله الوارد في الآية", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "ذكر الله على الإطلاق فبه تسكن القلوب، ويدخل في ضمنه: الحلف، فإذا حلف الرجل لرجل بالله صدقه واطمأن لذكر الله", "ashab": "", "athar": []}, {"n": 2, "t": "ذكر الله هنا القرآن", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 3519, "mi": 1, "aya": 28, "alam": "ابن القيم", "fil": "رجح", "kind": "ترجيح", "ref": "2/ 88", "qawl": "بأنه القرآن", "nass": "فإن القلب لا يطمئن إلا بالإيمان واليقين، ولا سبيل إلى حصول الإيمان واليقين إلا من القرآن، فإن سكون القلب وطمأنينته من يقينه، واضطرابه وقلقه من شكه، والقرآن هو المحصل لليقين الدافع للشكوك والظنون والأوهام، فلا تطمئن قلوب المؤمنين إلا به، وهذا القول هو المختار", "qawaid": ["الدلالة العقلية"], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [["ابن القيم", "رجّح ولم يتعيّن القول آليًّا"]], "rules": {"ابن القيم": ["الدلالة العقلية"]}, "rulesD": {}}}, {"aya": 29, "title": "في تأويل قوله: ﴿طوبى لهم﴾", "tabari": {"page": "13/519", "sarih": 1, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "معناه: نعم ما لهم", "taqdim": 0, "n_athar": 3, "qailun": [["عمرو بن نافع", ""], ["عكرمة", "تابعي"]], "athar": []}, {"n": 2, "t": "معناه: غبطة لهم", "taqdim": 0, "n_athar": 2, "qailun": [["الضحاك", "تابعي"]], "athar": [39107, 39130]}, {"n": 3, "t": "معناه: فرح وقرة عين", "taqdim": 0, "n_athar": 1, "qailun": [["ابن عباس", "صحابي"]], "athar": [39088, 39097, 39098, 39099, 39100]}, {"n": 4, "t": "معناه: حسنى لهم", "taqdim": 0, "n_athar": 2, "qailun": [["قتادة", "تابعي"]], "athar": [39120, 39121]}, {"n": 5, "t": "معناه: خير لهم", "taqdim": 0, "n_athar": 2, "qailun": [["إبراهيم", "تابعي"]], "athar": [39105, 39106]}, {"n": 6, "t": "﴿طوبى لهم﴾: اسم من أسماء الجنة. ومعنى الكلام: الجنة لهم", "taqdim": 0, "n_athar": 7, "qailun": [["ابن عباس", "صحابي"], ["سعيد بن مسجوح", ""], ["عكرمة", "تابعي"], ["مجاهد", "تابعي"]], "athar": [39088, 39097, 39098, 39099, 39100, 39108, 39109, 39110, 39126, 39129]}, {"n": 7, "t": "﴿طوبى لهم﴾: شجرة في الجنة", "taqdim": 0, "n_athar": 12, "qailun": [["موسى بن سالم", "تابع التابعين"], ["أبي هريرة", "صحابي"], ["شهر بن حوشب", "تابعي"], ["شمر بن عطية", ""], ["مغيث بن سمى", ""], ["لها", ""], ["حماد", "تابعي"], ["زيد", "صحابي"], ["له", ""]], "athar": [39096, 39115, 39119, 39124, 39127]}]}, "mawaqif": [], "mushid": {"i": 9, "imgs": ["013_009_1.png"], "pages": [305], "n": 7, "rajih": [7], "daif": [], "match": true}, "tags": {"m": {}, "t": {"7": [["ابن جرير", "r"]]}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 31, "title": "في معنى ذلك ﴿ولو أن قرآنا سيرت به الجبال أو قطعت به الأرض أو كلم به الموتى بل لله الأمر جميعا﴾", "tabari": {"page": "13/531", "sarih": 1, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "معناه: وهم يكفرون بالرحمن ولو أن قرآنا سيرت به الجبال. أي: يكفرون بالله ولو سير لهم الجبال بهذا القرآن. وقالوا: هو من المؤخر الذي معناه التقديم، وجعلوا جواب \"لو\" مقدما قبلها. وذلك أن الكلام على معنى قبلهم: ولو أن هذا القرآن [سيرت به] الجبال أو قطعت به الأرض لكفروا بالرحمن", "taqdim": 0, "n_athar": 5, "qailun": [["ابن عباس", "صحابي"], ["مجاهد", "تابعي"], ["ابن جريج", "تابع التابعين"]], "athar": [39142, 39143, 39144, 39146, 39163, 39166, 39167, 39168, 39169, 39170, 39172, 39184, 39185, 39186, 39187, 39188, 39189, 39195, 39196, 39197, 39198, 39199, 39205, 39206]}, {"n": 2, "t": "بل قوله : ﴿ولو أن قرآنا سيرت به الجبال﴾. كلام مبتدأ، منقطع عن قوله: ﴿وهم يكفرون بالرحمن﴾. قال: وجواب \"لو\" محذوف، استغنى بمعرفة السامعين المراد من الكلام عن ذكر جوابها. قالوا: والعرب تفعل ذلك كثيرا، ومنه قول امرئ القيس :", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}, {"n": 3, "t": "نحو معنى ذلك", "taqdim": 0, "n_athar": 4, "qailun": [["قتادة", "تابعي"], ["ابن زيد", "تابع التابعين"]], "athar": [39149, 39150, 39156, 39159, 39160, 39162, 39175, 39176, 39177, 39180, 39182, 39190, 39191, 39193, 39203, 39208]}]}, "mawaqif": [{"taliq": 3523, "mi": 1, "aya": 31, "alam": "ابن جرير", "fil": "وجه", "kind": "توجيه", "ref": "13/ 531", "qawl": "الأول", "nass": "ولو أن هذا القرآن سيرت به الجبال أو قطعت به الأرض لكفروا بالرحمن", "qawaid": [], "tabi": ""}, {"taliq": 3523, "mi": 1, "aya": 31, "alam": "ابن عطية", "fil": "وبنحوه", "kind": "موافقة", "ref": "5/ 205", "qawl": "", "nass": "وتتضمن الآية على هذا تعظيم القرآن، وهذا قول حسن يحرز فصاحة الآية، وقوله: {بل لله الأمر جميعا} يعضده، ويترتب مع الآخرين", "qawaid": [], "tabi": "ابن جرير"}], "mushid": {"i": 10, "imgs": ["013_010_1.png"], "pages": [305], "n": 2, "rajih": [], "daif": [], "match": false}, "mawsua": {"taliq": 3523, "masala": "جواب: {لو} في الآية", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "أن جوابها مقدم متعلق بقوله تعالى: {وهم يكفرون بالرحمن}", "ashab": "", "athar": []}, {"n": 2, "t": "أن جوابها محذوف، تقديره: لكان هذا القرآن", "ashab": "", "athar": []}, {"n": 3, "t": "أن جوابها محذوف، تقديره: لو كان هذا كله لما ءامنوا", "ashab": "", "athar": []}]}, "tags": {"m": {"1": [["ابن جرير", "w"], ["ابن عطية", "q"]]}, "t": {"2": [["ابن جرير", "w"], ["ابن عطية", "q"]]}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 31, "title": "تأويل: ﴿ولا يزال الذين كفروا تصيبهم بما صنعوا قارعة أو تحل قريبا من دارهم حتى يأتي وعد الله إن الل﴾", "tabari": {"page": "13/543", "sarih": 0, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "يقول تعالى ذكره: ﴿ولا يزال﴾ يا محمد ﴿الذين كفروا﴾ من قومك ﴿تصيبهم بما صنعوا﴾ من كفرهم بالله، وتكذيبهم إياك، وإخراجهم لك من بين أظهرهم، ﴿قارعة﴾. وهى ما يقرعهم من البلاء والعذاب والنقم، بالقتل أحيانا، وبالجدوب والقحط أحيانا، ﴿أو تحل﴾ أنت يا محمد. يقول: أو تنزل أنت ﴿قريبا من دارهم﴾ بجيشك وأصحابك ﴿حتى يأتي وعد الله﴾ الذي وعدك فيهم. وذلك ظهورك عليهم، وفتحك أرضهم، وقهرك إياهم بالسيف، ﴿إن الله لا يخلف ال", "taqdim": 1, "n_athar": 15, "qailun": [["ابن عباس", "صحابي"], ["عكرمة", "تابعي"], ["مجاهد", "تابعي"], ["قتادة", "تابعي"], ["ابن زيد", "تابع التابعين"]], "athar": [39142, 39143, 39144, 39146, 39149, 39150, 39156, 39159, 39160, 39162, 39163, 39166, 39167, 39169, 39170, 39172, 39175, 39176, 39177, 39180, 39182, 39184, 39185, 39186, 39187, 39188, 39189, 39190, 39191, 39193, 39195, 39196, 39197, 39198, 39199, 39203, 39205, 39206, 39208]}, {"n": 2, "t": "معنى قوله: ﴿أو تحل قريبا من دارهم﴾: تحل القارعة قريبا من دارهم", "taqdim": 0, "n_athar": 2, "qailun": [["قتادة", "تابعي"], ["الحسن", "تابعي"]], "athar": [39149, 39150, 39159, 39160, 39175, 39176, 39177, 39182, 39190, 39191, 39201, 39203, 39207, 39208]}, {"n": 3, "t": "﴿حتى يأتي وعد الله﴾: هو يوم القيامة", "taqdim": 0, "n_athar": 1, "qailun": [["الحسن", "تابعي"]], "athar": [39201, 39207]}]}, "mawaqif": [{"taliq": 3525, "mi": 1, "aya": 31, "alam": "ابن كثير", "fil": "رجح", "kind": "ترجيح", "ref": "8/ 152", "qawl": "الثاني", "nass": "وهذا هو الظاهر من السياق", "qawaid": ["السياق"], "tabi": ""}], "mushid": {"i": 11, "imgs": ["013_011_1.png"], "pages": [305], "n": 2, "rajih": [1], "daif": [], "match": false}, "mawsua": {"taliq": 3525, "masala": "قوله تعالى: {أو تحل قريبا من دارهم}", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "أنه رسول الله صلى الله عليه وسلم، فالمعنى: أو تحل أنت، يا محمد", "ashab": "أكثر السلف", "athar": []}, {"n": 2, "t": "أنها القارعة", "ashab": "الحسن", "athar": [39201]}]}, "tags": {"m": {"2": [["ابن كثير", "r"]]}, "t": {}, "gen": [], "rules": {"ابن كثير": ["السياق"]}, "rulesD": {}}}, {"aya": 35, "title": "في مرافع \"المثل\"", "tabari": {"page": "13/552", "sarih": 1, "tarjih": "قال أبو جعفر: وأولى الأقوال في ذلك بالصواب أن يقال: ذكر المثل فقال: ﴿مثل الجنة﴾. والمراد الجنة، ثم وصفت الجنة بصفتها، وذلك أن مثلها إنما هو صفتها، وليست صفتها شيئا غيرها. وإذ كان ذلك كذلك، ثم ذكر المثل، فقيل: ﴿مثل الجنة﴾، ومثلها صفتها وصفة الجنة، فكان وصفها كوصف المثل، وكان كأن الكلام جرى بذكر الجنة، فقيل: الجنة تجرى من تحتها الأنهار. كما قال الشاعر :", "how": "صاغ الصواب بلفظه (عموم أو جمع أو قول مستقل)", "aqwal": [{"n": 1, "t": "الرافع للمثل قوله: ﴿تجري من تحتها الأنهار﴾ في المعنى، وقال: هو كما تقول: حلية فلان أسمر و كذا وكذا. فليس الأسمر بمرفوع بالحلية، إنما هو ابتداء، أي: هو أسمر، هو كذا. قال: ولو دخل \"أن\" في مثل هذا كان صوابا. قال: ومثله في الكلام: مثلك أنك كذا، وأنك كذا. وقوله: (فلينظر الإنسان إلى طعامه (٢٤) أنا﴾ . [عبس: ٢٤، ٢٥] من وجه: ﴿مثل الجنة التي وعد المتقون فيها﴾ [محمد: ١٥]. ومن قال: ﴿أنا صببنا الماء﴾. أظهر الاسم؛ لأنه مردود على ا", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}, {"n": 2, "t": "معنى ذلك: صفة الجنة. قال: ومنه قول الله تعالى: ﴿وله المثل الأعلى﴾ [الروم: ٢٧]. معناه: ولله الصفة العليا. قال: فمعنى الكلام في قوله: ﴿مثل الجنة التي وعد المتقون تجرى من تحتها الأنهار﴾. أو: ﴿فيها أنهار﴾. كأنه قال: وصف الجنة صفة تجرى من تحتها الأنهار، أو صفة فيها أنهار. والله أعلم", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}, {"n": 3, "t": "هو من المكفوف عن خبره. قال: والعرب تفعل ذلك. قال: وله معنى آخر: للذين استجابوا لربهم الحسنى مثل الجنة، موصول، صفة لها على الكلام الأول", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}]}, "mawaqif": [], "mushid": {"i": 12, "imgs": ["013_012_1.png"], "pages": [306], "n": 2, "rajih": [1], "daif": [], "match": false}, "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 38, "title": "معنى قوله تعالى: {لكل أجل كتاب}", "mawsua": {"taliq": 3527, "masala": "معنى قوله تعالى: {لكل أجل كتاب}", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "لكل أجل من آجال الخلق كتاب عند الله", "ashab": "الحسن", "athar": [39266]}, {"n": 2, "t": "أنه من المقدم والمؤخر، والمعنى: لكل كتاب ينزل من السماء أجل", "ashab": "الضحاك، ومقاتل", "athar": [39265, 39267]}]}, "mawaqif": [{"taliq": 3527, "mi": 1, "aya": 38, "alam": "ابن جرير", "fil": "نقل", "kind": "نقل", "ref": "13/ 559", "qawl": "الضحاك", "nass": "وهذا على هذا القول نظير قول الله: {وجآءت سكرة الموت بالحق} [ق: 19]، وكان أبو بكر رضي الله عنهما يقرؤه: (وجآءت سكرة الحق بالموت)، وذلك أن سكرة الموت تأتي بالحق، والحق يأتي بها، فكذلك الأجل له كتاب، وللكتاب أجل", "qawaid": [], "tabi": ""}, {"taliq": 3527, "mi": 1, "aya": 38, "alam": "ابن عطية", "fil": "نقله", "kind": "نقل", "ref": "5/ 211 - 212", "qawl": "", "nass": "وهذا العكس غير لازم، ولا وجه له؛ إذ المعنى تام في ترتيب القرآن، بل يمكن هدم قولهما بأن الأشياء التي كتبها الله تعالى أزلية باقية كتنعيم أهل الجنة وغيره يوجد كتابها ولا أجل له", "qawaid": ["الدلالة العقلية"], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 39, "title": "في تأويل ذلك ﴿يمحو الله ما يشاء ويثبت وعنده أم الكتاب﴾", "tabari": {"page": "13/559", "sarih": 1, "tarjih": "وأولى الأقوال التي ذكرت في ذلك بتأويل الآية وأشبهها بالصواب، القول الذي ذكرناه عن الحسن ومجاهد، وذلك أن الله تعالى ذكره توعد المشركين الذين سألوا رسول الله ﷺ الآيات بالعقوبة، وتهددهم بها، وقال لهم: ﴿وما كان لرسول أن يأتي بآية إلا بإذن الله لكل أجل كتاب﴾. يعلمهم بذلك أن لقضائه فيهم أجلا مثبتا في كتاب، هم مؤخرون إلى وقت مجئ ذلك الأجل، ثم قال لهم: فإذا جاء ذلك الأجل، [محى الله ما شاء] ، ممن قد دنا أجله، وانقطع رزقه، أو حان هلاكه، أو اتضاعه من رفعة، أو هلاك مال، فيقضى ذلك في خلقه، فذلك محوه، ويثبت ما شاء ممن بقى أجله، وأكله ورزقه، فيتركه على ما هو عليه، فلا يمحوه.", "how": "صاغ الصواب بلفظه (عموم أو جمع أو قول مستقل)", "aqwal": [{"n": 1, "t": "يمحو الله ما يشاء من أمور عباده فيغيره، إلا الشقاء والسعادة، فإنهما لا يغيران", "taqdim": 0, "n_athar": 11, "qailun": [["ابن عباس", "صحابي"], ["مجاهد", "تابعي"], ["منصور", ""]], "athar": [39270, 39271, 39273, 39274, 39275, 39284, 39285, 39286, 39287, 39288, 39289, 39296, 39297, 39298, 39299, 39320, 39321, 39322, 39324]}, {"n": 2, "t": "معنى ذلك: أن الله يمحو ما يشاء ويثبت من كتاب سوى أم الكتاب الذي لا يغير منه شيء", "taqdim": 0, "n_athar": 12, "qailun": [["ابن عباس", "صحابي"], ["عكرمة", "تابعي"], ["شقيق", ""], ["أبي وائل", "تابعي"], ["عبد الله", "صحابي"], ["إبراهيم", "تابعي"]], "athar": [39273, 39274, 39275, 39276, 39282, 39283, 39284, 39285, 39286, 39287, 39288, 39289, 39293, 39320, 39321, 39322]}, {"n": 3, "t": "بل معنى ذلك أن الله ينسخ ما يشاء من أحكام كتابه، ويثبت ما يشاء منها فلا ينسخه", "taqdim": 0, "n_athar": 5, "qailun": [["ابن عباس", "صحابي"], ["قتادة", "تابعي"], ["ابن زيد", "تابع التابعين"], ["ابن جريج", "تابع التابعين"]], "athar": [39273, 39274, 39275, 39284, 39285, 39286, 39287, 39288, 39289, 39310, 39317, 39319, 39320, 39321, 39322, 39329, 39331, 39333]}, {"n": 4, "t": "معنى ذلك أنه يمحو من قد حان أجله، ويثبت من لم يجئ أجله إلى أجله", "taqdim": 0, "n_athar": 5, "qailun": [["الحسن", "تابعي"]], "athar": [39305, 39306, 39307, 39308]}, {"n": 5, "t": "معنى ذلك: ويغفر ما يشاء من ذنوب عباده، ويترك ما يشاء فلا يغفر", "taqdim": 0, "n_athar": 1, "qailun": [["سعيد", "تابعي"]], "athar": [39294, 39295]}]}, "mawaqif": [{"taliq": 3530, "mi": 1, "aya": 39, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "569 - 571", "qawl": "الخامس", "nass": "وذلك أن الله -تعالى ذكره- توعد المشركين الذين سألوا رسول الله صلى الله عليه وسلم الآيات بالعقوبة، وتهددهم بها، وقال لهم: {وما كان لرسول أن يأتي بآية إلا بإذن الله لكل أجل كتاب}، يعلمهم بذلك أن لقضائه فيهم أجلا مثبتا في كتاب، هم مؤخرون إلى وقت مجيء ذلك الأجل. ثم قال لهم: فإذا جاء ذلك الأجل محى الله ما شاء ممن قد دنا أجله وانقطع رزقه، أو حان هلاكه، أو اتضاعه من رفعة، أو هلاك مال، فيقضي ذلك في خلقه، فذلك محوه، ويثبت ما شاء ممن بقي أجله ورزقه وأكله، فيتركه على ما هو عليه، فلا يمحوه. وبهذا المعنى جاء الأثر عن رسول الله صلى الله عليه وسلم", "qawaid": ["السياق", "السنة"], "tabi": ""}, {"taliq": 3530, "mi": 1, "aya": 39, "alam": "ابن عطية", "fil": "رجح", "kind": "ترجيح", "ref": "5/ 212", "qawl": "الثاني", "nass": "وتخبط الناس في معنى هذه الألفاظ، والذي يتلخص من مسلكها أن نعتقد أن الأشياء التي قدرها الله تعالى في الأزل وعلمها بحال ما لا يصح فيها محو ولا تبديل، وهي التي كتبت في أم الكتاب، وسبق بها القضاء، وهذا مروي عن ابن عباس وغيره من أهل العلم، وأما الأشياء التي قد أخبر الله تعالى أنه يبدل فيها وينقل كغفر الذنوب بعد تقريرها، وكنسخ آية بعد تلاوتها واستقرار حكمها، ففيها يقع المحو والتثبيت فيما يقيده الحفظة ونحو ذلك، وأما إذا رد الأمر للقضاء والقدر فقد محا الله ما محا، وثبت ما ثبت", "qawaid": ["العموم"], "tabi": ""}, {"taliq": 3530, "mi": 1, "aya": 39, "alam": "ابن كثير", "fil": "علق", "kind": "تعليق", "ref": "8/ 165", "qawl": "الأول", "nass": "ومعنى هذه الأقوال: أن الأقدار ينسخ الله ما يشاء منها، ويثبت منها ما يشاء، وقد يستأنس لهذا القول بما رواه الإمام أحمد: حدثنا وكيع، حدثنا سفيان وهو الثوري، عن عبد الله بن عيسى، عن عبد الله بن أبي الجعد، عن ثوبان، قال: قال رسول الله صلى الله عليه وسلم: «إن الرجل ليحرم الرزق بالذنب يصيبه، ولا يرد القدر إلا الدعاء، ولا يزيد في العمر إلا البر»", "qawaid": [], "tabi": ""}], "mushid": {"i": 13, "imgs": ["013_013_1.png"], "pages": [306], "n": 6, "rajih": [4], "daif": [], "match": false}, "mawsua": {"taliq": 3530, "masala": "معنى المحو والإثبات المذكور في الآية", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "أنه عام في كل ما أراد الله محوه أو إثباته من رزق وأجل وسعادة وشقاوة وغير ذلك", "ashab": "عمر، وابن مسعود، وابن عباس من طريق العوفي، وقول كعب الأحبار، وأبي وائل، والضحاك", "athar": [39281, 39282, 39283, 39293, 39300, 39301]}, {"n": 2, "t": "يمحو الله ما يشاء من أمور عباده فيغيره، إلا الشقاء والسعادة فإنهما لا يغيران", "ashab": "ابن عباس من طريق سعيد بن جبير، ومجاهد من طريق منصور", "athar": []}, {"n": 3, "t": "يمحو الله ما يشاء ويثبت ما يشاء في كتاب سوى أم الكتاب، وهما كتابان أحدهما: أم الكتاب لا يغيره ولا يمحو منه شيئا كما أراد", "ashab": "ابن عباس من طريق عكرمة، وقول عكرمة", "athar": []}, {"n": 4, "t": "أنه الناسخ والمنسوخ، فيمحو المنسوخ، ويثبت الناسخ", "ashab": "ابن عباس من طريق علي بن أبي طلحة، وقتادة، وزيد بن أسلم، وابن جريج، ومقاتل بن سليمان، وعبد الرحمن بن زيد", "athar": [39310, 39315, 39317, 39318, 39319]}, {"n": 5, "t": "يمحو من جاء أجله ويثبت من لم يجئ أجله", "ashab": "الحسن، ومجاهد من طريق ابن أبي نجيح", "athar": [39305, 39306, 39307, 39308]}, {"n": 6, "t": "يغفر ما يشاء من ذنوب عباده، ويترك ما يشاء فلا يغفره", "ashab": "سعيد بن جبير", "athar": [39294, 39295]}, {"n": 7, "t": "يمحو من ديوان الحفظة ما ليس فيه ثواب ولا عقاب، ويثبت ما فيه ثواب وعقاب", "ashab": "الضحاك، والكلبي", "athar": [39300, 39301, 39277, 39316]}, {"n": 8, "t": "يمحو ما يشاء بالتوبة، ويثبت مكانها حسنات", "ashab": "عكرمة", "athar": []}, {"n": 9, "t": "يمحو القمر، ويثبت الشمس مكانه", "ashab": "السدي", "athar": [39313]}]}, "tags": {"m": {"5": [["ابن جرير", "r"]], "2": [["ابن عطية", "r"]]}, "t": {"4": [["ابن جرير", "r"]], "1": [["ابن عطية", "r"]]}, "gen": [], "rules": {"ابن جرير": ["السياق", "السنة"], "ابن عطية": ["العموم"]}, "rulesD": {}}}, {"aya": 39, "title": "في تأويل قوله: ﴿وعنده أم الكتاب﴾", "tabari": {"page": "13/571", "sarih": 1, "tarjih": "وأولى الأقوال في ذلك بالصواب قول من قال: وعنده أصل الكتاب وجملته، وذلك أنه تعالى ذكره أخبر أنه يمحو ما يشاء ويثبت ما يشاء، ثم عقب ذلك بقوله: ﴿وعنده أم الكتاب﴾. فكان بينا أن معناه: وعنده أصل المثبت منه والممحو، وجملته في كتاب لديه.", "how": "رجّح قول فريق («قول من قال…»)", "aqwal": [{"n": 1, "t": "معناه وعنده الحلال والحرام", "taqdim": 0, "n_athar": 6, "qailun": [["قتادة", "تابعي"], ["الضحاك", "تابعي"], ["ابن عباس", "صحابي"]], "athar": [39273, 39274, 39275, 39284, 39285, 39286, 39287, 39288, 39289, 39300, 39301, 39310, 39320, 39321, 39322, 39325, 39329]}, {"n": 2, "t": "ثنا الحسين، قال: ثنا معتمر بن سليمان، عن أبيه، عن سيار ، عن ابن عباس، أنه سأل كعبا عن أم الكتاب فقال: علم الله ما هو خالق وما خلقه عاملون، فقال لعلمه: كن كتابا. فكان كتابا", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}, {"n": 3, "t": "هو الذكر", "taqdim": 0, "n_athar": 1, "qailun": [["أبو جعفر", "تابعي"]], "athar": []}]}, "mawaqif": [{"taliq": 3531, "mi": 1, "aya": 39, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "13/ 573", "qawl": "الثاني", "nass": "وأولى الأقوال في ذلك بالصواب قول من قال: وعنده أصل الكتاب وجملته، وذلك أنه -تعالى ذكره- أخبر أنه يمحو ما يشاء ويثبت ما يشاء، ثم عقب ذلك بقوله: {وعنده أم الكتاب}، فكان بينا أن معناه: وعنده أصل المثبت منه والممحو، وجملته في كتاب لديه", "qawaid": ["السياق"], "tabi": ""}, {"taliq": 3531, "mi": 1, "aya": 39, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "5/ 213 - 214", "qawl": "", "nass": "", "qawaid": [], "tabi": "ابن جرير"}], "mushid": {"i": 14, "imgs": ["013_014_1.png"], "pages": [306], "n": 4, "rajih": [], "daif": [], "match": false}, "mawsua": {"taliq": 3531, "masala": "المراد بأم الكتاب", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "الحلال والحرام", "ashab": "", "athar": []}, {"n": 2, "t": "جملة الكتاب وأصله", "ashab": "ابن عباس من طريق علي بن أبي طلحة، وقول الضحاك، وقتادة", "athar": [39329]}, {"n": 3, "t": "هو علم الله تعالى بما خلق وما هو خالق", "ashab": "", "athar": []}, {"n": 4, "t": "الذكر", "ashab": "", "athar": []}]}, "tags": {"m": {"2": [["ابن جرير", "r"], ["ابن عطية", "r"]]}, "t": {}, "gen": [], "rules": {"ابن جرير": ["السياق"]}, "rulesD": {}}}, {"aya": 40, "title": "قوله: {نعدهم}", "mawsua": {"taliq": 3532, "masala": "قوله: {نعدهم}", "sigha": "ذكر احتمالين", "nasib": "ابن عطية", "aqwal": [{"n": 1, "t": "أن يريد به: المضار التي توعد الله بها الكفار، فأطلق فيها لفظة الوعد لما كانت تلك المضار معلومة مصرحا بها", "ashab": "", "athar": []}, {"n": 2, "t": "أن يريد: الوعد لمحمد صلى الله عليه وسلم في إهلاك الكفرة، ثم أضاف الوعد إليهم لما كان في شأنهم", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 3532, "mi": 1, "aya": 40, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "5/ 215", "qawl": "", "nass": "وقوله: {نعدهم} يحتمل أن يريد به: المضار التي توعد الله بها الكفار، فأطلق فيها لفظة الوعد لما كانت تلك المضار معلومة مصرحا بها. ويحتمل أن يريد: الوعد لمحمد صلى الله عليه وسلم في إهلاك الكفرة، ثم أضاف الوعد إليهم لما كان في شأنهم", "qawaid": [], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 41, "title": "في تأويل ذلك ﴿أولم يروا أنا نأتي الأرض ننقصها من أطرافها والله يحكم لا معقب لحكمه وهو سريع الحساب﴾", "tabari": {"page": "13/574", "sarih": 1, "tarjih": "وأولى الأقوال في تأويل ذلك بالصواب قول من قال: ﴿أولم يروا أنا نأتي الأرض ننقصها من أطرافها﴾ بظهور المسلمين من أصحاب محمد ﷺ عليها، وقهرهم أهلها، أفلا يعتبرون بذلك، فيخافون ظهورهم على أرضهم، وقهرهم إياهم؟ وذلك أن الله توعد الذين سألوا رسوله الآيات من مشركي قومه بقوله: ﴿وإن ما نرينك بعض الذي نعدهم أو نتوفينك فإنما عليك البلاغ وعلينا الحساب (٤٠)﴾. ثم وبخهم تعالى ذكره بسوء اعتبارهم بما يعاينون من فعل الله بضربائهم من الكفار، وهم مع ذلك يسألون الآيات، فقال: ﴿أولم يروا أنا نأتي الأرض ننقصها من أطرافها﴾ بقهر أهلها والغلبة عليها من أطرافها وجوانبها، وهم لا يعتبرون بما يرون من ذلك!", "how": "رجّح قول فريق («قول من قال…»)", "aqwal": [{"n": 1, "t": "معناه أو لم ير هؤلاء المشركون من أهل مكة، الذين يسألون محمدا الآيات، أنا نأتي الأرض، فنفتحها له أرضا بعد أرض، حوالي أرضهم؟ أفلا يخافون أن نفتح له أرضهم، كما فتحنا له غيرها؟", "taqdim": 0, "n_athar": 5, "qailun": [["ابن عباس", "صحابي"], ["الضحاك", "تابعي"], ["معمر", "تابع التابعين"]], "athar": [39337, 39338, 39339, 39340, 39341, 39342, 39349, 39350, 39351]}, {"n": 2, "t": "بل معناه: أولم يروا أنا نأتى الأرض فنخربها؟ أولا يخافون أن نفعل بهم وبأرضهم مثل ذلك، فنهلكهم ونخرب أرضهم؟", "taqdim": 0, "n_athar": 3, "qailun": [["ابن عباس", "صحابي"], ["عكرمة", "تابعي"]], "athar": [39337, 39338, 39339, 39340, 39341, 39342]}, {"n": 3, "t": "بل معناه: ننقص من بركتها وثمرتها وأهلها بالموت", "taqdim": 0, "n_athar": 3, "qailun": [["ابن عباس", "صحابي"], ["مجاهد", "تابعي"]], "athar": [39337, 39338, 39339, 39340, 39341, 39342, 39344, 39345, 39346, 39347, 39348]}, {"n": 4, "t": "معناه: أنا نأتى الأرض ننقصها من أهلها، فنتطرفهم بأخذهم بالموت", "taqdim": 0, "n_athar": 7, "qailun": [["مجاهد", "تابعي"], ["عكرمة", "تابعي"], ["قتادة", "تابعي"], ["أبي رجاء", ""]], "athar": [39344, 39345, 39346, 39347, 39348, 39352]}, {"n": 5, "t": "ننقصها من أطرافها بذهاب فقهائها وخيارها", "taqdim": 0, "n_athar": 1, "qailun": [["ابن عباس", "صحابي"]], "athar": [39337, 39338, 39339, 39340, 39341, 39342]}]}, "mawaqif": [{"taliq": 3533, "mi": 1, "aya": 41, "alam": "ابن عطية", "fil": "بين", "kind": "بيان", "ref": "5/ 215", "qawl": "الثاني", "nass": "", "qawaid": [], "tabi": ""}, {"taliq": 3533, "mi": 1, "aya": 41, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "13/ 579", "qawl": "الأول", "nass": "وذلك أن الله توعد الذين سألوا رسوله الآيات من مشركي قومه بقوله: {وإن ما نرينك بعض الذي نعدهم أو نتوفينك}، ثم وبخهم -تعالى ذكره- بسوء اعتبارهم ما يعاينون من فعل الله بضربائهم من الكفار، وهم مع ذلك يسألون الآيات، فقال: {أو لم يروا أنا نأتي الأرض ننقصها من أطرافها} بقهر أهلها، والغلبة عليها من أطرافها وجوانبها، وهم لا يعتبرون بما يرون من ذلك", "qawaid": ["السياق", "القرآن والنظائر"], "tabi": ""}, {"taliq": 3533, "mi": 1, "aya": 41, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "5/ 215", "qawl": "", "nass": "وأليق ما يقصد لفظ الآية هو تنقص الأرض بالفتوح على محمد", "qawaid": [], "tabi": ""}, {"taliq": 3533, "mi": 1, "aya": 41, "alam": "ابن كثير", "fil": "قال", "kind": "قول", "ref": "8/ 170", "qawl": "", "nass": "والقول الأول أولى، وهو ظهور الإسلام على الشرك قرية بعد قرية، كقوله تعالى: {ولقد أهلكنا ما حولكم من القرى} [الأحقاف: 27] الآية", "qawaid": [], "tabi": ""}], "mushid": {"i": 15, "imgs": ["013_015_1.png"], "pages": [307], "n": 5, "rajih": [1], "daif": [], "match": true}, "mawsua": {"taliq": 3533, "masala": "معنى إنقاص الأرض من أطرافها المذكور في الآية", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "ما ينقص من أرض المشركين بفتح رسول الله صلى الله عليه وسلم والمسلمين له وغلبتهم عليه", "ashab": "", "athar": []}, {"n": 2, "t": "بخرابها بعد العمارة", "ashab": "", "athar": []}, {"n": 3, "t": "ننقص من بركتها وثمرتها", "ashab": "", "athar": []}, {"n": 4, "t": "موت أهلها", "ashab": "", "athar": []}, {"n": 5, "t": "موت فقهائها وخيارها", "ashab": "", "athar": []}]}, "tags": {"m": {"1": [["ابن جرير", "r"]]}, "t": {"1": [["ابن جرير", "r"]]}, "gen": [], "rules": {"ابن جرير": ["السياق", "القرآن والنظائر"]}, "rulesD": {}}}], "extra": [{"i": 5, "aya": 11, "imgs": ["013_005_1.png"], "pages": [303], "ihala": 0}], "others": {"0": [{"id": 3473, "kinds": "تعليق،نقل", "text": "ذكر ابنُ عطية (5/ 168) قول سعيد بن جبير، وقتادة، ونقل عن قتادة قولًا حكاه عنه المهدوي: أنّ السورة مكية إلا قوله تعالى: {ولا يَزالُ الَّذِينَ كَفَرُوا تُصِيبُهُمْ بِما صَنَعُوا قارِعَةٌ أوْ تَحُلُّ قَرِيبًا مِن دارِهِمْ} [31]، وقوله: {ومَن عِنْدَهُ عِلْمُ الكِتابِ} [43]، ثم علَّق بقوله: «والظاهر عندي أنّ المدني فيها كثير، وكل ما نزل في شأن عامر بن الطفيل وإربد بن ربيعة فهو مدني».", "mawaqif": [{"taliq": 3473, "mi": 0, "aya": 0, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "5/ 168", "qawl": "سعيد بن", "nass": "والظاهر عندي أن المدني فيها كثير، وكل ما نزل في شأن عامر بن الطفيل وإربد بن ربيعة فهو مدني", "qawaid": [], "tabi": ""}]}], "1": [{"id": 3474, "kinds": "توجيه،نقل", "text": "ذكر ابنُ عطية (5/ 168 - 169) أنّ مَن قال بأنّ حروف أوائل السور هي مثال لحروف المعجم، قال: الإشارة هنا بـ {تلك} هي إلى حروف المعجم، ثم وجَّه قولهم بقوله: «ويَصِحُّ على هذا أن يكون {الكِتابِ} يراد به: القرآن، ويصح أن يراد به: التوراة والإنجيل. و {المر} على هذا ابتداءٌ، و {تِلْكَ} ابتداء ثان، و {آياتُ} خبر الثاني، والجملة خبر الأول … قوله تعالى: {والَّذِي أُنْزِلَ إلَيْكَ مِن رَبِّكَ الحَقُّ}: {الَّذِي} رفع بالابتداء، و {الحَقُّ} خبره». ثم وجَّه قول ابن عباس بقوله: «وعلى قول ابن عباس في {المر} تكون {تِلْكَ} ابتداء، و {آياتُ} بدلًا منه، ويصح في {الكِتابِ} التأويلان اللذان تقدَّما … وعلى قول ابن عباس يكون {الذي} عطفًا على {تلكَ}، و {الحقُّ} خبر {تلكَ}».", "mawaqif": [{"taliq": 3474, "mi": 0, "aya": 1, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "5/ 168 - 169", "qawl": "", "nass": "ويصح على هذا أن يكون {الكتاب} يراد به: القرآن، ويصح أن يراد به: التوراة والإنجيل. و {المر} على هذا ابتداء، و {تلك} ابتداء ثان، و {آيات} خبر الثاني، والجملة خبر الأول … قوله تعالى: {والذي أنزل إليك من ربك الحق}: {الذي} رفع بالابتداء، و {الحق} خبره", "qawaid": [], "tabi": ""}]}, {"id": 3475, "kinds": "نقد", "text": "انتَقَد ابنُ كثير (8/ 101) قول مجاهد، وقتادة أن الكتاب في قوله تعالى: {تِلْكَ آياتُ الكِتابِ}: التوراة والإنجيل، فقال: «وفيه نظر، بل هو بعيد».", "mawaqif": [{"taliq": 3475, "mi": 0, "aya": 1, "alam": "ابن كثير", "fil": "انتقد", "kind": "نقد", "ref": "8/ 101", "qawl": "مجاهد", "nass": "وفيه نظر، بل هو بعيد", "qawaid": [], "tabi": ""}]}], "2": [{"id": 3477, "kinds": "توجيه", "text": "وجَّه ابنُ كثير (8/ 102) قول إياس بن معاوية بقوله: «يعني: بلا عَمَد».", "mawaqif": [{"taliq": 3477, "mi": 0, "aya": 2, "alam": "ابن كثير", "fil": "وجه", "kind": "توجيه", "ref": "8/ 102", "qawl": "إياس بن", "nass": "يعني: بلا عمد", "qawaid": [], "tabi": ""}]}, {"id": 3479, "kinds": "نقد،بيان،نقل", "text": "نقل ابنُ عطية (5/ 171) عن مجاهد أنّه قال في معنى: {اسْتَوى عَلى العَرْشِ} أي: علا على العرش، ثم انتقده قائلًا: «والنظر الصحيح يرفع هذه العبارة» أ. هـ.\nوتعقيب ابن عطية باطل، والحق إثبات الاستواء لله تعالى على ما يليق بجلاله وكماله وعظمته، وهو إجماع السلف من الصحابة والتابعين وتابعيهم. ينظر: الشريعة 3/ 1081 - 1107، الإبانة الكبرى 3/ 136 - 168، شرح أصول اعتقاد أهل السنة والجماعة 2/ 429 - 447.", "mawaqif": [{"taliq": 3479, "mi": 0, "aya": 2, "alam": "ابن عطية", "fil": "نقل", "kind": "نقل", "ref": "5/ 171", "qawl": "", "nass": "والنظر الصحيح يرفع هذه العبارة", "qawaid": [], "tabi": ""}]}, {"id": 3480, "kinds": "غيره", "text": "لم يذكر ابنُ جرير (13/ 412) في معنى: {كُلٌّ يَجْرِي لأَجَلٍ مُسَمًّى} سوى قول مجاهد.", "mawaqif": []}], "4": [{"id": 3481, "kinds": "توجيه،تعليق،نقل", "text": "ذكر ابنُ عطية (5/ 175) قول ابن عباس من طريق عكرمة، وقتادة، ثم وجَّهه بقوله: «وهذا وجْه من العبرة، كأنه قال: وفي الأرض قطع مختلفات بتخصيص الله لها بمعان فهي تسقى بماءٍ واحد، ولكن تختلف فيما تخرجه». ثم علَّق بقوله: «والذي يظهر من وصفه لها بالتجاور إنما هو: أنّها مِن تربة واحدة ونوع واحد، والعبرة في هذا أبْيَن؛ لأنها مع اتفاقها في التربة والماء تفضل القدرة والإرادة بعض أكلها على بعض، كما قال النبي عليه الصلاة والسلام حين سُئِل عن هذه الآية فقال: «الدَّقَل، والفارسي، والحلو، والحامض»».", "mawaqif": [{"taliq": 3481, "mi": 0, "aya": 4, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "5/ 175", "qawl": "ابن عباس", "nass": "وهذا وجه من العبرة، كأنه قال: وفي الأرض قطع مختلفات بتخصيص الله لها بمعان فهي تسقى بماء واحد، ولكن تختلف فيما تخرجه", "qawaid": [], "tabi": ""}]}, {"id": 3482, "kinds": "تعليق،نقل", "text": "نقل ابنُ عطية (5/ 174) عن البراء بن عازب رضي الله عنهما قوله: «الصِّنوان: المجتمع. وغير صنوان: المتفرق فردًا فردًا». ثم علَّق عليه بقوله: «ومنه قول النبي صلى الله عليه وسلم: «العمُّ صِنْوُ الأب»».", "mawaqif": [{"taliq": 3482, "mi": 0, "aya": 4, "alam": "ابن عطية", "fil": "نقل", "kind": "نقل", "ref": "5/ 174", "qawl": "", "nass": "الصنوان: المجتمع. وغير صنوان: المتفرق فردا فردا", "qawaid": [], "tabi": ""}]}], "6": [{"id": 3484, "kinds": "تعليق،نقل", "text": "نقل ابنُ عطية (5/ 178) عن ابن جرير في قوله تعالى: {وإنَّ رَبَّكَ لَذُو مَغْفِرَةٍ لِلنّاسِ عَلى ظُلْمِهِمْ} أنه قال: «معناه: في الآخرة». ونقل عن قومٍ: أن «المعنى: إذا تابوا، وشديد العقاب إذا كفروا». ثم علَّق بقوله: «والظاهر من معنى المغفرة هنا إنما هو: سَتْرُهُ في الدنيا وإمهاله للكفرة، ألا ترى التنكير في لفظ {مَغْفِرَةٍ}، وأنها منَكَّرة مُقَلَّلة وليس فيها مبالغة، كما في قوله تعالى: {وإنِّي لَغَفّارٌ لِمَن تابَ وآمَنَ} [طه: 82]، ونمط الآية يُعْطِي هذا، ألا ترى حكمه عليهم بالنار؟ ثم قال: {ويَسْتَعْجِلُونَكَ}، فلما ظهر سوءُ فعلهم وجب في نفس السامع تعذيبهم، فأخبر بسيرته في الأمم وأنه يمهل مع ظلم الكفر، ولم يَرِد في الشرع أنّ الله تعالى يغفر ظُلْمَ العباد».", "mawaqif": [{"taliq": 3484, "mi": 0, "aya": 6, "alam": "ابن عطية", "fil": "نقل", "kind": "نقل", "ref": "5/ 178", "qawl": "", "nass": "معناه: في الآخرة", "qawaid": [], "tabi": ""}]}], "8": [{"id": 3486, "kinds": "نقد،نقل", "text": "نقل ابنُ عطية (5/ 182) اختلافًا في أكثر الحمل قائلًا: «فقيل: تسعة أشهر». وانتقده قائلًا: «وهذا ضعيف». ثم قال: «وقالت عائشة وجماعة من العلماء: أكثره حولان. وقالت فرقة: ثلاثة أعوام. وفي المدونة: أربعة أعوام، وخمسة أعوام. وقال ابن شهاب وغيره: سبعة أعوام. وروي: أنّ ابن عجلان ولدت امرأته لسبعة أعوام. وروي: أنّ الضحاك بن مزاحم بقي حولين، قال: فولدت وقد نبتت ثناياي. وروي: أنّ عبد الملك بن مروان ولد لستة أشهر».", "mawaqif": [{"taliq": 3486, "mi": 0, "aya": 8, "alam": "ابن عطية", "fil": "نقل", "kind": "نقل", "ref": "5/ 182", "qawl": "", "nass": "فقيل: تسعة أشهر", "qawaid": [], "tabi": ""}]}, {"id": 3487, "kinds": "توجيه،تعليق،نقل", "text": "علَّق ابنُ القيم (2/ 79) على هذه الآثار في معنى: {وما تَغِيضُ الأَرْحامُ وما تَزْدادُ} بقوله: «والتحقيق في معنى الآية: أنه يعلم مدة الحمل، وما يعرض فيها من الزيادة والنقصان، فهو العالم بذلك دونكم، كما هو العالم بما تحمل كل أنثى: هل هو ذكر أو أنثى؟ وهذا أحد أنواع الغيب التي لا يعلمها إلا الله تعالى، كما في الصحيح عنه صلى الله عليه وسلم: «مفاتيح الغيب خمس لا يعلمهن إلا الله: لا يعلم متى تجيء الساعة إلا الله، ولا يعلم ما في غدٍ إلا الله، ولا يعلم متى يجيء الغيث إلا الله، ولا يعلم ما في الأرحام إلا الله، ولا تدري نفس بأي أرض تموت إلا الله». فهو سبحانه المنفرد بعلم ما في الرحم، وعلم وقت إقامته فيه، وما يزيد من بدنه وما ينقص». ثم وجَّه ما عداه من الأقوال بقوله: «وما عدا هذا القول فهو من توابعه ولوازمه، كالسقط والتام، ورؤية الدم وانقطاعه».\nونقل ابنُ عطية (5/ 181) عن بعض الناس أن غيض الرحم: «هو نضوب الدم فيه، وإمساكه بعد عادة إرساله بالحيض». ثم وجَّهه بقوله: «فيكون قوله: {وما تَزْدادُ} بعد ذلك جاريًا مجرى» تغيض «على غير مقابلة، بل غيض الرحم هو بمعنى الزيادة فيه».", "mawaqif": [{"taliq": 3487, "mi": 0, "aya": 8, "alam": "ابن القيم", "fil": "علق", "kind": "تعليق", "ref": "2/ 79", "qawl": "", "nass": "والتحقيق في معنى الآية: أنه يعلم مدة الحمل، وما يعرض فيها من الزيادة والنقصان، فهو العالم بذلك دونكم، كما هو العالم بما تحمل كل أنثى: هل هو ذكر أو أنثى؟ وهذا أحد أنواع الغيب التي لا يعلمها إلا الله تعالى، كما في الصحيح عنه صلى الله عليه وسلم: «مفاتيح الغيب خمس لا يعلمهن إلا الله: لا يعلم متى تجيء الساعة إلا الله، ولا يعلم ما في غد إلا الله، ولا يعلم متى يجيء الغيث إلا الله، ولا يعلم ما في الأرحام إلا الله، ولا تدري نفس بأي أرض تموت إلا الله", "qawaid": [], "tabi": ""}, {"taliq": 3487, "mi": 0, "aya": 8, "alam": "ابن عطية", "fil": "نقل", "kind": "نقل", "ref": "5/ 181", "qawl": "", "nass": "هو نضوب الدم فيه، وإمساكه بعد عادة إرساله بالحيض", "qawaid": [], "tabi": ""}]}, {"id": 3488, "kinds": "غيره", "text": "لم يذكر ابنُ جرير (13/ 452) في معنى: {وكُلُّ شَيْءٍ عِنْدَهُ بِمِقْدارٍ} سوى قول قتادة.", "mawaqif": []}], "10": [{"id": 3489, "kinds": "نقد،نقل", "text": "نقل ابنُ عطية (5/ 184) عن «قطرب -فيما حكى الزجاج-: {مُسْتَخْفٍ} معناه: ظاهر، من قولهم: خفَيْتُ الشيء: إذا أظهرته، … {وسارِبٌ} معناه: متوارٍ في سرب». ثم انتقده مستندًا إلى دلالة السياق قائلًا: «وهذا القول وإن كان متعلِّقًا باللغة فضعيف؛ لأن اقتران الليل بالمستخفي والنهار بالسارب يردُّ على هذا القول».", "mawaqif": [{"taliq": 3489, "mi": 0, "aya": 10, "alam": "ابن عطية", "fil": "نقل", "kind": "نقل", "ref": "5/ 184", "qawl": "", "nass": "قطرب -فيما حكى الزجاج-: {مستخف} معناه: ظاهر، من قولهم: خفيت الشيء: إذا أظهرته، … {وسارب} معناه: متوار في سرب", "qawaid": ["السياق"], "tabi": ""}]}, {"id": 3490, "kinds": "توجيه،تعليق،نقل", "text": "ذكر ابنُ عطية (5/ 183) أنّ ابن عباس -من طريق العوفي- ومجاهد ذهبا «إلى معنى مقتضاه: أنّ المستخفي بالليل والسارب بالنهار هو رجل واحد، مريب بالليل، ويظهر بالنهار البراءة في التصرف مع الناس». ثم علَّق عليه بقوله: «فهذا قِسْمٌ واحد جعل الليلَ نهار راحته». ثم وجَّهه بقوله: «والمعنى: هذا والذي أمره كله واحد بريء من الريب سواء في اطلاع الله تعالى على الكل، ويؤيد هذا التأويل عطف السارب دون تكرار {مَن}، ولا يأتي حذفها إلا في ضرورة الشعر».", "mawaqif": [{"taliq": 3490, "mi": 0, "aya": 10, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "5/ 183", "qawl": "", "nass": "إلى معنى مقتضاه: أن المستخفي بالليل والسارب بالنهار هو رجل واحد، مريب بالليل، ويظهر بالنهار البراءة في التصرف مع الناس", "qawaid": [], "tabi": ""}]}], "11": [{"id": 3491, "kinds": "توجيه", "text": "وجَّه ابنُ كثير (8/ 116) قول ابن عباس من طريق العوفي، والضحاك، وعكرمة من طريق شرقي بقوله: «والظاهر -والله أعلم- أنّ مراد ابن عباس، وعكرمة، والضحاك بهذا: أنّ حرس الملائكة للعبيد يُشْبِه حرس هؤلاء لملوكهم وأمرائهم».", "mawaqif": [{"taliq": 3491, "mi": 0, "aya": 11, "alam": "ابن كثير", "fil": "وجه", "kind": "توجيه", "ref": "8/ 116", "qawl": "ابن عباس", "nass": "والظاهر -والله أعلم- أن مراد ابن عباس، وعكرمة، والضحاك بهذا: أن حرس الملائكة للعبيد يشبه حرس هؤلاء لملوكهم وأمرائهم", "qawaid": [], "tabi": ""}]}, {"id": 3493, "kinds": "نقد،توجيه", "text": "وجَّه ابنُ عطية (3/ 302 ط: دار الكتب العلمية) قول قتادة بأنّ المعنى: يحفظونه مما أمر الله، ثم انتقده قائلًا: «وهذا تَحَكُّم في التأويل».", "mawaqif": [{"taliq": 3493, "mi": 0, "aya": 11, "alam": "ابن عطية", "fil": "وجه", "kind": "توجيه", "ref": "3/ 302 ط: دار الكتب العلمية", "qawl": "قتادة بأن", "nass": "وهذا تحكم في التأويل", "qawaid": [], "tabi": ""}]}], "12": [{"id": 3496, "kinds": "نقد،تعليق،نقل", "text": "ذكر ابنُ عطية (5/ 188) أنّ البرق: رُوِي فيه عن النبي صلى الله عليه وسلم أنّه مخراق بيد ملَك يزجر به السحاب، ثم علَّق عليه بقوله: «وهذا أصحُّ ما روي فيه». ونقل عن بعض العلماء أنه قال: البرق: اصطكاك الأجرام. ثم انتقده قائلًا: «وهذا عندي مردود».", "mawaqif": [{"taliq": 3496, "mi": 0, "aya": 12, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "5/ 188", "qawl": "", "nass": "وهذا أصح ما روي فيه", "qawaid": [], "tabi": ""}]}, {"id": 3497, "kinds": "توجيه", "text": "وجَّه ابنُ عطية (5/ 189) هذا الأثر بقوله: «ومعنى هذا القول: أنّه لما كان داعية الماء، وكان خوف المسافر من الماء وطمع المقيم فيه؛ عُبِّر في هذا القول عنه بالماء».", "mawaqif": [{"taliq": 3497, "mi": 0, "aya": 12, "alam": "ابن عطية", "fil": "وجه", "kind": "توجيه", "ref": "5/ 189", "qawl": "", "nass": "ومعنى هذا القول: أنه لما كان داعية الماء، وكان خوف المسافر من الماء وطمع المقيم فيه؛ عبر في هذا القول عنه بالماء", "qawaid": [], "tabi": ""}]}, {"id": 3498, "kinds": "غيره", "text": "لم يذكر ابنُ جرير (13/ 475) في معنى: {هُوَ الَّذِي يُرِيكُمُ البَرْقَ خَوْفًا وطَمَعًا} سوى قول قتادة.", "mawaqif": []}], "13": [{"id": 3499, "kinds": "نقل", "text": "ذكر ابنُ عطية (5/ 191) في قوله تعالى: {وهُمْ يُجادِلُونَ في الله} عدة احتمالات لاسم الإشارة «هم»، فقال: «يجوز أن تكون إشارة إلى جدال اليهود المذكور، وتكون الواو واو حال، أو إلى جدال الجبار المذكور. ويجوز -إن كانت الآية على غير سبب- أن يكون قوله: {وهُمْ يُجادِلُونَ فِي اللَّهِ} إشارة إلى جميع الكفرة مِن العرب وغيرهم، الذين جُلبت لهم هذه التنبيهات».", "mawaqif": [{"taliq": 3499, "mi": 0, "aya": 13, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "5/ 191", "qawl": "", "nass": "هم", "qawaid": [], "tabi": ""}]}], "14": [{"id": 3501, "kinds": "نقل", "text": "نقل ابنُ عطية (5/ 193) قول علي بن أبي طالب وابن عباس، ثم زاد قائلًا: «ويصح أن يكون معناها: له دعوة العباد بالحق، ودعاء غيره من الأوثان باطل».", "mawaqif": [{"taliq": 3501, "mi": 0, "aya": 14, "alam": "ابن عطية", "fil": "نقل", "kind": "نقل", "ref": "5/ 193", "qawl": "علي بن", "nass": "ويصح أن يكون معناها: له دعوة العباد بالحق، ودعاء غيره من الأوثان باطل", "qawaid": [], "tabi": ""}]}], "15": [{"id": 3502, "kinds": "نقل", "text": "ذكر ابنُ عطية (5/ 194) أنّ {مَن} في قوله تعالى: {ولِلَّهِ يَسْجُدُ مَن فِي السَّماواتِ والأَرْضِ طَوْعًا وكَرْهًا} «تقع على الملائكة عمومًا، وسجودهم طوعًا بلا خلاف، وأمّا أهل الأرض فالمؤمنون منهم داخلون في مَن سجودهم طَوْعٌ، وأمّا سجود الكفرة فهو الكُرْه». ثم ذكر صنفين مِن الكفار يدخلون في الكُره بناءً على المقصود بالسجود في الآية: «فإن جعلنا السجود هذه الهيئة المعهودة فالمراد مِن الكفرة مَن يضمه السَّيْفُ إلى الإسلام -كما قال قتادة- فيسجد كرهًا؛ إمّا نفاقًا، وإمّا أن يكون الكره أول حاله فتستمر عليه الصفة، وإن صح إيمانه بعد. وإن جعلنا السجود الخضوع والتذلل على حسب ما هو في اللغة … فيدخل الكفار أجمعون في {مَن}؛ لأنه ليس مِن كافر إلا ويلحقه مِن التذلل والاستكانة بقدرة الله أنواع أكثر مِن أن تحصى بحسب رزاياه واعتباراته». ونقل عن النحاس والزجاج قولهم: «إنّ الكره يكون في سجود عصاة المسلمين وأهل الكسل منهم». ثم انتقدهم قائلًا: «وإن كان اللفظ يقتضي هذا فهو قَلِق مِن جهة المعنى المقصود بالآية».", "mawaqif": [{"taliq": 3502, "mi": 0, "aya": 15, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "5/ 194", "qawl": "", "nass": "تقع على الملائكة عموما، وسجودهم طوعا بلا خلاف، وأما أهل الأرض فالمؤمنون منهم داخلون في من سجودهم طوع، وأما سجود الكفرة فهو الكره", "qawaid": [], "tabi": ""}]}, {"id": 3503, "kinds": "نقد،نقل", "text": "نقل ابنُ عطية (5/ 194) حكاية الزجاج «أنّ بعض الناس قال: إنّ الظلال هنا يراد بها: الأشخاص». ثم قال: «وضعَّفه أبو إسحاق».", "mawaqif": [{"taliq": 3503, "mi": 0, "aya": 15, "alam": "ابن عطية", "fil": "نقل", "kind": "نقل", "ref": "5/ 194", "qawl": "", "nass": "أن بعض الناس قال: إن الظلال هنا يراد بها: الأشخاص", "qawaid": [], "tabi": ""}]}], "17": [{"id": 3504, "kinds": "نقد،توجيه،نقل", "text": "نقل ابنُ عطية (5/ 197) عن ابن عباس أن «قوله تعالى: {مِنَ السَّماءِ} يريد به: الشَّرْعَ والدِّين، وقوله تعالى: {فَسالَتْ أوْدِيَةٌ} يريد به: القلوب، أي: أخذ النبيل بحظِّه، والبليد بحظِّه». ثم انتقده مستندًا إلى ضعف إسناد الأثر، وإلى مخالفة لغة العرب قائلًا: «وهذا قول لا يصح -والله أعلم- عن ابن عباس؛ لأنه ينحو إلى أقوال أصحاب الرموز، وقد تمسَّك به الغزاليُّ وأهل ذلك الطريق، ولا وجه لإخراج اللفظ عن مفهوم كلام العرب لغير عِلَّةٍ تدعو إلى ذلك». إلا أنه وجَّهه على فرض صحته بقوله: «وإن صَحَّ هذا القول عن ابن عباس فإنما قصد أنّ قوله تعالى: {كَذلِكَ يَضْرِبُ اللَّهُ الحَقَّ والباطِلَ} معناه: الحق الذي يتقرر في القلوب، والباطل الذي يعتريها».", "mawaqif": [{"taliq": 3504, "mi": 0, "aya": 17, "alam": "ابن عطية", "fil": "نقل", "kind": "نقل", "ref": "5/ 197", "qawl": "", "nass": "قوله تعالى: {من السماء} يريد به: الشرع والدين، وقوله تعالى: {فسالت أودية} يريد به: القلوب، أي: أخذ النبيل بحظه، والبليد بحظه", "qawaid": ["نقد الرواية (السند، الإسرائيليات)", "اللغة"], "tabi": ""}]}, {"id": 3505, "kinds": "نقل", "text": "ذكر ابنُ عطية (5/ 196) في معنى الآية احتمالًا آخر، فقال: «يحتمل أن يريد: بما قُدّر لها من الماء».", "mawaqif": [{"taliq": 3505, "mi": 0, "aya": 17, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "5/ 196", "qawl": "", "nass": "يحتمل أن يريد: بما قدر لها من الماء", "qawaid": [], "tabi": ""}]}], "18": [{"id": 3506, "kinds": "غيره", "text": "لم يذكر ابنُ جرير (13/ 505) في معنى: {لِلَّذِينَ اسْتَجابُوا لِرَبِّهِمُ الحُسْنى} سوى قول قتادة.", "mawaqif": []}], "19": [{"id": 3507, "kinds": "تعليق،نقل", "text": "ذكر ابنُ عطية (5/ 199) أنّ هذه الآية نزلت في حمزة بن عبد المطلب وأبي جهل بن هشام. وقيل: في عمار بن ياسر وأبي جهل، ثم علَّق بقوله: «وهي بعد هذا مثال في جميع العالم».", "mawaqif": [{"taliq": 3507, "mi": 0, "aya": 19, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "5/ 199", "qawl": "", "nass": "وهي بعد هذا مثال في جميع العالم", "qawaid": [], "tabi": ""}]}], "20": [{"id": 3508, "kinds": "توجيه", "text": "وجَّه ابنُ عطية (5/ 199) تفسير قتادة للميثاق بأنه يريد به جنس المواثيق.", "mawaqif": [{"taliq": 3508, "mi": 0, "aya": 20, "alam": "ابن عطية", "fil": "وجه", "kind": "توجيه", "ref": "5/ 199", "qawl": "", "nass": "", "qawaid": [], "tabi": ""}]}], "22": [{"id": 3510, "kinds": "نقل", "text": "قال ابنُ عطية (5/ 200): «ورُوِي أنّ هذه الآية نزلت في الأنصار، ثم بقيت عامَّةً بعد ذلك في كلِّ مَن اتَّصَف بهذه الصِّفات».", "mawaqif": [{"taliq": 3510, "mi": 0, "aya": 22, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "5/ 200", "qawl": "", "nass": "وروي أن هذه الآية نزلت في الأنصار، ثم بقيت عامة بعد ذلك في كل من اتصف بهذه الصفات", "qawaid": [], "tabi": ""}]}, {"id": 3511, "kinds": "غيره", "text": "لم يذكر ابنُ جرير (13/ 510) في معنى: {ويدرءونَ بالحسنةِ السيئةَ} سوى قول ابن زيد.", "mawaqif": []}], "23": [{"id": 3512, "kinds": "نقل", "text": "ذكر ابنُ عطية (5/ 200) هذا القول، ثم أورد احتمالًا آخر، فقال: «ويحتمل: أي: مَن صلح لذلك بقدر الله تعالى، وسابِق عِلْمِه».", "mawaqif": [{"taliq": 3512, "mi": 0, "aya": 23, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "5/ 200", "qawl": "", "nass": "ويحتمل: أي: من صلح لذلك بقدر الله تعالى، وسابق علمه", "qawaid": [], "tabi": ""}]}], "24": [{"id": 3513, "kinds": "نقد،نقل", "text": "هذا الحديثُ أورده ابنُ جرير (13/ 512 - 513) في بيان صفة دخول الملائكة الجنة على المؤمنين، وقد انتقد ذلك ابنُ عطية (5/ 200) فقال: «وحكى الطبريُّ في صفة دخول الملائكة أحاديث لم نُطَوِّل بها؛ لضعف أسانيدها».", "mawaqif": [{"taliq": 3513, "mi": 0, "aya": 24, "alam": "ابن جرير", "fil": "أورده", "kind": "نقل", "ref": "13/ 512 - 513", "qawl": "", "nass": "وحكى الطبري في صفة دخول الملائكة أحاديث لم نطول بها؛ لضعف أسانيدها", "qawaid": [], "tabi": ""}]}, {"id": 3514, "kinds": "نقد،توجيه،بيان،نقل", "text": "وجَّه ابنُ عطية (5/ 200) القول بأنهم أُعقِبُوا الجنة بقوله: «وهذا التأويل مبنيٌّ على حديث ورد وهو: «أن كل رجل في الجنة فقد كان له مقعد معروف في النار، فصرفه الله عنه إلى النعيم، فيُعرَضُ عليه، ويُقال له: هذا كان مقعدك، فبدَّلك الله منه الجنة بإيمانك وطاعتك وصبرك»». وذكر احتمالين في المراد من قوله تعالى: {فَنِعْمَ عُقْبى الدّارِ}، فقال: «وقوله: {عقبى الدار} يحتمل أن يكون: عقبى دار الدنيا، ثم فسَّر العُقبى بقوله: {جنات عدن}؛ إذ العُقْبى تعم حالة الخير وحالة الشر، ويحتمل أن يريد: عقبى دار الآخرة لدار الدنيا، أي: العقبى الحسنة في الدار الآخرة هي لهم».", "mawaqif": [{"taliq": 3514, "mi": 0, "aya": 24, "alam": "ابن عطية", "fil": "وجه", "kind": "توجيه", "ref": "5/ 200", "qawl": "بأنهم أعقبوا", "nass": "وهذا التأويل مبني على حديث ورد وهو: «أن كل رجل في الجنة فقد كان له مقعد معروف في النار، فصرفه الله عنه إلى النعيم، فيعرض عليه، ويقال له: هذا كان مقعدك، فبدلك الله منه الجنة بإيمانك وطاعتك وصبرك»", "qawaid": [], "tabi": ""}]}], "25": [{"id": 3515, "kinds": "تعليق", "text": "علَّق ابنُ عطية (5/ 201 - 202) على هذا الأثر بقوله: «فكان سعد بن أبي وقاص? يجعل فيهم الآيتين».", "mawaqif": [{"taliq": 3515, "mi": 0, "aya": 25, "alam": "ابن عطية", "fil": "علق", "kind": "تعليق", "ref": "5/ 201 - 202", "qawl": "", "nass": "فكان سعد بن أبي وقاص? يجعل فيهم الآيتين", "qawaid": [], "tabi": ""}]}, {"id": 3516, "kinds": "غيره", "text": "قال ابنُ عطية (5/ 199): «ووصل ما أمر الله به أن يوصل ظاهره في القرابات، وهو مع ذلك يتناول جميع الطاعات».\nوبنحوه ابنُ القيم (2/ 86) حيث قال: «ويدخل في هذا ظاهر الدين وباطنه، وحق الله وحق خلقه».", "mawaqif": [{"taliq": 3516, "mi": 0, "aya": 25, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "5/ 199", "qawl": "", "nass": "ووصل ما أمر الله به أن يوصل ظاهره في القرابات، وهو مع ذلك يتناول جميع الطاعات", "qawaid": [], "tabi": ""}, {"taliq": 3516, "mi": 0, "aya": 25, "alam": "ابن القيم", "fil": "وبنحوه", "kind": "موافقة", "ref": "2/ 86", "qawl": "", "nass": "ويدخل في هذا ظاهر الدين وباطنه، وحق الله وحق خلقه", "qawaid": [], "tabi": "ابن عطية"}]}, {"id": 3517, "kinds": "ترجيح،نقل", "text": "ذكر ابنُ عطية (5/ 202) أنّ {سوء الدار} ضد {عقبى الدار}، ثم رجّح مستندًا إلى الظاهر أنها دار الآخرة، فقال: «والأظهر في الدار هنا: أنها دار الآخرة، ويحتمل أنها الدنيا على ضعف».", "mawaqif": [{"taliq": 3517, "mi": 0, "aya": 25, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "5/ 202", "qawl": "", "nass": "والأظهر في الدار هنا: أنها دار الآخرة، ويحتمل أنها الدنيا على ضعف", "qawaid": ["ظاهر الآية ولفظها"], "tabi": ""}]}], "28": [{"id": 3518, "kinds": "غيره", "text": "لم يذكر ابنُ جرير (13/ 518) في معنى: {وتَطْمَئِنُّ قُلُوبُهُمْ بِذِكْرِ اللَّهِ} سوى قول قتادة.", "mawaqif": []}], "29": [{"id": 3520, "kinds": "نقد،نقل", "text": "انتقد ابنُ عطية (5/ 203 - 204) بعضَ التفصيلات المروية في وصف شجرة طوبى مستندًا لعدم ثبوت أسانيدها، فقال: «وحكى الطبريُّ عن أبي هريرة، وعن مغيث بن سُمَيّ، وعتبة بن عبد يرفعه، أخبارًا مقتضاها أنّ هذه الشجرة ليس دار في الجنة إلا وفيها مِن أغصانها، وأنها تثمر ثياب أهل الجنة، وأنها تخرج منها الخيل بسُرُجِها ولُجُمها، ونحو هذا مما لم يثبت سنده».", "mawaqif": [{"taliq": 3520, "mi": 0, "aya": 29, "alam": "ابن عطية", "fil": "انتقد", "kind": "نقد", "ref": "5/ 203 - 204", "qawl": "", "nass": "وحكى الطبري عن أبي هريرة، وعن مغيث بن سمي، وعتبة بن عبد يرفعه، أخبارا مقتضاها أن هذه الشجرة ليس دار في الجنة إلا وفيها من أغصانها، وأنها تثمر ثياب أهل الجنة، وأنها تخرج منها الخيل بسرجها ولجمها، ونحو هذا مما لم يثبت سنده", "qawaid": ["نقد الرواية (السند، الإسرائيليات)"], "tabi": ""}]}, {"id": 3521, "kinds": "تعليق،نقل", "text": "علَّق ابنُ عطية (5/ 203) على القول بأنّ طوبى اسم شجرة في الجنة بقوله: «وبهذا تواترت الأحاديث، قال رسول الله صلى الله عليه وسلم: «طوبى: شجرة في الجنة، يسير الراكب المُجِدُّ في ظلها مائة عام لا يقطعها، اقرؤوا إن شئتم: {وظل ممدود} [الواقعة: 30]»».\nوذكر ابنُ كثير (8/ 142) قول ابن عباس من طريق علي بن أبي طلحة: فرح وقُرة عين. وقول عِكْرِمة: نعم ما لهم. وقول الضحاك: غبطة لَهُم. وقول إبراهيم النَّخعي: خير لهم. وقول قتادة: هي كلمة عربية، يقول الرجل: طوبى لك، أي: أصبت خيرًا. وقال في رواية: {طُوبى لَهُمْ}: حسنى لهم، ثم علَّق عليها بقوله: «وهذه الأقوال شيء واحد، لا منافاة بينها».", "mawaqif": [{"taliq": 3521, "mi": 0, "aya": 29, "alam": "ابن عطية", "fil": "علق", "kind": "تعليق", "ref": "5/ 203", "qawl": "بأن طوبى", "nass": "وبهذا تواترت الأحاديث، قال رسول الله صلى الله عليه وسلم: «طوبى: شجرة في الجنة، يسير الراكب المجد في ظلها مائة عام لا يقطعها، اقرؤوا إن شئتم: {وظل ممدود} [الواقعة: 30]»", "qawaid": [], "tabi": ""}, {"taliq": 3521, "mi": 0, "aya": 29, "alam": "ابن كثير", "fil": "ذكر", "kind": "نقل", "ref": "8/ 142", "qawl": "ابن عباس", "nass": "وهذه الأقوال شيء واحد، لا منافاة بينها", "qawaid": [], "tabi": ""}]}], "30": [{"id": 3522, "kinds": "تعليق،نقل", "text": "علَّق ابنُ عطية (5/ 204) على ما أفادته هذه الآثار من قول قريش: لا نعرف الرحمن ولا نُقِرُّ اسمَه. فقال: «والذي أقول في هذا: إن {الرحمن} هنا يراد به الله تعالى وذاته، ونُسِبَ إليهم الكفر به على الإطلاق، وقصة الحديبية وقصة أمية بن خلف مع عبد الرحمن بن عوف إنما هي عن إباية الاسم فقط، وهروب عن هذه العبارة التي لم يعرفوها إلا من قِبَلِ محمد صلى الله عليه وسلم».", "mawaqif": [{"taliq": 3522, "mi": 0, "aya": 30, "alam": "ابن عطية", "fil": "علق", "kind": "تعليق", "ref": "5/ 204", "qawl": "قريش", "nass": "والذي أقول في هذا: إن {الرحمن} هنا يراد به الله تعالى وذاته، ونسب إليهم الكفر به على الإطلاق، وقصة الحديبية وقصة أمية بن خلف مع عبد الرحمن بن عوف إنما هي عن إباية الاسم فقط، وهروب عن هذه العبارة التي لم يعرفوها إلا من قبل محمد صلى الله عليه وسلم", "qawaid": [], "tabi": ""}]}], "31": [{"id": 3524, "kinds": "ترجيح،بيان،نقل", "text": "ذكر ابنُ جرير (13/ 535 - 537) اختلاف أهل العربية في معنى قوله تعالى: {أفلمْ ييأس}، وأنّ فرقة منهم قالت: {ييأس} بمعنى: يعلم. وأن الفرقة الأخرى ذكرت أنّ اليأس على وجهه. ثم ذكر أنّ أهل التأويل من السلف على القول الأول.\nورجّحه (13/ 538) مستندًا إلى الإجماع واللغة، فقال: «والصواب من القول في ذلك ما قاله أهل التأويل: إنّ تأويل ذلك: أفلم يتبين ويعلم. لإجماع أهل التأويل على ذلك، والأبيات التي أنشدناها فيه». وقد فسره بمعنى اليأس أبو العالية، فذكر أنّ المعنى: قد يئس الذين آمنوا أن يهدوا واحدًا.\nوذكر ابنُ عطية (5/ 206) أنّ اليأس: «يحتمل أن يكون في هذه الآية على بابه، وذلك أنه لما أبعد إيمانهم في قوله: {ولَوْ أنَّ قُرْآنًا} الآية على التأويلين في المحذوف المقدَّر، قال في هذه الآية: أفلم ييئس المؤمنون مِن إيمان هؤلاء الكفرة علمًا منهم أن لو شاء الله لهدى الناس جميعًا».", "mawaqif": [{"taliq": 3524, "mi": 0, "aya": 31, "alam": "ابن جرير", "fil": "ذكر", "kind": "نقل", "ref": "13/ 535 - 537", "qawl": "الأول", "nass": "والصواب من القول في ذلك ما قاله أهل التأويل: إن تأويل ذلك: أفلم يتبين ويعلم. لإجماع أهل التأويل على ذلك، والأبيات التي أنشدناها فيه", "qawaid": ["الإجماع", "اللغة"], "tabi": ""}, {"taliq": 3524, "mi": 0, "aya": 31, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "5/ 206", "qawl": "", "nass": "يحتمل أن يكون في هذه الآية على بابه، وذلك أنه لما أبعد إيمانهم في قوله: {ولو أن قرآنا} الآية على التأويلين في المحذوف المقدر، قال في هذه الآية: أفلم ييئس المؤمنون من إيمان هؤلاء الكفرة علما منهم أن لو شاء الله لهدى الناس جميعا", "qawaid": [], "tabi": ""}]}], "36": [{"id": 3526, "kinds": "نقد،بيان،تعليق،نقل", "text": "علَّق ابنُ عطية (3/ 319 ط: دار الكتب العلمية) على قول ابن زيد بقوله: «والمعنى: مدحهم بأنهم لشدة إيمانهم يسرون بجميع ما يرد على النبي صلى الله عليه وسلم من زيادات الشرع». وذكر ابنُ عطية (5/ 210) أنّ فرقة قالت: المراد بلذين آتَيْناهُمُ الكِتابَ: اليهود والنصارى، وعلَّق عليه بقوله: «وذلك أنهم لهم فرح بما ينزل على النبي صلى الله عليه وسلم مِن تصديق شرائعهم، وذكر أوائلهم». ثم انتقده مستندًا إلى الدلالة العقلية، فقال: «ويضعف هذا التأويل بأنّ همهم به أكثر من فرحهم، فلا يُعتدُّ بفرحهم، ويُضعَّفُ أيضًا بأن اليهود والنصارى ينكرون بعضه، وقد فرَّق الله في هذه الآية بين الذين ينكرون بعضه وبين الذين آتيناهم الكتاب».", "mawaqif": [{"taliq": 3526, "mi": 0, "aya": 36, "alam": "ابن عطية", "fil": "علق", "kind": "تعليق", "ref": "3/ 319 ط: دار الكتب العلمية", "qawl": "ابن زيد", "nass": "والمعنى: مدحهم بأنهم لشدة إيمانهم يسرون بجميع ما يرد على النبي صلى الله عليه وسلم من زيادات الشرع", "qawaid": [], "tabi": ""}, {"taliq": 3526, "mi": 0, "aya": 36, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "5/ 210", "qawl": "", "nass": "وذلك أنهم لهم فرح بما ينزل على النبي صلى الله عليه وسلم من تصديق شرائعهم، وذكر أوائلهم", "qawaid": ["الدلالة العقلية"], "tabi": ""}]}], "39": [{"id": 3528, "kinds": "توجيه", "text": "وجَّه ابنُ عطية (5/ 213) هذا الدعاء الوارد عن عمر وابن مسعود بقوله: «وهذا دعاء في غفران الذنوب، وعلى جهة الجزع منهما، أي: اللهم، إن كُنّا شقينا بمعصيتك، وكُتِب علينا ذنوب وشقاوة بها؛ فامْحُها عنا بالمغفرة. ولم يكن دعاؤهما البتة في تبديل سابق القضاء، ولا يُتَأوَّل عليهما ذلك».", "mawaqif": [{"taliq": 3528, "mi": 0, "aya": 39, "alam": "ابن عطية", "fil": "وجه", "kind": "توجيه", "ref": "5/ 213", "qawl": "", "nass": "وهذا دعاء في غفران الذنوب، وعلى جهة الجزع منهما، أي: اللهم، إن كنا شقينا بمعصيتك، وكتب علينا ذنوب وشقاوة بها؛ فامحها عنا بالمغفرة. ولم يكن دعاؤهما البتة في تبديل سابق القضاء، ولا يتأول عليهما ذلك", "qawaid": [], "tabi": ""}]}, {"id": 3529, "kinds": "نقد،نقل", "text": "ذكر ابنُ عطية (5/ 213) أنّ أبا المعالي في التلخيص قال بأنّ علي بن أبي طالب هو الذي قال هذه المقالة المذكورة عن كعب. وانتقده بقوله: «وذلك عندي لا يصِحُّ عن علي».", "mawaqif": [{"taliq": 3529, "mi": 0, "aya": 39, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "5/ 213", "qawl": "", "nass": "وذلك عندي لا يصح عن علي", "qawaid": [], "tabi": ""}]}], "43": [{"id": 3534, "kinds": "نقد،تعليق،نقل", "text": "ذكر ابنُ جرير (13/ 586) هذه القراءة عن الحسن من رواية شيخه بِشْر بسنده عن قتادة عن الحسن، ثم انتقد رواية بِشْر مستندًا إلى اللغة، فقال: «هكذا حدثنا به بشر: (عُلِمَ الكِتابُ)، وأنا أحسبه وهِمَ فيه، وأنه: (ومِن عِندِهِ عِلْمُ الكِتابِ)، لأنّ قوله:» وجملتُه «اسم، لا يُعطَف باسمٍ على فعل ماض».\nوذكر ابنُ عطية (5/ 217) هذه القراء، ة وقراءة: {ومِن عندِه عِلْمُ الكتاب}، ثم علَّق بقوله: «وهذه القراءات يُراد فيها اللهُ تعالى، لا يحتمل لفظها غير ذلك».", "mawaqif": [{"taliq": 3534, "mi": 0, "aya": 43, "alam": "ابن جرير", "fil": "ذكر", "kind": "نقل", "ref": "13/ 586", "qawl": "", "nass": "هكذا حدثنا به بشر: (علم الكتاب)، وأنا أحسبه وهم فيه، وأنه: (ومن عنده علم الكتاب)، لأن قوله:", "qawaid": ["اللغة"], "tabi": ""}, {"taliq": 3534, "mi": 0, "aya": 43, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "5/ 217", "qawl": "", "nass": "وهذه القراءات يراد فيها الله تعالى، لا يحتمل لفظها غير ذلك", "qawaid": [], "tabi": ""}]}, {"id": 3535, "kinds": "نقد،نقل", "text": "انتقد ابنُ تيمية (4/ 98 - 99 بتصرف) القول بأنّ {من عنده علم الكتاب} المراد به علي بن أبي طالب مستندًا إلى عدم الصحة، ومخالفة الجمهور، والدلالة العقلية، بما مفاده الآتي: الأول: عدم ثبوته. الثاني: أنّه بتقدير ثبوته ليس بحجة مع مخالفة الجمهور له. الثالث: بطلانه قطعًا؛ لأنّه لو أُريد بالآية عليًّا لما كان لشهادته نفع للنبي، ولا يكون ذلك حُجَّةً له على الناس؛ لأنهم يقولون: مِن أين لعليٍّ ذلك؟ وإنما هو استفاد ذلك من محمد، فيكون محمد هو الشاهد لنفسه. ومنها أن يقال: إنّ هذا ابن عمه ومن أول مَن آمن به، فيظن به المحاباة، والشاهد إن لم يكن عالمًا بما يشهد به، بريئًا من التهمة، لم يحكم بشهادته، ولم يكن حجة على المشهود عليه، فكيف إذا لم يكن له علم بها إلا من المشهود له؟!.\nوظاهر كلام ابن تيمية ترجيحُه أنّ المراد بمن عنده علم الكتاب: أهل الكتاب، استنادًا للدلالة العقلية، والنظائر، فقال: «وأما أهل الكتاب فإذا شهدوا بما تواتر عندهم عن الأنبياء وبما علم صدقه كانت تلك شهادةً نافعة، كما لو كان الأنبياء موجودين وشهدوا له؛ لأنّ ما ثبت نقله عنهم بالتواتر وغيره كان بمنزلة شهادتهم أنفسهم. ولهذا نحن نشهد على الأمم بما علمناه من جهة نبينا، كما قال تعالى: {وكذلك جعلناكم أمة وسطا لتكونوا شهداء على الناس ويكون الرسول عليكم شهيدا} [البقرة: 143]، … والله? قد ذكر الاستشهاد بأهل الكتاب في غير آية، كقوله تعالى: {قل أرأيتم إن كان من عند الله ثم كفرتم به} [فصلت: 52]، {وشهد شاهد من بني إسرائيل على مثله} [الأحقاف: 10] أفترى عليًّا هو مِن بني إسرائيل؟ وقال تعالى: {فإن كنت في شك مما أنزلنا إليك فاسأل الذين يقرءون الكتاب من قبلك} [يونس: 94]، فهل كان علي من الذين يقرءون الكتاب من قبله؟ وقال: {وما أرسلنا من قبلك إلا رجالا نوحي إليهم} [يوسف: 109]، {فاسألوا أهل الذكر} [النحل: 43] فهل أهل الذكر الذين يسألونهم هل أرسل الله إليهم رجالًا هم علي بن أبي طالب؟!».", "mawaqif": [{"taliq": 3535, "mi": 0, "aya": 43, "alam": "ابن تيمية", "fil": "انتقد", "kind": "نقد", "ref": "4/ 98 - 99 بتصرف", "qawl": "بأن", "nass": "وأما أهل الكتاب فإذا شهدوا بما تواتر عندهم عن الأنبياء وبما علم صدقه كانت تلك شهادة نافعة، كما لو كان الأنبياء موجودين وشهدوا له؛ لأن ما ثبت نقله عنهم بالتواتر وغيره كان بمنزلة شهادتهم أنفسهم. ولهذا نحن نشهد على الأمم بما علمناه من جهة نبينا، كما قال تعالى: {وكذلك جعلناكم أمة وسطا لتكونوا شهداء على الناس ويكون الرسول عليكم شهيدا} [البقرة: 143]، … والله? قد ذكر الاستشهاد بأهل الكتاب في غير آية، كقوله تعالى: {قل أرأيتم إن كان من عند الله ثم كفرتم به} [فصلت: 52]، {وشهد شاهد من بني إسرائيل على مثله} [الأحقاف: 10] أفترى عليا هو من بني إسرائيل؟ وقال تعالى: {فإن كنت في شك مما أنزلنا إليك فاسأل الذين يقرءون الكتاب من قبلك} [يونس: 94]، فهل كان علي من الذين يقرءون الكتاب من قبله؟ وقال: {وما أرسلنا من قبلك إلا رجالا نوحي إليهم} [يوسف: 109]، {فاسألوا أهل الذكر} [النحل: 43] فهل أهل الذكر الذين يسألونهم هل أرسل الله إليهم رجالا هم علي بن أبي طالب؟!", "qawaid": ["غير ذلك", "أقوال السلف", "الدلالة العقلية", "القرآن والنظائر"], "tabi": ""}]}, {"id": 3536, "kinds": "خلاف،ترجيح،نقد،توجيه،بيان،تعليق،نقل", "text": "اختُلِف في معنى قوله تعالى: {ومن عنده علم الكتاب} بحسب اختلاف القرّاء في كيفية قراءتها، فقد قرأها بعض القراء بفتح ميم: {من} وفتح دال {عنده}، وقرأها آخرون بكسر ميم {من} وكسر دال {عنده}.\nوقد وجَّه ابنُ جرير (13/ 582) القراءة الأولى، وبيَّن المعنى عليها بقوله: «فـ {من} إذا قرئ كذلك في موضع خفض عطفًا به على اسم الله، وكذلك قرأته قَرَأَة الأمصار، بمعنى: والذين عندهم علم الكتاب، أي: الكتب التي نزلت قبل القرآن كالتوراة والإنجيل». ثم علَّق بقوله: «على هذه القراءة فسَّر ذلك المفسرون». ثم ذكر أقوال المفسرين بأن مَن عنده علم الكتاب اليهود والنصارى، سواء في ذلك مَن فسَّرها بمعيَّن منهم كعبد الله بن سلام، أو فسرها بذلك دون تعيين.\nوبنحوه قال ابنُ عطية (5/ 216 - 217) واستدرك مستندًا إلى أحوال النزول على هذا المعنى بأنّه لا يستقيم «إلا بأن تكون الآية مدنية، والجمهور على أنها مكية».\nوانتقد ابنُ كثير (8/ 171) تفسير الآية بعبد الله بن سلام مستندًا إلى أحوال النزول، فقال: «وهذا القول غريب؛ لأن هذه الآية مكية، وعبد الله بن سلام إنما أسلم في أول مقدم رسول الله صلى الله عليه وسلم المدينة». واستظهر رواية العوفي عن ابن عباس، فقال: «والأظهر في هذا ما قاله العوفي عن ابن عباس، قال: هم من اليهود والنصارى».\nوزاد ابنُ عطية (5/ 216) معنى آخر تحتمله هذه القراءة، فقال: «وقيل: يريد الله تعالى، كأنه استشهد بالله تعالى، ثم ذَكَرَه بهذه الألفاظ التي تتضمن صفة تعظيم». ثم انتقده مستندًا إلى اللغة، فقال: «ويُعتَرَض هذا القول بأنّ فيه عطف الصفة على الموصوف، وذلك لا يجوز وإنّما تعطف الصفات بعضها على بعض». ثم قال: «ويحتمل أن تكون {مَن} في موضع رفع بالابتداء، والخبر محذوف، تقديره: أعدل وأمضى قولًا، ونحو هذا مما يدل عليه لفظ: {شهيدا}، ويُراد بذلك الله تعالى».\nوبَيَّن ابنُ جرير (13/ 584) أنّ المعنى على القراءة الثانية: «مِن عندِ الله علم الكتاب».\nوبنحوه ابنُ عطية (5/ 217).\nوانتقد ابنُ جرير (13/ 587) الحديث المروي عن رسول الله صلى الله عليه وسلم بتصحيح هذه القراءة بأنّ في إسناده نظرًا لعدم اتّصاله، فقال: «وهذا خبر ليس له أصل عند الثقات من أصحاب الزهري».\nوكذا ابنُ كثير (8/ 171 - 172) فقد أورد كلام ابن جرير، ثم قال: «قلت: وقد رواه الحافظ أبو يعلى في مسنده، من طريق هارون بن موسى هذا، عن سليمان بن أرقم -وهو ضعيف -عن الزهري، عن سالم، عن أبيه مرفوعًا كذلك. ولا يثبت».\nورجَّح ابنُ جرير (13/ 587) مستندًا إلى القراءات المعنى الأول بقوله: «فإذ كان ذلك كذلك، وكانت قَرَأة الأمصار من أهل الحجاز والشام والعراق على القراءة الأخرى، وهي: {ومَن عنده علم الكتاب}، كان التأويل الذي على المعنى الذي عليه قرأة الأمصار أولى بالصواب مِمّا خالفه، إذ كانت القراءة بما هم عليه مجمعون أحقُّ بالصواب».\nوكذا رجَّحه ابنُ كثير (8/ 172)، فقال: «والصحيح في هذا: أنّ {ومَن عِنْدَهُ} اسم جنس يشمل علماء أهل الكتاب الذين يجدون صفة محمد صلى الله عليه وسلم ونعتَه في كتبهم المتقدمة مِن بشارات الأنبياء به، كما قال تعالى: {ورَحْمَتِي وسِعَتْ كُلَّ شَيْءٍ فَسَأَكْتُبُها لِلَّذِينَ يَتَّقُونَ ويُؤْتُونَ الزَّكاةَ والَّذِينَ هُمْ بِآياتِنا يُؤْمِنُونَ الَّذِينَ يَتَّبِعُونَ الرَّسُولَ النَّبِيَّ الأمِّيَّ الَّذِي يَجِدُونَهُ مَكْتُوبًا عِنْدَهُمْ فِي التَّوْراةِ والإنْجِيلِ} الآية [الأعراف: 156 - 157]. وقال تعالى: {أوَلَمْ يَكُنْ لَهُمْ آيَةً أنْ يَعْلَمَهُ عُلَماءُ بَنِي إسْرائِيلَ} الآية [الشعراء: 197]. وأمثال ذلك مما فيه الإخبار عن علماء بني إسرائيل: أنّهم يعلمون ذلك مِن كتبهم المنزلة».", "mawaqif": [{"taliq": 3536, "mi": 0, "aya": 43, "alam": "ابن جرير", "fil": "وجه", "kind": "توجيه", "ref": "13/ 582", "qawl": "", "nass": "ف {من} إذا قرئ كذلك في موضع خفض عطفا به على اسم الله، وكذلك قرأته قرأة الأمصار، بمعنى: والذين عندهم علم الكتاب، أي: الكتب التي نزلت قبل القرآن كالتوراة والإنجيل", "qawaid": [], "tabi": ""}, {"taliq": 3536, "mi": 0, "aya": 43, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "5/ 216 - 217", "qawl": "", "nass": "إلا بأن تكون الآية مدنية، والجمهور على أنها مكية", "qawaid": ["سبب النزول وأحواله"], "tabi": "ابن جرير"}, {"taliq": 3536, "mi": 0, "aya": 43, "alam": "ابن كثير", "fil": "انتقد", "kind": "نقد", "ref": "8/ 171", "qawl": "", "nass": "وهذا القول غريب؛ لأن هذه الآية مكية، وعبد الله بن سلام إنما أسلم في أول مقدم رسول الله صلى الله عليه وسلم المدينة", "qawaid": ["سبب النزول وأحواله"], "tabi": ""}, {"taliq": 3536, "mi": 0, "aya": 43, "alam": "ابن عطية", "fil": "زاد", "kind": "نقل", "ref": "5/ 216", "qawl": "", "nass": "وقيل: يريد الله تعالى، كأنه استشهد بالله تعالى، ثم ذكره بهذه الألفاظ التي تتضمن صفة تعظيم", "qawaid": ["اللغة"], "tabi": ""}, {"taliq": 3536, "mi": 0, "aya": 43, "alam": "ابن جرير", "fil": "بين", "kind": "بيان", "ref": "13/ 584", "qawl": "", "nass": "من عند الله علم الكتاب", "qawaid": [], "tabi": ""}, {"taliq": 3536, "mi": 0, "aya": 43, "alam": "ابن عطية", "fil": "وبنحوه", "kind": "موافقة", "ref": "5/ 217", "qawl": "", "nass": "", "qawaid": [], "tabi": "ابن جرير"}, {"taliq": 3536, "mi": 0, "aya": 43, "alam": "ابن جرير", "fil": "انتقد", "kind": "نقد", "ref": "13/ 587", "qawl": "", "nass": "وهذا خبر ليس له أصل عند الثقات من أصحاب الزهري", "qawaid": [], "tabi": ""}, {"taliq": 3536, "mi": 0, "aya": 43, "alam": "ابن كثير", "fil": "وكذا", "kind": "موافقة", "ref": "8/ 171 - 172", "qawl": "", "nass": "قلت: وقد رواه الحافظ أبو يعلى في مسنده، من طريق هارون بن موسى هذا، عن سليمان بن أرقم -وهو ضعيف -عن الزهري، عن سالم، عن أبيه مرفوعا كذلك. ولا يثبت", "qawaid": [], "tabi": "ابن جرير"}, {"taliq": 3536, "mi": 0, "aya": 43, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "13/ 587", "qawl": "الأول", "nass": "فإذ كان ذلك كذلك، وكانت قرأة الأمصار من أهل الحجاز والشام والعراق على القراءة الأخرى، وهي: {ومن عنده علم الكتاب}، كان التأويل الذي على المعنى الذي عليه قرأة الأمصار أولى بالصواب مما خالفه، إذ كانت القراءة بما هم عليه مجمعون أحق بالصواب", "qawaid": ["القراءة ورسم المصحف"], "tabi": ""}, {"taliq": 3536, "mi": 0, "aya": 43, "alam": "ابن كثير", "fil": "رجحه", "kind": "ترجيح", "ref": "8/ 172", "qawl": "", "nass": "والصحيح في هذا: أن {ومن عنده} اسم جنس يشمل علماء أهل الكتاب الذين يجدون صفة محمد صلى الله عليه وسلم ونعته في كتبهم المتقدمة من بشارات الأنبياء به، كما قال تعالى: {ورحمتي وسعت كل شيء فسأكتبها للذين يتقون ويؤتون الزكاة والذين هم بآياتنا يؤمنون الذين يتبعون الرسول النبي الأمي الذي يجدونه مكتوبا عندهم في التوراة والإنجيل} الآية [الأعراف: 156 - 157]. وقال تعالى: {أولم يكن لهم آية أن يعلمه علماء بني إسرائيل} الآية [الشعراء: 197]. وأمثال ذلك مما فيه الإخبار عن علماء بني إسرائيل: أنهم يعلمون ذلك من كتبهم المنزلة", "qawaid": [], "tabi": "ابن جرير"}]}, {"id": 3537, "kinds": "تعليق،نقل", "text": "أورد ابنُ كثير (8/ 172 - 173) هذا الحديث مبينًا ما ذُكر عن عبد الله بن سلام بأنه أسلم بمكة قبل الهجرة، وذلك من طريق أبي نعيم الأصبهاني بسنده عن عبد الله بن سلام رضي الله عنهما، ثم علَّق عليه بقوله: «وهذا غريب جدًّا».", "mawaqif": [{"taliq": 3537, "mi": 0, "aya": 43, "alam": "ابن كثير", "fil": "أورد", "kind": "نقل", "ref": "8/ 172 - 173", "qawl": "", "nass": "وهذا غريب جدا", "qawaid": [], "tabi": ""}]}]}, "athar": {"38912": {"num": 38912, "aya": 14, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق علي بن أبي طلحة- في قوله: {كباسطِ كفَّيه إلى الماءِ ليبلُغ فاهُ}، قال: هذا مَثَلُ المُشْركِ الذي عَبَدَ معَ اللهِ غيرَه، فمثلُه كمَثَل الرجل العطشان الذي ينظر إلى خياله في الماء مِن بعيدٍ، وهو يريد أن يتناوله ولا يَقْدِرُ عليه."}, "38913": {"num": 38913, "aya": 14, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس: كالعطشان إذا بسط كفيه في الماء، لا ينفعه ذلك ما لم يَغْرِف بهما الماء، ولا يبلغ الماءُ فاهُ ما دام باسِطًا كَفَّيْه. وهو مَثَلٌ ضربه لِخَيْبَةِ الكُفّار."}, "38914": {"num": 38914, "aya": 14, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- في قوله: {كباسطِ كفَّيه إلى الماءِ}، قال: يدعو الماءَ بلسانه، ويُشير إليه بيده، ولا يأتيه أبدًا."}, "38915": {"num": 38915, "aya": 14, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق الأعرج- في قوله: {ليبلغ فاه}، قال: يدعوه ليأتيه، وما هو بآتيه، كذلك لا يستجيب مَن هو دونه."}, "38916": {"num": 38916, "aya": 14, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- {والذين يدعُون من دونه لا يستجيبون لهُم بشيءٍ إلا كباسطِ كفَّيه إلى الماءِ ليبلغ فاهُ وما هُو ببالغِهِ}: وليس ببالغِه حتى يَتَمزَّع عُنُقُه، ويهلِكَ عطشًا، قال الله: {وما دُعاءُ الكافرينَ إلا في ضلالٍ}. فهذا مَثَلٌ ضربه الله؛ إنّ هذا الذي يَدْعون مِن دون الله -هذا الوثنُ وهذا الحجرُ- لا يستجيبُ له بشيءٍ في الدنيا، ولا يسوقُ إليه خيرًا، ولا يدفع عنه سوءًا حتى يأتيه الموتُ، كمثل هذا الذي يبسُطُ ذراعيه إلى الماء ليبلغ فاه، ولا يبلُغُ فاه ولا يَصِلُ ذلك إليه حتى يموت عطشًا."}, "39180": {"num": 39180, "aya": 31, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "تفسير الآية", "text": "عن عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- {أفلم ييأس}: أفلم يعلمْ. ومِن الناس مَن يقرؤها: (أفَلَمْ يَتَبَيَّنِ). وإنما هو كالاسْتِنقاهِ، أفلم يعلمُوا أنّ الله يفعلُ ذلك؟ لم ييأسُوا من ذلك وهم يعلمون أنّ اللهَ لو شاء فعل ذلك."}, "39282": {"num": 39282, "aya": 39, "qail": "عبد الله بن مسعود", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن مسعود -من طريق القاسم بن عبد الرحمن- قال: ما دعا عبدٌ قطُّ بهذه الدعوات إلا وسَّع الله له في معيشته: يا ذا المَنَّ ولا يُمنُّ عليه، يا ذا الجلال والإكرام، يا ذا الطَّول والإنعام، لا إله إلا أنت ظَهِير اللاجئين، وجار المستجيرين، ومَأْمَن الخائفين، إن كنت كتبتني في أُمِّ الكتاب شقيًّا فامحُ عنِّي اسم الشقاء، وأَثبِتْني عندك سعيدًا، وإن كنت كتبتني عندك في أمِّ الكتاب محرومًا مُقَتَّرًا عليَّ رزقي فامحُ حرماني، ويسِّر رزقي، وأَثْبتني عندك سعيدًا مُوَفَّقًا للخير؛ فإنّك تقول في كتابك الذي أنزلت: {يمحُوا الله ما يشاءُ ويثبتُ وعندهُ أمُّ الكتابِ}."}, "39281": {"num": 39281, "aya": 39, "qail": "عمر بن الخطاب", "tabaqa": "صحابي", "bab": "", "text": "عن عمر بن الخطاب -من طريق أبي عثمان النَّهدي- أنّه قال وهو يطوفُ بالبيت: اللهمَّ، إن كنتَ كتبتَ عَلَيَّ شِقْوةً أو ذنبًا فامْحُهُ؛ فإنّك تمحو ما تشاءُ وتثبت وعندك أمَّ الكتاب، فاجعله سعادةً ومغفرةً."}, "38922": {"num": 38922, "aya": 14, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق الضَّحّاك-: {وما دعاء الكافرين} ربهم {إلا في ضلال}؛ لأنّ أصواتَهم محجوبةٌ عن الله تعالى."}, "39283": {"num": 39283, "aya": 39, "qail": "عبد الله بن مسعود", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن مسعود -من طريق أبي قلابة- أنّه كان يقولُ: اللهمَّ، إن كنتَ كتبتني في السعداءِ فأثْبِتْني في السعداء، وإن كنت كتبتني في الأشقياءِ فامحُني مِن الأشقياء وأَثْبِتْنِي في السعداء، فإنّك تمحُو ما تشاءُ وتُثْبِتُ، وعندك أمُّ الكتابِ."}, "39182": {"num": 39182, "aya": 31, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "نزول الآية", "text": "عن قتادة بن دعامة، قال: سورةُ الرعد مدنِيَّةٌ، إلا آيةً مَكِّيَّةً: {ولا يزالُ الَّذين كفرُوا تُصيبهُمُ بما صنعُوا قارعةٌ}."}, "38955": {"num": 38955, "aya": 17, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "وعبد الله بن عباس -من طريق السدي، عن أبي مالك وأبي صالح- في قوله: {فسالتْ أودية بقدرها} الآية، قال: فمَرَّ السَّيلُ على رأسه مِن التراب والغُثاءِ حتى استقَرَّ في القَرارِ وعليه الزَّبَدُ، فضَرَبَتْه الريحُ، فذهب الزَّبَدُ جفاءً إلى جوانبه، فيَبِس، فلم ينفع أحدًا، وبَقِي الماءُ الذي ينتفع به الناسُ، فشربوا منه، وسَقَوْا أنعامهم، فكما ذهب الزَّبَدُ فلم ينفع، فكذلك الباطلُ يَضْمَحِلُّ يوم القيامة فلا ينفع أهله، وكما نفع الماءُ فكذلك ينفعُ الحقُّ أهله، هذا مَثَلٌ ضربه الله."}, "38956": {"num": 38956, "aya": 17, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق علي بن أبي طلحة- في قوله: {أنزَلَ من السَّماء ماءً} الآية، قال: هذا مَثَلٌ ضربه اللهُ، احْتَمَلَتْ مِنه القلوبُ على قدْرِ يقينها وشكِّها؛ فأمّا الشَّكُّ فما ينفع معه العَمَلُ، وأَمّا اليقين فينفعُ الله به أهلَه، وهو قولُه: {فأمّا الزبدُ فَيَذهبُ جُفاءً} وهو الشكُّ، {وأمّا ما ينفعُ النّاس فيمكُثُ في الأرضِ} وهو اليقينُ، وكما يُجْعَلُ الحُلِيُّ في النار، فيؤخذُ خالصُه به، ويُتْرَكُ خَبَثُه في النار؛ كذلك يقبلُ اللهُ اليقينَ، ويترُكُ الشَّكَّ."}, "38957": {"num": 38957, "aya": 17, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق ابن جُرَيْج- في قوله: {فسألتْ أودية بقدرها}، قال: الصغيرُ قَدْرَ صِغَرِه، والكبيرُ قَدْرَ كِبرَه."}, "38958": {"num": 38958, "aya": 17, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق العوفي- في الآية، قال: هذا مَثَلٌ ضربه اللهُ بين الحقِّ والباطل، يقول: احتمل السيلُ ما في الوادي مِن عودٍ ودِمْنَةٍ، «ومِمّا تُوقِدُونَ عَلَيْهِ فِي النّارِ»، فهو الذهبُ والفِضَّةُ والحِلْيَةُ، والمتاعُ: النُّحاسُ والحديدُ، وللنُّحاس والحديد خَبَثٌ، فجعل الله مَثَل خَبَثِه كمَثَل زَبَد الماء، فأمّا ما ينفع الناسُ فالذَّهبُ والفِضَّةُ، وأَمّا ما ينفع الأرضَ فما شَرِبَتْ مِن الماء فأَنبَتَتْ، فجعل ذلك مَثَلَ العمل الصالح الذي يَبْقى لأهله، والعمل السَّيِّئ يَضْمَحِلُّ عن أهله كما يذهبُ هذا الزَّبَد، فذلك الهُدى والحقُّ جاء مِن عند الله، فمَن عَمِل بالحقِّ كان له، وبَقِي كما يبقى ما ينفع الناسَ في الأرضِ، وكذلك الحديدُ لا يُسْتَطاعُ أن يُعْمَل منه سِكِّينٌ ولا سَيْفٌ حتى يُدْخل النار، فتأكل خبثه، فيخرُج جَيِّده فينتفع به، كذلك يَضْمَحِلُّ الباطل إذا كان يوم القيامة، وأُقيم الناسُ، وعُرِضَت الأعمالُ، فيرفعُ الباطلُ ويهلكُ، وينتفع أهلُ الحقِّ بالحقِّ."}, "38959": {"num": 38959, "aya": 17, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق عبد الله بن كثير- في قوله: {أنزل من السَّماءً ماء فسالتْ أوديةٌ بقدرها} قال: بمِلْئِها ما أطاقَتْ، {فاحتملَ السيلُ زبدًا رابيًا} قال: انقَضى الكلامُ، ثُمَّ اسْتَقْبل فقال: {وممّا يوقدون عليه في النّار ابتغاءَ حليةٍ أو متاعٍ زبدٌ مثله} قال: فالمتاع: الحديد، والنُّحاسُ، والرَّصاصُ، وأشباهُه، {زبدٌ مثلُهُ} قال: خَبَثُ ذلك الحديد والحلية مثل زَبَد السَّيْل، {وأمّا ما ينفعُ النّاس} مِن الماء {فيمكُثُ في الأرض}، وأمّا الزبد {فيذهبُ جُفاءً} قال: جُمودًا في الأرض، قال: فذلك مَثَلُ الحقِّ والباطلِ."}, "38960": {"num": 38960, "aya": 17, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق شبل وورقاء عن ابن أبي نجيح، يزيد أحدهما على صاحبه- في قوله: {فسالت أودية بقدرها} قال: بملئها، {فاحتمل السيل زبدا رابيا} قال: الزبد: السيل، {ابتغاء حلية أو متاع زبد مثله} قال: خَبَث الحديد والحلية، {فأما الزبد فيذهب جفاء} قال: جمودًا في الأرض، {وأما ما ينفع الناس فيمكث في الأرض} قال: الماء، وهما مثَلان للحق والباطل."}, "38962": {"num": 38962, "aya": 17, "qail": "عطاء بن أبي رباح", "tabaqa": "تابعي", "bab": "", "text": "عن عطاء [بن أبي رباح]-من طريق طلحة بن عمرو- قال: ضرب اللهُ مَثَلَ الحقِّ والباطل، فضرب مَثَل الحقِّ السَّيْلَ الذي يمكُثُ في الأرض فينفعُ الناسَ، ومثلَ الباطل مَثَل الزَّبَد الذي لا ينفعُ الناسَ، ومَثَل الحقِّ مثل الحُلِيِّ الذي يُجعَلُ في النار، فما خَلَصَ منه انتفع به أهلُه، وما خبُث منه فهو مَثَل الباطل، عُلِم ألّا ينفع الزَّبد وخَبَثُ الحُلِيِّ أهلَه، فكذلك الباطلُ لا ينفعُ أهلَه."}, "38963": {"num": 38963, "aya": 17, "qail": "عطاء", "tabaqa": "تابعي", "bab": "", "text": "عن عطاءٍ، في قوله: {أنزَلَ من السماءِ ماءً} قال: هذا مثلٌ ضَرَبَهُ اللهُ للمؤمنِ والكافرِ، {فسالتْ أوديةٌ بقدرها} قال: جَرى الوادي، وامتلأ بقدْر ما يحملُ، {فاحتمَلَ السيْلُ زبدًا رابيًا} قال: زَبدَ الماءِ، {وممّا توقدونَ عليه في النارِ} قال: زبدُ ما تُوقدون عليه مِن ذلك حليةٌ، وما سقط فهو مَثَلُ زَبَد الماء، وهو مَثَلٌ ضُرِب للحقِّ والباطل، فأمّا خَبَثُ الحديدِ والذهبِ وزَبَدُ الماءِ فهو الباطلُ، وما يصفو مِن الحلية والماء والحديد فمَثَلُ الحقِّ."}, "38964": {"num": 38964, "aya": 17, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق مَعْمَر- في قوله: {فسالتْ أوديةٌ بقدرها} قال: الكبيرُ بقَدَرِه، والصغيرُ بقَدَره، {زبدًا رابيًا} قال: رَبا فوق الماء الزَّبَدُ، {وممّا يوقدون عليه في النار} قال: هو الذَّهبُ، إذا أُدْخِل النارَ بَقِيَ صَفْوُه، وذَهَب ما كان فيه مِن كَدَرٍ، وهذا مَثَلٌ ضربه الله للحقِّ والباطل، {فأمّا الزبدُ فيذهبُ جفاءً} يتعلق بالشَّجَرِ، ولا يكونُ شيئًا، هذا مَثَل الباطل، {وأمّا ما ينفعُ النّاسَ فيمكُثُ في الأرض} هذا يُخرج النبات، وهو مَثَلُ الحقِّ، {أو متاعٍ زبدٌ مثلُهُ} قال: المتاعُ: الصُّفْرُ، والحديدُ."}, "38965": {"num": 38965, "aya": 17, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- قوله: {أنزل من السماء ماء فسالت أودية بقدرها} الصغير بصِغَرِه، والكبير بكبره، {فاحتمل السيل زبدا رابيا} أي: عاليًا، {ومما يوقدون عليه في النار ابتغاء حلية أو متاع زبد مثله، كذلك يضرب الله الحق والباطل، فأما الزبد فيذهب جفاء} والجفاء: ما يتعلق بالشَّجَر، {وأما ما ينفع الناس فيمكث في الأرض}. هذه ثلاثة أمْثال ضَرَبها اللهُ في مَثَل واحد. يقول: كما اضْمَحَلَّ هذا الزبدُ فصار جُفاءً لا يُنتَفَعُ به، ولا تُرْجى بَرَكَتُه؛ كذلك يَضْمَحِلُّ الباطلُ عن أهله كما اضْمَحَلَّ هذا الزَّبَد، وكما مكث هذا الماءُ في الأرض، فأَمْرَعَتْ هذه الأرض، وأخْرَجَتْ نباتَها، كذلك يبقى الحقُّ لأهله كما بَقِي هذا الماءُ في الأرض، فأخرج الله به ما أخرج من النبات. قوله: {ومما يوقدون عليه في النار} الآية: كما يبقى خالِصُ الذَّهَب والفضة حين أُدْخِل النار، وذَهَبَ خَبَثُه؛ كذلك يبقى الحقُّ لأهله. قوله: {أو متاع زبد مثله} يقول: هذا الحديد والصفر الذي ينتفع به، فيه منافع، يقول: كما يبقى خالِص هذا الحديد وهذا الصفر حين أدخل النار وذهب خبثه كذلك يبقى الحقُّ لأهله كما بَقِي خالِصُهما."}, "39190": {"num": 39190, "aya": 31, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن قتادة بن دعامة -من طريق مَعْمَر- {قارعة}، قال: وقِيعَة."}, "38968": {"num": 38968, "aya": 17, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "", "text": "عن عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- قال في قوله: {ومما يوقدون عليه في النار ابتغاء حلية أو متاع زبد مثله}، قال: هذا مَثَلٌ ضَرَبَه الله للحقِّ والباطل، فقرأ: {أنزل من السماء ماء فسالت أودية بقدرها فاحتمل السيل زبدا رابيا} هذا الزَّبَد لا ينفع، {أو متاع زبد مثله} هذا لا ينفع أيضًا. قال: وبَقِي الماءُ في الأرضِ، فنَفَع الناسَ، وبَقِي الحُلِيُّ الذي صلح مِن هذا، فانتفع الناسُ به، {فأما الزبد فيذهب جفاء وأما ما ينفع الناس فيمكث في الأرض كذلك يضرب الله الأمثال}. وقال: هذا مَثَلٌ ضربه الله للحقِّ والباطل."}, "39191": {"num": 39191, "aya": 31, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن قتادة بن دعامة -من طريق سعيد- قوله: {ولا يزال الذين كفروا تصيبهم بما صنعوا قارعة}، أي: بأعمالهم أعمال السوء."}, "39193": {"num": 39193, "aya": 31, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "تفسير الآية", "text": "عن عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- في قوله: {ولا يزال الذين كفروا تصيبهم بما صنعوا قارعة}، قال: قارِعَة مِن العذاب."}, "39296": {"num": 39296, "aya": 39, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نَجِيح- قال: قالت قريشٌ حين أُنزِل: {وما كان لرسولٍ أن يأتي بآيةٍ إلا بإذن الله}: ما نراك -يا محمدُ- تملِك من شيءٍ، ولقد فُرِغ من الأمر. فأنزلت هذه الآية تخويفًا لهم ووعيدًا لهم: {يمحُوا الله ما يشاءُ ويُثْبتُ}: إنّا إن شئنا أحدثنا له مِن أمرنا ما شئنا، ويُحْدِث الله في كلِّ رمضان، فيمحو الله ما يشاءُ ويُثْبِتُ مِن أرزاق الناس، ومصائبهم، وما يُعطيهم، وما يَقسِم لهم."}, "38991": {"num": 38991, "aya": 20, "qail": "مقاتل بن سليمان", "tabaqa": "تابع التابعين", "bab": "", "text": "قال مقاتل بن سليمان: ثُمَّ نَعَتَ اللهُ أهلَ اللبِّ، فقال: {الذين يوفون بعهد الله} في التوحيد، {ولا ينقضون الميثاق} الذي أخَذَ اللهُ عليهم على عهد آدم عليه السلام. ويقال: هم مُؤْمِنو أهلِ الكتاب."}, "39297": {"num": 39297, "aya": 39, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق منصور- في قوله: {يمحُوا اللهُ ما يشاءُ ويثبت}، قال: إلّا الحياةَ والموتَ، والشقاءَ والسعادةَ؛ فإنّهما لا يَتَغَيَّران."}, "39298": {"num": 39298, "aya": 39, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق منصور- في قوله: {يمحُوا الله ما يشاءُ ويُثبتُ}، قال: الله يُنزِلُ كلَّ شيءٍ يكونُ في السنةِ في ليلة القدر، فيمحُو ما يشاءُ مِن الآجالِ والأرزاقِ والمقاديرِ، إلا الشقاءَ والسعادةَ؛ فإنّهما ثابتان."}, "39299": {"num": 39299, "aya": 39, "qail": "منصور", "tabaqa": "", "bab": "", "text": "عن منصورٍ، قال: سألتُ مجاهدًا، فقلتُ: أرأيتَ دعاءَ أحدِنا يقولُ: اللهمَّ، إن كان اسمي في السعداء فأَثْبِتْه فيهم، وإن كان في الأشقياء فامْحُهُ منهم، واجعله في السعداءِ؟ فقال: حسنٌ. ثم لقيته بعدَ ذلك بحَوْلٍ أو أكثر مِن ذلك، فسألتُه عن ذلك، فقال: {إنا أنزلنهُ في ليلةٍ مباركةٍ إنّا كنا منذرينَ* فيها يُفرقُ كل أمرٍ حكيمٍ} [الدخان: 3 - 4]. قال: يعني: في ليلةِ القدر، ما يكونُ في السنة من رزقٍ أو مصيبةٍ، ثم يُقَدِّم ما يشاءُ، ويُؤَخِّرُ ما يشاءُ، فأمّا كتابُ الشقاء والسعادة فهو ثابِتٌ لا يُغيَّرُ."}, "39300": {"num": 39300, "aya": 39, "qail": "الضحاك بن مزاحم", "tabaqa": "تابعي", "bab": "", "text": "عن الضَّحّاك بن مُزاحِم -من طريق عبيد- في الآية، قال: يقولُ: أنسَخُ ما شِئْتُ، وأَصْنَعُ مِن الأفعال ما شِئْتُ؛ إن شئتُ زِدتُ فيها، وإن شئتُ نَقَصْتُ."}, "39301": {"num": 39301, "aya": 39, "qail": "الضحاك بن مزاحم", "tabaqa": "تابعي", "bab": "", "text": "قال الضحاك بن مزاحم: إنّ الحَفَظَة يكتبون جميعَ أعمال بني آدم وأقوالهم، فيمحو الله مِن ديوان الحَفَظَة ما ليس فيه ثوابٌ ولا عقاب، مثل قوله: أكلتُ، شربتُ، دخلتُ، خرجتُ، ونحوها من كلام هو صادق فيه، ويُثْبِتُ ما فيه ثوابٌ وعقابٌ."}, "38524": {"num": 38524, "aya": 1, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق سفيان-: {المر} فواتح يفتتحُ بها كلامه."}, "38527": {"num": 38527, "aya": 1, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق سفيان- في قوله: {تلك آياتُ الكتابِ}، قال: التوراة، والإنجيل."}, "38529": {"num": 38529, "aya": 1, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- في قوله: {تلك آياتُ الكتابِ}، قال: الكتب التي كانت قبل القرآن."}, "38530": {"num": 38530, "aya": 1, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق خالد بن قيس- في قوله: {المر تلك آيات الكتاب}، قال: التوراة، والإنجيل، والزَّبور."}, "39307": {"num": 39307, "aya": 39, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "", "text": "قال الحسن البصري: {يمحو الله ما يشاء} يعني: الآباء، {ويثبت} يعني: الأبناء."}, "38533": {"num": 38533, "aya": 1, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "نزول الآية", "text": "عن مجاهد بن جبر -من طريق سفيان- في قوله: {والذي أُنزل إليك من ربك الحقُّ}، قال: القرآن."}, "38535": {"num": 38535, "aya": 1, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "نزول الآية", "text": "عن قتادة بن دعامة -من طريق سعيد- في قوله: {والذي أنزلَ إليكَ من ربك الحقُّ}، أي: هذا القرآنُ."}, "39308": {"num": 39308, "aya": 39, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "", "text": "عن الحسن البصري -من طريق قتادة- قال: مَن كَذَب بالقَدَر فقد كَذَب بالقرآن."}, "38539": {"num": 38539, "aya": 2, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس -من طريق عكرمة- في قوله: {رفع السماواتِ بغيرِ عمدِ ترونها}، قال: وما يُدْرِيك، لعلها بعمدٍ لا ترونها."}, "38540": {"num": 38540, "aya": 2, "qail": "عكرمة", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن عكرمة، قال: قلتُ لابن عباس: إنّ فلانًا يقولُ: إنها على عمدٍ. يعني: السماء، فقال: اقرأها: {بغير عَمَدٍ ترونها}، أي: لا تَرَوْنها."}, "38541": {"num": 38541, "aya": 2, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس -من طريق قتادة- في قوله: {بغير عمدٍ ترونها}، يقولُ: لها عَمَدٌ، ولكن لا ترونها. يعني: الأعمادَ."}, "38542": {"num": 38542, "aya": 2, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- في قوله: {بغيرِ عمدٍ ترونها}، قال: هي بعمد لا ترونها."}, "38545": {"num": 38545, "aya": 2, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "وقتادة بن دعامة -من طريق مَعْمَر- في قوله: {رفع السماواتِ بغيرِ عمدِ}، قالا: رفعها بغير عمد ترونها."}, "38547": {"num": 38547, "aya": 2, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "وقتادة بن دعامة -من طريق سعيد- أنهما كانا يقولان: خلقها بغير عمدٍ، قال لها: قُومي. فقامت."}, "38548": {"num": 38548, "aya": 2, "qail": "إياس بن معاوية", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن إياس بن معاوية -من طريق حماد بن سلمة- في قوله: {رفَعَ السمواتِ بغيرِ عمدٍ ترونها}، قال: السماءُ مُقَبَّبَة على الأرض مثلُ القُبَّة."}, "38550": {"num": 38550, "aya": 2, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "آثار متعلقة بالآية", "text": "عن عبد الله بن عباس -من طريق عكرمة- قال: السماءُ على أربعة أملاك، كلُّ زاويةٍ موكلٌ بها مَلَكٌ."}, "38552": {"num": 38552, "aya": 2, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- في قوله: {استوى}، قال: عَلا على العرشِ."}, "38554": {"num": 38554, "aya": 2, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "قال عبد الله بن عباس: أراد بالأجل المسمى: درجاتهما، ومنازلهما، ينتهيان إليها لا يُجاوِزانها."}, "38555": {"num": 38555, "aya": 2, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- في قوله: {كلٌ يجري لأجلٍ مسمىً}، قال: الدنيا."}, "38556": {"num": 38556, "aya": 2, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة، في قوله: {وسخَّر الشَّمس والقمر كلٌ يجري لأجلٍ مسمى}، قال: أجل معلوم، وحدٌّ لا يُقصرُ دونَه، ولا يُتَعَدّى."}, "38559": {"num": 38559, "aya": 2, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- في قوله: {يدبر الأمر}، قال: يَقْضِيه وحدَه."}, "38561": {"num": 38561, "aya": 2, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- في قوله: {لعلَّكم بلقاءِ ربكُم توقنونَ}، قال: إنّ الله إنّما أنزل كتابه وبعث رسله لِيُؤْمَن بوعده، وليُسْتَيْقَنَ بلقائه."}, "39313": {"num": 39313, "aya": 39, "qail": "إسماعيل السدي", "tabaqa": "تابعي", "bab": "", "text": "قال إسماعيل السُّدِّيّ: {يمحو الله ما يشاء} يعني: القمر، {ويثبت} يعني: الشمس."}, "39315": {"num": 39315, "aya": 39, "qail": "زيد بن أسلم", "tabaqa": "تابعي", "bab": "", "text": "عن زيد بن أسلم -من طريق القاسم بن عبد الله- أنّه قال: قال الله: {ما ننسخ من آية أو ننسها نأت بخير منها أو مثلها} [البقرة: 106]، وقال الله: {وإذا بدلنا آية}، {والله أعلم بما ينزل} [النحل: 101]، وقال: {يمحوا الله ما يشاء ويثبت وعنده أم الكتاب} …."}, "39088": {"num": 39088, "aya": 29, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس، قال: قال رسول الله صلى الله عليه وسلم: «طُوبى شجرةٌ في الجنة، غَرَسَها اللهُ بيده، ونفخ فيها مِن رُوحِه، وإنّ أغصانها لَتُرى مِن وراء سُورِ الجنة، تُنبِتُ الحُلِيَّ، والثمارُ مُتَهَدِّلَةٌ على أفواهِها»."}, "39316": {"num": 39316, "aya": 39, "qail": "محمد بن السائب الكلبي", "tabaqa": "تابع التابعين", "bab": "", "text": "عن محمد بن السائب الكلبي -من طريق همّام- في قوله: {يمحو ما يشاء ويثبت}، قال: يكتب القولَ كلَّه، حتى إذا كان يوم الخميس طرَح منه كلَّ شيء ليس فيه ثواب ولا عليه عقاب، مثل قولك: أكلت، شربت، دخلت، خرجت، ونحو ذلك مِن الكلام وهو صادق، ويثبت ما كان فيه الثواب وعليه العقاب."}, "39096": {"num": 39096, "aya": 29, "qail": "أبي هريرة", "tabaqa": "صحابي", "bab": "", "text": "عن أبي هريرة -من طريق شَهْر بن حَوْشَب- قال: {طُوبى}: شجرةٌ في الجنة، يقولُ الله لها: تَفَتَّقِي لعبدي عمّا شاء. فتَتَفَتَّق له عن الخيل بسُرُوجِها ولُجُمِها، وعن الإبل برحالها وأزِمَّتِها، وعما شاء مِن الكسوةِ."}, "39097": {"num": 39097, "aya": 29, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق العوفي- في قوله: {الذين آمنوا وعملوا الصالحات طوبى لهم وحسن مآب}، قال: لَمّا خلق الله الجنَّة وفَرَغ منها قال: {الذين آمنوا وعملوا الصّالحات طُوبى لهُم وحُسنُ مآبٍ}. وذلك حينَ أعْجَبَتْهُ."}, "39098": {"num": 39098, "aya": 29, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق علي بن أبي طلحة- في قوله: {طُوبى لهُم}، قال: فَرَحٌ، وقُرَّةُ عينٍ."}, "39099": {"num": 39099, "aya": 29, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق سعيد بن جبير- قال: طوبى: اسمُ الجنة، بالحَبَشِيَّة."}, "39100": {"num": 39100, "aya": 29, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق موسى بن سالم- قال: طوبى: اسم شجرة في الجنةِ."}, "38590": {"num": 38590, "aya": 4, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ليث- في قوله: {وفي الأرض قطع متجاورات}، قال: سِباخ، وجَدْوَل."}, "38591": {"num": 38591, "aya": 4, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ليث- في قوله: {وفي الأرض قطعٌ متجاوراتٌ}، قال: السَّبخة، والعَذِيَة، والمالحُ، والطيِّبُ."}, "38592": {"num": 38592, "aya": 4, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- في قوله: {وفي الأرض قطع متجاورات}، قال: طيِّبُها، وعَذِيُها، وخبيثُها السِّباخُ."}, "38593": {"num": 38593, "aya": 4, "qail": "الضحاك بن مزاحم", "tabaqa": "تابعي", "bab": "", "text": "عن الضحاك بن مزاحم -من طريق عبيد بن سليمان- في قوله: {وفي الأرض قطع متجاورات}، قال: يعني: الأرض السبخة، والأرض العذية، متجاورات بعضها عند بعض."}, "39105": {"num": 39105, "aya": 29, "qail": "إبراهيم النخعي", "tabaqa": "تابعي", "bab": "", "text": "عن إبراهيم النخعي -من طريق منصور- في قوله: {طُوبى لهُم}، قال: الخيرُ والكرامةُ الذي أعطاهم الله."}, "39107": {"num": 39107, "aya": 29, "qail": "الضحاك بن مزاحم", "tabaqa": "تابعي", "bab": "", "text": "عن الضحاك بن مُزاحِم -من طريق جُوَيْبِر- في قوله: {طوبى لهم}، قال: غِبطَةٌ لهم."}, "39106": {"num": 39106, "aya": 29, "qail": "إبراهيم النخعي", "tabaqa": "تابعي", "bab": "", "text": "عن إبراهيم النخعي -من طريق منصور- في قوله: {طوبى لهم}، قال: الجنَّة."}, "39108": {"num": 39108, "aya": 29, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي جَرَّةَ- قال: طوبى: شجرةٌ في الجنة، حمْلُها أمثال ثُدِيِّ النساء، فيه حُلَلُ أهل الجنة."}, "39109": {"num": 39109, "aya": 29, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- في قوله: {طُوبى لهُم}، قال: الجنةُ."}, "38599": {"num": 38599, "aya": 4, "qail": "عبد الله بن شوذب", "tabaqa": "تابع التابعين", "bab": "", "text": "عن [عبد الله] بن شوذب -من طريق ضمرة بن ربيعة- في قوله: {وفي الأرض قطع متجاورات}، قال: عذية، ومالحة."}, "38600": {"num": 38600, "aya": 4, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- في قوله: {وجناتٌ من أعنابٍ}، قال: جناتٌ وما معها."}, "39110": {"num": 39110, "aya": 29, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق منصور- في قوله: {طوبى لهم وحسن مآب}، قال: الخير."}, "39115": {"num": 39115, "aya": 29, "qail": "شهر بن حوشب", "tabaqa": "تابعي", "bab": "", "text": "عن شَهْر بن حَوْشَب -من طريق جعفر- قال: طوبى شجرةٌ في الجنة، كلُّ شجرةٍ في الجنة منها، أغصانُها مِن وراء سور الجنة."}, "38605": {"num": 38605, "aya": 4, "qail": "الضحاك بن مزاحم", "tabaqa": "تابعي", "bab": "", "text": "عن الضَّحّاك بن مُزاحِم -من طريق سلمة بن نبيط- {صنوان وغير صنوان}، قال: الصنوان: المجتمع، أصله واحد. {وغير صنوان}: المُتَفَرِّق أصلُه."}, "38606": {"num": 38606, "aya": 4, "qail": "الضحاك بن مزاحم", "tabaqa": "تابعي", "bab": "", "text": "عن الضحاك بن مزاحم -من طريق جُوَيْبِر- {صنوان} قال: يقول: إذا كان الخمسُ والسِّتُّ أصلُهُنَّ واحد، وفروعهن شتّى، وطلعهن مختلف، {وغير صنوان}: النخلة غير المنفردة."}, "39119": {"num": 39119, "aya": 29, "qail": "مغيث بن سمي", "tabaqa": "", "bab": "", "text": "عن مُغِيث بن سُمَيّ -من طريق حسان بن أبي الأشرس- قال: طوبى: شجرةٌ في الجنة، لو أنّ رجلًا رَكِب قَلُوصًا جذعًا أو جذعًة، ثم دار بها، لم يبلغ المكان الذي ارتحل منه حتى يموت هَرِمًا، وما مِن أهل الجنة منزلٌ إلا غُصنٌ مِن تلك الشجرة مُتَدَلٍّ عليهم، فإذا أرادوا أن يأكلوا مِن الثمرة تَدَلّى إليهم، فيأكلون ما شاءوا، ويجيء الطيرُ فيأكلون منه قدِيدًا وشويًّا ما شاءوا، ثم يطيرُ."}, "39120": {"num": 39120, "aya": 29, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- في قوله: {طُوبى لهُم}، قال: حُسنى لهم، وهي كلمةٌ مِن كلام العرب."}, "38609": {"num": 38609, "aya": 4, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- في قوله: {صنوانٌ} قال: النخلتان وأكثرُ في أصلٍ واحدٍ، {وغيرُ صنوانٍ} وحدَها."}, "38610": {"num": 38610, "aya": 4, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق القاسم بن أبي بزَّة- {صنوانٌ}، قال: ثلاثُ نخلاتٍ في أصلٍ واحدٍ، كمثلِ ثلاثةٍ مِن بني أبٍ وأمٍّ يتفاضلون في العمل، كما يتفاضل ثمرُ هذه النخلات الثلاث في أصلٍ واحدٍ."}, "39121": {"num": 39121, "aya": 29, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق مَعْمَر- في قوله: {طُوبى لهُم}، قال: هذه كلمةٌ عربيةٌ، يقول الرجلُ: طوبى لك. أي: أصبتَ خيرًا."}, "39124": {"num": 39124, "aya": 29, "qail": "شمر بن عطية", "tabaqa": "", "bab": "", "text": "عن شِمْر بن عطية -من طريق العلاء- في قوله: {طُوبى لهُم}، قال: هي شجرةٌ في الجنة يُقال لها: طُوبى."}, "39126": {"num": 39126, "aya": 29, "qail": "سعيد بن مسجوح", "tabaqa": "", "bab": "", "text": "عن سعيد بن مسْجوحٍ -من طريق جعفر بن أبي المغيرة- قال: طوبى: اسمُ الجنة، بالهندية."}, "39127": {"num": 39127, "aya": 29, "qail": "حماد", "tabaqa": "تابعي", "bab": "", "text": "عن حماد -من طريق علي بن جرير- قال: شجرة في الجنة، في دار كُلِّ مؤمن غُصْنٌ منها."}, "38617": {"num": 38617, "aya": 4, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "قراءات الآية، وتفسيرها", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- في قوله: «تُسْقى بِمَآءٍ واحِدٍ»، قال: ماء السماء، كمثل صالح بني آدم وخبيثهم، أبوهم واحدٌ، وكذلك النخلةُ، أصلها واحدٌ وطعامُها مختلِفٌ، وهو يشربُ بماءٍ واحدٍ."}, "38618": {"num": 38618, "aya": 4, "qail": "الضحاك بن مزاحم", "tabaqa": "تابعي", "bab": "قراءات الآية، وتفسيرها", "text": "عن الضَّحّاك بن مُزاحِم -من طريق أبي إسحاق الكوفي- «تُسْقى بِمَآءٍ واحِدٍ»، قال: ماء المطر."}, "39130": {"num": 39130, "aya": 29, "qail": "الضحاك بن مزاحم", "tabaqa": "تابعي", "bab": "", "text": "عن الضَّحّاك بن مُزاحِم -من طريق جُوَيْبِر- {وحُسنُ مآب}، قال: حُسنُ مُنقَلَب."}, "38620": {"num": 38620, "aya": 4, "qail": "عبد الله بن شوذب", "tabaqa": "تابع التابعين", "bab": "قراءات الآية، وتفسيرها", "text": "عن [عبد الله] بن شَوْذَب -من طريق ضَمْرَة بن ربيعة- «تُسْقى بِمَآءٍ واحِدٍ»، قال: بماء السماء."}, "39129": {"num": 39129, "aya": 29, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق قيس- قال: {وحسن مآب}، قال: حسن مَرْجِع."}, "38627": {"num": 38627, "aya": 4, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن مجاهد بن جبر، {ونفضل بعضها على بعض في الأكل}، قال: هذا حلوٌ، وهذا مرٌّ، وهذا حامضٌ، كذلك بنو آدم؛ أبوهم واحدٌ، ومنهم المؤمن والكافر."}, "38629": {"num": 38629, "aya": 4, "qail": "الضحاك بن مزاحم", "tabaqa": "تابعي", "bab": "", "text": "عن الضحاك بن مُزاحِم -من طريق علي بن الحكم- {صنوان وغير صنوان}، فيقول: تسقى بماء واحد، بعضُها أفضلُ مِن بعض حملًا، ففي ذلك آية لقوم يعقلون."}, "39142": {"num": 39142, "aya": 31, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "نزول الآية", "text": "عن عبد الله بن عباس -من طريق ابن جُرَيْج- قال: قالوا: سُيِّر بالقرآنِ الجبال، قُطِّع بالقرآن الأرض، أُخْرِج به موتانا."}, "39143": {"num": 39143, "aya": 31, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "نزول الآية", "text": "عن عبد الله بن عباس - من طريق قابوس بن أبي ظَبْيان، عن أبيه- قال: قالوا للنبيِّ صلى الله عليه وسلم: إن كان كما تقول فأرِنا أشياخَنا الأُوَلَ مِن الموتى نُكَلِّمهم، وأفْسِحْ لنا هذه الجبال جبالَ مكة التي قد ضَمَّتْنا. فنزلت: {ولو أنّ قُرآنًا سيرتْ به الجبالُ أوْ قطعتْ به الأرضُ أو كلمَ به الموتى}."}, "39144": {"num": 39144, "aya": 31, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "نزول الآية", "text": "عن عبد الله بن عباس -من طريق العوفيّ- قال: قال المشركون مِن قريش لرسول الله صلى الله عليه وسلم: لو وسَّعْتَ لنا أودية مكة، وسيَّرتَ جبالها فاحْتَرَثْناها، وأَحْيَيْتَ مَن مات مِنّا، وقطِّعْ به الأرض، أو كَلِّم به الموتى. فأنزل الله: {ولو أنّ قرآنًا} الآية."}, "39146": {"num": 39146, "aya": 31, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "نزول الآية", "text": "عن مجاهد بن جبر -من طريق ابن أبي نَجِيح- في قوله: {ولو أنّ قرآنا سيرت به الجبال} الآية، قال: قولُ كفار قريش لمحمد صلى الله عليه وسلم: سيِّر جبالَنا تتسع لنا أرضُنا؛ فإنها ضَيِّقةٌ، أو قرِّب لنا الشامَ؛ فإنّا نتَّجرُ إليها، أو أخرج لنا آباءنا مِن القبور نكلِّمهم. فقال الله تعالى: {ولَوْ أنَّ قُرْآنًا سُيِّرَتْ بِهِ الجِبالُ أوْ قُطِّعَتْ بِهِ الأَرْضُ أوْ كُلِّمَ بِهِ المَوْتى}."}, "39149": {"num": 39149, "aya": 31, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "نزول الآية", "text": "عن قتادة بن دعامة: أنّ هذه الآية: {ولو أنّ قرآنًا سيرتْ به الجبالُ أو قطعتْ به الأرضُ أو كُلمَ به الموتى} مكيَّةٌ."}, "39150": {"num": 39150, "aya": 31, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "نزول الآية", "text": "عن قتادة بن دعامة -من طريق سعيد- قوله: {ولو أن قرآنا سيرت به الجبال أو قطعت به الأرض أو كلم به الموتى}: ذُكِر لنا: أنّ قريشًا قالوا: إن سرَّك -يا محمد- اتِّباعُك -أو: أن نَتَّبِعَك- فسَيِّر لنا جبال تهامة، أو زِد لنا في حَرَمِنا حتى نتخذ قطائعَ نَخْتَرِف فيها، أو أحْيِ لنا فلانًا وفلانًا ناسًا ماتوا في الجاهلية. فأنزل الله تعالى: {ولو أن قرآنا سيرت به الجبال أو قطعت به الأرض أو كلم به الموتى} …."}, "39156": {"num": 39156, "aya": 31, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "نزول الآية", "text": "عن عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- في قوله: {ولو أن قرآنا سيرت به الجبال} الآية، قال: قالوا للنبي صلى الله عليه وسلم: إن كنتَ صادِقًا فسَيِّر عنا هذه الجبال، واجعلها حروثًا كهيئة أرض الشام ومصر والبلدان، أو ابعث موتانا فأخبِرْهم، فإنّهم قد ماتوا على الذي نحن عليه. فقال الله: {ولو أن قرآنا سيرت به الجبال أو قطعت به الأرض أو كلم به الموتى}."}, "39159": {"num": 39159, "aya": 31, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- قوله: {ولو أن قرآنا سيرت به الجبال أو قطعت به الأرض أو كلم به الموتى} … يقول: لو فُعِل هذا بقرآنٍ قبل قرآنكم لَفُعِل بقرآنكم."}, "39160": {"num": 39160, "aya": 31, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق مَعْمَر- … في قوله: {ولو أن قرآنا سيرت به الجبال أو قطعت به الأرض أو كلم به الموتى بل لله الأمر جميعا}، يقول: لو كان فُعِل ذلك بشيء مِن الكُتُب فيما مضى كان ذلك."}, "39162": {"num": 39162, "aya": 31, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "", "text": "عن عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- في قوله: {ولو أن قرآنا سيرت به الجبال أو قطعت به الأرض أو كلم به الموتى}، قال: لم يُصْنَع ذلك بقرآن قط، ولا كتاب، فيُصْنَع ذلك بهذا القرآن."}, "39163": {"num": 39163, "aya": 31, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس، في قوله: {بل لله الأمرُ جميعًا}: لا يصنعُ مِن ذلك إلا ما يشاءُ، ولم يكن لِيَفْعلَ."}, "39166": {"num": 39166, "aya": 31, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "قراءات", "text": "عن عبد الله بن عباس -من طريق عكرمة- أنّه كان يقرأُ: (أفَلَمْ يَتَبَيَّنِ الَّذِينَ آمَنُواْ)."}, "39167": {"num": 39167, "aya": 31, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "قراءات", "text": "عن عبد الله بن عباس -من طريق عكرمة- أنّه قرأ: (أفَلَمْ يَتَبَيَّنِ الَّذِينَ آمَنُواْ)، فقيل له: إنّها في المصحف: {أفَلَمْ يَيْأَسِ}. فقال: أظنُّ الكاتب كتبها وهو ناعِسٌ."}, "39168": {"num": 39168, "aya": 31, "qail": "ابن جريج", "tabaqa": "تابع التابعين", "bab": "قراءات", "text": "قال ابن جُرَيْج: في القراءة الأولى زعم ابنُ كثير وغيرُه: (أفَلَمْ يَتَبَيَّن)."}, "39169": {"num": 39169, "aya": 31, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس -من طريق علي بن أبي طلحة- {أفلمْ ييأس}، يقول: يعلم."}, "39170": {"num": 39170, "aya": 31, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس: أنّ نافع بن الأزرق سأله عن قوله: {أفلمْ ييأس الذين آمنُوا}. قال: أفلمْ يعلم، بلغة بني مالكٍ. قال: وهل تعرفُ العربُ ذلك؟ قال: نعم، أما سمعت مالك بن عوف يقولُ: لقد يئسَ الأقوامُ أنِّي أنا ابنُه … وإن كنتُ عن أرضِ العشيرةِ نائِيا."}, "38659": {"num": 38659, "aya": 7, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- في قوله: {ويقول الذين كفروا لولا أنزل عليه آية من ربه}، قال: هذا قولُ مشركي العرب."}, "39172": {"num": 39172, "aya": 31, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن مجاهد بن جبر -من طريق ليث- في قوله: {أفلم ييأس الذين آمنوا}، قال: أفلم يَتَبَيَّن."}, "38661": {"num": 38661, "aya": 7, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس، قال: لَمّا نزلت: {إنّما أنت منذرٌ ولكل قومٍ هادٍ} وضَعَ رسولُ الله صلى الله عليه وسلم يدَه على صدره، فقال: «أنا المنذرُ، ولكل قوم هاد». وأومأ بيده إلى منكب عليٍّ، فقال: «أنت الهادي، يا عليُّ، بك يهتدي المهتدون مِن بعدي»."}, "39175": {"num": 39175, "aya": 31, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن قتادة بن دعامة، {أفلمْ ييأسِ الذينَ آمنُوا}، قال: ألم يَعْرِف الذين آمنوا."}, "38664": {"num": 38664, "aya": 7, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس، في الآية، قال رسول الله صلى الله عليه وسلم: «المنذِرُ أنا، والهادي عليُّ بنُ أبي طالب»."}, "39176": {"num": 39176, "aya": 31, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن قتادة بن دعامة -من طريق سعيد- في قوله: {أفلم ييأس الذين آمنوا}، قال: ألم يتبين الذين آمنوا."}, "39177": {"num": 39177, "aya": 31, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن قتادة بن دعامة -من طريق مَعْمَر- {أفلم ييأس الذين آمنوا}، قال: ألم يعلم الذين آمنوا."}, "38667": {"num": 38667, "aya": 7, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق علي بن أبي طلحة- {ولكل قوم هادٍ}، قال: داعٍ."}, "38668": {"num": 38668, "aya": 7, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق العوفي- في قوله: {إنما أنت منذرٌ ولكل قومٍ هادٍ}، يقول: أنت -يا محمد- منذرٌ، وأنا هادي كلِّ قومٍ."}, "38669": {"num": 38669, "aya": 7, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق عكرمة- {إنما أنت منذر ولكل قوم هاد}، قال: هو المنذر، وهو الهاد. يعني: النبي صلى الله عليه وسلم."}, "38670": {"num": 38670, "aya": 7, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس، في الآية، قال: إنما أنت منذرٌ وهادٍ لكلِّ قومٍ. وفي لفظٍ: رسولُ الله هو المنذِرُ، وهو الهادي."}, "38671": {"num": 38671, "aya": 7, "qail": "أبي العالية الرياحي", "tabaqa": "تابعي", "bab": "", "text": "عن أبي العالية الرِّياحِيِّ -من طريق الربيع- {إنما أنت منذر ولكل قوم هاد}، قال: الهادي: القائد، والقائد الإمام، والإمام العمل."}, "38672": {"num": 38672, "aya": 7, "qail": "سعيد بن جبير", "tabaqa": "تابعي", "bab": "", "text": "عن سعيد بن جبير -من طريق عطاء بن السائب- في قوله: {إنما أنت منذر ولكل قوم هادٍ}، قال: محمدٌ المنذِرُ، والهادي الله عز وجل."}, "38673": {"num": 38673, "aya": 7, "qail": "أبي الضحى مسلم بن صبيح", "tabaqa": "تابعي", "bab": "", "text": "عن أبي الضُّحى مسلم بن صبيح -من طريق منصور- ="}, "39184": {"num": 39184, "aya": 31, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس، في قوله: {تُصيبهُمُ بما صنعُوا قارعةٌ}، قال: السَّرايا."}, "38675": {"num": 38675, "aya": 7, "qail": "أبي الضحى مسلم بن صبيح", "tabaqa": "تابعي", "bab": "", "text": "عن أبي الضُّحى مسلم بن صبيح ="}, "39185": {"num": 39185, "aya": 31, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس -من طريق سعيد بن جبير- في قوله: {ولا يزالُ الذين كفروا تُصيبهم بما صنعوا قارعة}، قال: سَرِيَّةٌ."}, "38677": {"num": 38677, "aya": 7, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ليث- في قوله: {إنّما أنت منذرٌ ولكل قومٍ هادٍ} قال: المنذر: محمد صلى الله عليه وسلم، {ولكل قوم هادٍ}: نبيٌّ يدعوهم إلى الله."}, "38678": {"num": 38678, "aya": 7, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق قيس- في قوله: {إنما أنت منذرٌ ولكل قومٍ هادٍ}، قال: المنذِرُ النبيُ صلى الله عليه وسلم، والله عز وجل هادي كلِّ قومٍ."}, "39186": {"num": 39186, "aya": 31, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس -من طريق عكرمة- في قوله: {تُصيبهم بما صنعوا قارعةٌ}، قال: نَكْبَةٌ."}, "38680": {"num": 38680, "aya": 7, "qail": "يحيى بن رافع", "tabaqa": "", "bab": "", "text": "عن يحيى بن رافع -من طريق إسماعيل- في قوله: {إنما أنت منذر ولكل قوم هاد}، قال: قائِد."}, "38681": {"num": 38681, "aya": 7, "qail": "أبي صالح باذام", "tabaqa": "تابعي", "bab": "", "text": "عن أبي صالح باذام -من طريق جابر بن نوح، عن إسماعيل بن أبي خالد- {إنما أنت منذر ولكل قوم هاد}، قال: إنما أنت -يا محمد- منذر، ولكل قوم قادة."}, "38682": {"num": 38682, "aya": 7, "qail": "أبي صالح باذام", "tabaqa": "تابعي", "bab": "", "text": "عن أبي صالح باذام -من طريق سفيان، عن إسماعيل بن أبي خالد- في قوله: {إنما أنت منذر} يا محمد، {ولكل قوم هاد} داعٍ إلى هُدًى أو ضلالة."}, "38683": {"num": 38683, "aya": 7, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- قال الله: {إنّما أنت منذرٌ ولكل قوم هادٍ}: لكل قومٍ داعٍ يدعوهم إلى الله."}, "39187": {"num": 39187, "aya": 31, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس -من طريق العوفيّ- في قوله: {تصيبهم بما صنعُوا قارعةٌ}، قال: عذابٌ مِن السماء."}, "39188": {"num": 39188, "aya": 31, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن مجاهد بن جبر -من طريق ليث- قال: القارِعةُ: السَّرايا."}, "39189": {"num": 39189, "aya": 31, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن مجاهد بن جبر -من طريق محمد بن طلحة، عن أبيه- في قوله تعالى: {بما صنعوا قارعة}، قال: ألْوِيَة."}, "39195": {"num": 39195, "aya": 31, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق سعيد بن جبير- في قوله: {أو تحلُّ قريبًا من دارهم}، قال: أنت، يا محمدُ."}, "38688": {"num": 38688, "aya": 7, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "", "text": "عن عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- قال في قوله: {ولكل قوم هاد}، قال: لكل قوم نبي، الهادي: النبي صلى الله عليه وسلم، والمنذر أيضًا: النبي صلى الله عليه وسلم. وقرأ: {وإن من أمة إلا خلا فيها نذير} [فاطر: 24]، وقال: {نذير من النذر الأولى} [النجم: 56]، قال: نبي مِن الأنبياء."}, "39196": {"num": 39196, "aya": 31, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق العوفي- في قوله: {أو تحل قريبًا من دارهم}، يعني: نزول رسول الله صلى الله عليه وسلم بهم، وقتاله إيّاهم."}, "39197": {"num": 39197, "aya": 31, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ليث- في قوله: {أو تحل قريبا من دراهم}، قال: أنت، يا محمد."}, "39198": {"num": 39198, "aya": 31, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- في قوله: {أو تحل قريبا من دارهم}، قال: أنت تحل قريبًا مِن دارهم."}, "39199": {"num": 39199, "aya": 31, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق منصور- قوله: {أو تحلُّ قريبا من دارهم}، قال: الحُدَيْبِيةُ."}, "39205": {"num": 39205, "aya": 31, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق سعيد بن جبير- في قوله: {حتى يأتيَ وعد اللهِ}، قال: فَتْحُ مكَّة."}, "39206": {"num": 39206, "aya": 31, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ليث- في قوله: {حتى يأتي وعد الله}، قال: فَتْح مكة."}, "39203": {"num": 39203, "aya": 31, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- قوله: {أو تحل قريبا من دارهم} أنت، يا محمد."}, "39208": {"num": 39208, "aya": 31, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- قوله: {حتى يأتي وعد الله}: ووعد الله فتحُ مكة."}, "39201": {"num": 39201, "aya": 31, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "", "text": "عن الحسن البصري -من طريق قتادة- في قوله: {أو تحلُ قريبًا من دارهم}، قال: أو تحلُّ القارعةُ قريبًا مِن دارهم."}, "39207": {"num": 39207, "aya": 31, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "", "text": "عن الحسن البصري -من طريق إسماعيل بن حكيم، عن رجل- في قوله: {حتى يأتيَ وعدُ الله}، قال: يومُ القيامة."}, "38747": {"num": 38747, "aya": 11, "qail": "قتادة", "tabaqa": "تابعي", "bab": "قراءات", "text": "عن قتادة، قال: في قراءة أُبَيِّ بن كعبٍ: (لَهُ مُعَقِّباتٌ مِّن بَيْنِ يَدَيْهِ ورَقِيبٌ مِّنْ خَلْفِهِ يَحْفَظُونَهُ مِن أمْرِ اللَّهِ)."}, "38748": {"num": 38748, "aya": 11, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "قراءات", "text": "عن عبد الله بن عباس -من طريق عمرو بن دينار- أنّه كان يقرأ: (لَهُ مُعَقِّباتٌ مِّن بَيْنِ يَدَيْهِ ورُقَبَآءُ مِن خَلْفِهِ مِن أمْرِ اللهِ يَحْفَظُونَهُ)."}, "38750": {"num": 38750, "aya": 11, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "قراءات", "text": "عن قتادة بن دعامة -من طريق سعيد- وفي بعض القراءة: (يَحْفَظُونَهُ بِأَمْرِ اللهِ)."}, "38751": {"num": 38751, "aya": 11, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "نزول الآية", "text": "عن عبد الله بن عباس -من طريق عطاءِ بن يسارِ-: أنّ أرْبَدَ بن قيس، وعامر بن الطُّفيل، قدِما المدينةَ على رسول الله صلى الله عليه وسلم، فانتهيا إليه وهو جالسٌ، فجلسا بين يديه، فقال عامرٌ: ما تجعلُ لي إن أسلمتُ؟ قال النبيُّ صلى الله عليه وسلم: «لك ما للمسلمين، وعليك ما عليهم». قال: أتجعلُ لي -إن أسلمتُ- الأمرَ من بعدك؟ قال: «ليس لك، ولا لقومك، ولكن لك أعِنَّةَ الخيل». قال: فاجعل لي الوَبَرَ، ولك المدَرُ فقال النبيُّ صلى الله عليه وسلم: «لا». فلما قَفّى مِن عنده قال: لَأَمْلَأَنَّها عليكَ خيلًا ورجالًا. قال النبيُّ صلى الله عليه وسلم: «يمنعُك الله». فلما خرج أرْبَدُ وعامرٌ قال عامرٌ: يا أرْبَدُ، إنِّي سأُلْهِي محمدًا عنك بالحديث، فاضربه بالسيف؛ فإنّ الناس إذا قتلتَ محمدًا لم يزيدوا على أن يَرْضَوا بالدِّيَة، ويكرهوا الحرب، فسَنُعْطِيهم الدِّيَة. فقال أرْبَدُ: أفعل. فأقبلا راجِعَيْن، فقال عامرٌ: يا محمدُ، قُم معي أكلمك. فقام معه، فخليا إلى الجدار، ووقف معه عامرٌ يكلِّمه، وسلَّ أرْبَدُ السيف، فلمّا وضع يده على سيفه يَبِستْ على قائم السيف، فلم يستطع سلَّ سيفه، وأبطأ أرْبَدُ على عامر بالضرب، فالتفت رسول الله صلى الله عليه وسلم، فرأى أرْبَدَ وما يصنع، فانصرف عنهما، وقال عامرٌ لأَرْبَدَ: ما لَكَ حُشِمْتَ؟. قال: وضعتُ يدي على قائم السيف، فيَبِسَتْ. فلما خرج عامرٌ وأَرْبَدُ مِن عند رسول الله صلى الله عليه وسلم، حتى إذا كانا بحرَّة -حرَّةِ واقمٍ- نزلا، فخرج إليهما سعدُ بن معاذ وأسيد بن حضير، فقال: اشخصا، يا عدُوَّي الله، لعنكما الله. وقع بهما، فقال عامرٌ: مَن هذا، يا سعدُ؟ فقال سعدٌ: هذا أُسيدُ بن حُضَيْر الكَتائِبِ. قال: أما -والله- إن كان حُضيرٌ صديقًا لي. حتى إذا كانا بالرَّقَمِ أرسل الله على أرْبَد صاعقةً، فقتلته، وخرج عامرٌ حتى إذا كان بالجَرِيب أرسل الله عليه قَرْحةً، فأدركه الموت؛ فأنزل الله: {الله يعلمُ ما تحملُ كل أنثى} إلى قوله: {له معقباتٌ من بين يديه ومنْ خلفه}. قال: المعقِّبات مِن أمر الله يحفظون محمدًا صلى الله عليه وسلم. ثم ذكر أرْبَد وما قتله، فقال: {هو الذي يريكُمُ البرقَ} إلى قوله: {وهو شديدُ المحالِ}."}, "38752": {"num": 38752, "aya": 11, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "نزول الآية", "text": "عن عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب-، نحوه."}, "39265": {"num": 39265, "aya": 38, "qail": "الضحاك بن مزاحم", "tabaqa": "تابعي", "bab": "", "text": "عن الضَّحّاك بن مُزاحِم -من طريق جُوَيْبِر- في قوله: {لكلّ أجلٍ كتابٌ}، يقولُ: لكلِّ كتابٍ ينزل من السماء أجلٌ، فيمحو الله مِن ذلك ما يشاءُ، ويُثْبِت، وعنده أمُّ الكتاب."}, "38754": {"num": 38754, "aya": 11, "qail": "كنانة العدوي", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن كنانة العَدَوِيِّ، قال: دخل عثمانُ بنُ عفانَ على رسول الله صلى الله عليه وسلم، فقال: يا رسول الله، أخبِرْني عن العبد، كم معه مِن مَلَك؟ فقال: «ملَكٌ عن يمينك على حسناتك، وهو أميرٌ على الذي على الشمال، إذا عملتَ حسنة كُتِبَتْ عشرًا، فإذا عملت سيئةً قال الذي على الشمال للذي على اليمين: أكتُبُ؟ قال: لا، لعلَّه يستغفر اللهَ ويتوبُ. فإذا قال ثلاثًا، قال: نعم، اكتبه، أراحنا الله منه فبئس القرينُ، ما أقل مراقبته لله، وأقل استحياؤه منه. يقول الله: {وما يلفظُ من قول إلا لديه رقيب عتيدٌ} [ق: 18]، وملَكان مِن بين يديك ومِن خلفك، يقول الله: {له معقباتٌ من بين يديه ومن خلفه يحفظونه من أمر الله}. وملك قابِض على ناصيتك، فإذا تواضعتَ لله رفعك، وإذا تجَبَّرْتَ على الله قَصَمك، وملكان على شفتيك ليس يحفظان عليك إلا الصلاة على النبيِّ صلى الله عليه وسلم، ومَلَك قائمٌ على فِيك لا يدع أن تدخل الحية في فيك، وملكان على عينيك، فهؤلاء عشرةُ أملاك على كل بني آدمَ، ينزلون ملائكة الليل على ملائكة النهار؛ لأنّ ملائكة الليل سوى ملائكة النهار، فهؤلاء عشرون ملكًا على كل آدميٍّ، وإبليس بالنهار، وولده بالليل»."}, "38755": {"num": 38755, "aya": 11, "qail": "أبي أمامة", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن أبي أُمامة، قال: قال رسول الله صلى الله عليه وسلم: «وُكِّل بالمؤمن ستون وثلاثمائة ملَكٍ، يدفعون عنه ما لم يُقدَّر عليه مِن ذلك، للبصر سبعةُ أملاكٍ يَذبُّون عنه كما يُذَبُّ عن قَصْعَةِ العسل مِن الذباب في اليوم الصّائِف، وما لو بدا لكم لرأيتموه على كلِّ سَهْلٍ وجبل، كلُّهم باسطٌ يديه، فاغِرٌ فاه، وما لو وكل العبدُ فيه إلى نفسه طَرْفَة عين لاخْتَطَفَتْه الشياطينُ»."}, "38756": {"num": 38756, "aya": 11, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس -من طريق علي بن أبي طلحة- في قوله: {له معقبات}، قال: الملائكة."}, "38757": {"num": 38757, "aya": 11, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس -من طريق العوفي- في قوله: {له معقبات} الآية، يعني: ولِيُّ السلطان، يكون عليه الحُرّاس يحفظونه مِن بين يديه ومِن خلفه."}, "38758": {"num": 38758, "aya": 11, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس -من طريق سعيد بن جبير- في قوله: {له معقبات} الآية، قال: الملوك يَتَّخِذُون الحَرَس؛ يحفظونه مِن أمامه ومِن خلفه، وعن يمينه وعن شماله، يحفظونه مِن القتل، ألم تسمع أنّ الله تعالى يقول: {وإذا أراد الله بقومٍ سوءًا فلا مردَّ له}. أي: إذا أراد سوءًالم يُغْنِ الحرسُ عنه شيئًا."}, "38759": {"num": 38759, "aya": 11, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس -من طريق الضَّحّاك- في قوله: {له معقباتٌ}، قال: هم الملائكةُ، تُعَقِّبُ بالليل والنهار، وتكتُبُ على ابن آدمَ."}, "38760": {"num": 38760, "aya": 11, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس -من طريق الضَّحّاك- أنّه قال: {له معقبات}، يعني: لمحمد صلى الله عليه وسلم حُرّاس مِن الرحمن مِن بين يديه ومِن خلفه."}, "38761": {"num": 38761, "aya": 11, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس -من طريق عكرمة- في قوله: {له معقبات}، قال: ملائكةٌ يحفظونه مِن بين يديه ومِن خلفه، فإذا جاء قَدَرُه خَلَّوْا عنه."}, "38762": {"num": 38762, "aya": 11, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس -من طريق عمرو بن دينار-: {لَهُ مُعَقِّباتٌ مِّن بَيْنِ يَدَيْهِ} رُقَباء {مِن خَلْفِهِ} مِن أمْرِ اللهِ {يَحْفَظُونَهُ}."}, "38763": {"num": 38763, "aya": 11, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس -من طريق ابن جُرَيْج- قال: {له معقبات من بين يديه ومن خلفه}، قال: الملائكة. ="}, "38764": {"num": 38764, "aya": 11, "qail": "ابن جريج", "tabaqa": "تابع التابعين", "bab": "تفسير الآية", "text": "قال ابن جُرَيْج، {معقبات}، قال: الملائكة تعاقب الليل والنهار، وبلغنا: أنّ النبي صلى الله عليه وسلم قال: «يجتمعون فيكم عند صلاة العصر وصلاة الصبح». وقوله: {من بين يديه ومن خلفه يحفظونه} قال ابن جريج: مثل قوله: {عن اليمين وعن الشمال قعيد} [ق: 17]، قال: الحسنات مِن بين يديه، والسيئات من خلفه، الذي عن يمينه يكتب الحسنات، والذي عن شماله يكتب السيئات."}, "38765": {"num": 38765, "aya": 11, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس -من طريق عطاء بن يسار- {له معقباتٌ من بين يديه ومنْ خلفه}، قال: المُعَقِّبات مِن أمر الله، يحفظون محمدًا."}, "38766": {"num": 38766, "aya": 11, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس -من طريق أبي الجوزاء- في قوله: {له معقباتٌ من بين يديهِ ومن خلفهِ يحفظونهُ}، قال: هذه للنبيِّ صلى الله عليه وسلم خاصَّةً."}, "39270": {"num": 39270, "aya": 39, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "نزول الآية", "text": "عن مجاهد بن جبر -من طريق قيس-: أنّ رسول الله صلى الله عليه وسلم لَمّا أتاهم بـ: الله، والرحمن الرحيم، والمتشابه، والمحكم، والناسخ والمنسوخ؛ قالوا: ما نرى لك مِن الأمر من شيء. فأنزل الله: {يمحوا الله ما يشاء ويثبت وعنده أم الكتاب}."}, "38768": {"num": 38768, "aya": 11, "qail": "سعيد بن جبير", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن سعيد بن جبير -من طريق عطاء بن السائب- في قوله: {له معقبات}، قال: الملائكةُ."}, "38769": {"num": 38769, "aya": 11, "qail": "إبراهيم النخعي", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن إبراهيم النخعي -من طريق منصور- في هذه الآية، قال: الحَفَظَة."}, "38770": {"num": 38770, "aya": 11, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن مجاهد بن جبر -من طريق خُصَيْف- في قوله: {له معقبات} الآية، قال: الملائكة مِن أمر الله."}, "38771": {"num": 38771, "aya": 11, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن مجاهد بن جبر -من طريق ابن عبيد الله- في قوله: {له معقباتٌ}، قال: الحفظةُ هم مِن أمر الله."}, "38772": {"num": 38772, "aya": 11, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- في قوله: {له معقباتٌ}، قال: الملائكة تعاقبُ الليل والنهار. وبلغني: أنّ النبيَّ صلى الله عليه وسلم قال: «يجتمعون فيكم عند صلاة العصر، وصلاة الصبح»."}, "39284": {"num": 39284, "aya": 39, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق سعيد بن جبير- في قوله: {يمحُوا الله ما يشاءُ ويثبتُ}، قال: ينزِل اللهُ في كلِّ شهر رمضان إلى سماء الدنيا؛ يُدَبِّر أمرَ السنة إلى السنة في ليلة القدر، فيمحو ما يشاءُ ويثبتُ، إلا الشّقوة والسعادة، والحياة والممات."}, "39285": {"num": 39285, "aya": 39, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق العوفي- {يمحُوا الله ما يشاءُ}: هو الرجلُ يعملُ الزَّمانَ بطاعة الله، ثم يعود لمعصية الله، فيموتُ على ضلاله، فهو الذي يمحُو. والذي يثبتُ الرجلُ الذي يعمل بمعصية الله، وقد سبق له خيرٌ، حتى يموت وهو في طاعة الله."}, "39286": {"num": 39286, "aya": 39, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق عكرمة- {يمحُوا الله ما يشاءُ ويثبتُ}، قال: مِن أحد الكتابين، هما كتابان يمحو اللهُ ما يشاءُ مِن أحدهما ويُثبت، {وعنده أمُّ الكتابِ}."}, "39287": {"num": 39287, "aya": 39, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق عطاء- قال: إنّ لله لوحًا محفوظًا مسيرةَ خمسمائة عامٍ، من دُرَّة بيضاء، له دفَّتان مِن ياقوت، والدَّفَّتان لوحان، لله كلَّ يوم ثلاثٌ وستون لحظة، يمحو ما يشاءُ ويُثبتُ، وعنده أمُّ الكتاب."}, "39288": {"num": 39288, "aya": 39, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس، قال: لا ينفعُ الحذرُ مِن القَدَر، ولكنَّ اللهَ يمحو بالدعاء ما يشاءُ مِن القَدَر."}, "39289": {"num": 39289, "aya": 39, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق علي بن أبي طلحة- في قوله: {يمحُوا الله ما يشاءُ ويُثبتُ}، قال: يُبَدِّل اللهُ ما يشاءُ مِن القرآن فينسخه، ويُثبتُ ما يشاءُ فلا يُبَدِّله."}, "38779": {"num": 38779, "aya": 11, "qail": "أبي صالح باذام", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن أبي صالح باذام -من طريق إسماعيل بن أبي خالد- في قوله: {له معقبات}، قال: ملائكة الليل يَعْقُبون ملائكةَ النهار."}, "38780": {"num": 38780, "aya": 11, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن قتادة بن دعامة -من طريق مَعْمَر- قوله: {له معقبات من بين يديه}، قال: ملائكة يَتَعاقَبُونه."}, "39293": {"num": 39293, "aya": 39, "qail": "أبي وائل شقيق بن سلمة", "tabaqa": "تابعي", "bab": "", "text": "عن أبي وائل شقيق بن سلمة -من طريق الأعمش- قال: كان مِمّا يكثرُ أن يدعو بهؤلاء الدعوات: اللهمَّ، إن كنت كتبتنا أشقياءَ فامحُنا واكتُبنا سعداءَ، وإن كنتَ كتبتنا سعداءَ فأثْبِتْنا، فإنّك تمحُو ما تشاءُ وتثبتُ، وعندك أمُّ الكتاب."}, "39294": {"num": 39294, "aya": 39, "qail": "سعيد بن جبير", "tabaqa": "تابعي", "bab": "", "text": "عن سعيد بن جبيرٍ -من طريق عطاء- في قوله: {يمحُوا الله ما يشاءُ ويثبتُ}، قال: يُثبتُ في البطن الشقاءَ والسعادةَ، وكلَّ شيءٍ هو كائنٌ، فيقدِّم منه ما يشاءُ، ويُؤَخِّرُ ما يشاءُ."}, "39295": {"num": 39295, "aya": 39, "qail": "سعيد بن جبير", "tabaqa": "تابعي", "bab": "", "text": "عن سعيد بن جبير، قال: {يمحو الله ما يشاء} مِن ذنوب العباد فيغفرها، {ويثبت} ما يشاء فلا يغفرها."}, "38784": {"num": 38784, "aya": 11, "qail": "أبي مجلز لاحق بن حميد", "tabaqa": "تابعي", "bab": "", "text": "عن أبي مِجْلَز لاحق بن حميد، قال: جاء رجلٌ مِن مرادٍ إلى علي بن أبي طالب وهو يُصَلِّي، فقال: احتَرِس؛ فإنّ ناسًا مِن مُراد يريدون قتلك. فقال: إنّ مع كلِّ رجلٍ مَلَكَين يحفظانه مِمّا لم يُقدَّر، فإذا جاء القدرُ خَلَّيا بينه وبينه، وإنّ الأجل جُنَّةٌ حصينةٌ."}, "38785": {"num": 38785, "aya": 11, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق سعيد- في قوله: {يحفظونهُ من أمْر الله}، قال: عن أمر الله، يحفظونه مِن بين يديه ومن خلفه."}, "38786": {"num": 38786, "aya": 11, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس، في قوله: {يحفظونه من أمر الله}، قال: ذلك الحِفظُ مِن أمر الله بأمر الله."}, "38787": {"num": 38787, "aya": 11, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق علي بن أبي طلحة- في قوله: {يحفظونه من أمر الله}، قال: بإذن الله."}, "38788": {"num": 38788, "aya": 11, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق عكرمة- في قوله: {يحفظونه من أمر الله}، قال: يحفظونه حتى إذا جاء القَدَر خَلَّوْا عنه."}, "38789": {"num": 38789, "aya": 11, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق الضَّحّاك- {يحفظونه من أمر الله}، قال: مِن الموت."}, "38790": {"num": 38790, "aya": 11, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق الضَّحّاك- أنّه قال: {له معقبات} يعني: لمحمد صلى الله عليه وسلم حُرّاس مِن الرحمن مِن بين يديه ومِن خلفه {يحفظونه من أمر الله} يعني: مِن شَرِّ الجِنِّ، وطَوارِق الليل والنهار."}, "38791": {"num": 38791, "aya": 11, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق العوفي- في قوله: {له معقبات} الآية، يعني: وليُّ السلطان، يكون عليه الحُرّاس يحفظونه مِن بين يديه ومِن خلفه، يقول الله عز وجل: يحفظونه مِن أمري؟! فإنِّي إذا أردتُ بقوم سوءًا فلا مَرَدَّ له."}, "38792": {"num": 38792, "aya": 11, "qail": "أبي أمامة", "tabaqa": "صحابي", "bab": "", "text": "عن أبي أُمامة -من طريق أبي غالب- قال: ما مِن آدَمِيٍّ إلا ومعه مَلَكٌ يذودُ عنه، حتى يُسْلِمَه للذي قُدِّر له."}, "38793": {"num": 38793, "aya": 11, "qail": "كعب الأحبار", "tabaqa": "تابعي", "bab": "", "text": "عن كعب الأحبار -من طريق يزيد بن شريح- قال: لو تَجَلّى لابن آدم كُلُّ سَهل وحزن لَرَأى على كُلِّ شيءٍ مِن ذلك شياطين، لولا أنّ الله وكَّل بكم ملائكةٌ يَذُبُّون عنكم في مَطْعَمِكم ومشربكم وعوراتكم، إذن لَتُخُطِّفْتُم."}, "38794": {"num": 38794, "aya": 11, "qail": "سعيد بن جبير", "tabaqa": "تابعي", "bab": "", "text": "عن سعيد بن جبير -من طريق عطاء بن السائب- في قوله: {يحفظونه من أمر الله}، قال: حِفظُهم إيّاه مِن أمر الله."}, "38795": {"num": 38795, "aya": 11, "qail": "إبراهيم النخعي", "tabaqa": "تابعي", "bab": "", "text": "عن إبراهيم النخعي -من طريق طلحة- في قوله: {يحفظونه من أمر الله}، قال: مِن الجنِّ."}, "38796": {"num": 38796, "aya": 11, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر، في قوله: {من بين يديه}: مثلُ قوله: {عن اليمين وعن الشمال} [ق: 17]، الحسناتُ مِن بين يديه، والسيئاتُ مِن خلفه، الذي على يمينه يكتبُ الحسنات، والذي على يساره يكتبُ السيئات، والذي على يمينه يكتب بغير شهادة الذي على يساره، والذي على يساره لا يكتب إلا بشهادة الذي على يمينه، فإن مَشى كان أحدُهما أمامَه والآخرُ وراءَه، وإن قعد كان أحدُهما على يمينه والآخرُ على يساره، وإن رقد كان أحدُهما عند رأسه والآخرُ عند رجليه، {يحفظونه من أمر الله} قال: يحفظون عليه."}, "38797": {"num": 38797, "aya": 11, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ليث- قال: ما من عبد إلا له مَلَكٌ مُوكَلٌ بحفظه في نومه ويقظته مِن الجنِّ والإنس والهوام، فما منها شيءٌ يأتيه يُرِيده إلا قال: وراءَك. إلّا شيئًا يأذنُ اللهُ فيه فيُصِيبُه."}, "38798": {"num": 38798, "aya": 11, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- في قوله: {يحفظونه من أمر الله}، قال: بأمر الله."}, "39310": {"num": 39310, "aya": 39, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- في قوله: {يمحُوا الله ما يشاءُ ويُثبتُ}، قال: هي مِثلُ قوله: {ما ننسخْ من آيةٍ أو ننسها نأتِ بخيرٍ منها أوْ مثلها} [البقرة: 106]."}, "39305": {"num": 39305, "aya": 39, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "", "text": "عن الحسن البصري -من طريق عوف- في قوله: {يمحوا اللهُ ما يشاءُ} قال: مَن جاء أجلُه {ويُثبتُ} قال: مَن لم يجئْ أجله بعدُ فهو يجري إلى أجله."}, "38801": {"num": 38801, "aya": 11, "qail": "عبد الملك ابن جريج", "tabaqa": "تابع التابعين", "bab": "", "text": "عن عبد الملك ابن جُرَيْج -من طريق حجاج- في قوله: {من بين يديه ومن خلفه يحفظونه}، قال: مِثلُ قوله: {عن اليمين وعن الشمال قعيد} [ق: 17]. قال: الحسنات مِن بين يديه، والسيئات مِن خلفه، الذي عن يمينه يكتب الحسنات، والذي عن شماله يكتب السيئات."}, "38802": {"num": 38802, "aya": 11, "qail": "عبد الملك ابن جريج", "tabaqa": "تابع التابعين", "bab": "", "text": "عن عبد الملك ابن جُرَيْج -من طريق حجاج- {يحفظونه من أمر الله}، قال: يحفظون عليه مِن الله."}, "39306": {"num": 39306, "aya": 39, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "", "text": "عن الحسن البصري، في الآية، قال: {يمحُوا الله} رزقَ هذا الميِّت، {ويُثبّتَ} رزقَ هذا المخلوقِ الحيِّ."}, "38804": {"num": 38804, "aya": 11, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "", "text": "عن عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- قال: أتى عامرُ بن الطفيل وأَرْبَدُ بن ربيعة إلى رسول الله صلى الله عليه وسلم، فقال له عامرٌ: ما تجعل لي إن أنا اتَّبَعْتُك؟ قال: «أنت فارسٌ، أُعطِيك أعِنَّة الخيل». قال: قَطُّ؟ قال: «فما تبغي؟». قال: لي الشرق، ولكَ الغرب. قال: «لا». قال: ليَ الوَبرُ، ولكَ المَدَرُ. قال: «لا». قال: لَأَمْلَأنّها إذن عليك خيلًا ورجالًا. قال: «يمنعك اللهُ ذلك وابنا قَيْلَةَ». يريدُ: الأوس، والخزرج، فخرجا، فقال عامر لأَرْبَدَ: إن كان الرجلُ لنا لَمُمَكَّنًا، لو قتلناه ما انتَطَحَتْ فيه عَنزان، ولَرَضُوا بأن نَعْقِلَه لهم، وأَحَبُّوا السِّلْم، وكَرِهوا الحرب إذا رَأَوْا أمرًا قد وقع. فقال الآخرُ: إن شِئتَ. فتشاوَرا، وقال: ارْجِع، فأنا أشغَلُه عنك بالمجادلة، وكن وراءه، فاضْرِبْه بالسيف ضربةً واحدةً. فكانا كذلك؛ واحدٌ وراء النبيِّ صلى الله عليه وسلم، والآخرُ قال: اقْصُصْ علينا قصصك. قال: «ما تقولُ؟». قال: قرآنك. فجعل يُجادله ويَسْتَبْطِئُه، حتى قال له: ما لك حُشِمْتَ؟ قال: وضَعْتُ يدي على قائم السيف، فيَبِست، فما قدرتُ على أن أُحْلِيَ، ولا أُمِرَّ، ولا أحرِّكَها. فخرجا، فلمّا كانا بالحرَّة سمع بذلك سعدُ بنُ معاذٍ وأُسَيْدُ بن حُضَيرٍ، فخرجا إليه على كلِّ واحد منهما لَأْمَتُه، ورُمْحُه بيده، وهو مُتَقَلِّدٌ سيفَه، فقالا لعامر بن الطفيل: يا أعور الخبيث، أنت الذي تشترط على رسول الله صلى الله عليه وسلم؟! لولا أنّك في أمانٍ مِن رسول الله صلى الله عليه وسلم ما رِمْتَ المنزل حتى نضرب عنقك. فقال: مَن هذا؟ قالوا: أُسَيْدُ بن حُضَيرٍ. قال: لو كان أبوه حيًّا لم يفعل بي هذا. ثم قال عامرٌ لأَرْبَدَ: اخرجْ أنت -يا أرْبَدُ- إلى ناحيةِ عَدَنَةَ، وأخرُجُ إلى نجدٍ، فنجمعُ الرجالَ، فنلتقي عليه. فخرج أرْبَدُ حتى إذا كان بالرَّقَمِ بعث الله سحابة من الصَّيْفِ فيها صاعقةٌ فأحرقتْه، وخرج عامرٌ حتى إذا كان بوادي الجَرِيب أرسل الله عليه الطاعونَ، فجعل يصيحُ: يا آل عامرٍ، أغُدَّةٌ كغُدَّة البعير تقتُلني، وموتٌ أيضًا في بيت سلولية؟! وهي امرأةٌ مِن قيسٍ، فذلك قوله: {سواءٌ منكم مَّن أسرَّ القولَ ومن جهرَ به} إلى قوله: {له معقباتٌ من بين يديه ومن خلفِهِ يحفظونهُ من أمرِ الله}. هذا مُقَدَّمٌ ومُؤَخرٌ؛ لِرَسول الله صلى الله عليه وسلم تلك المُعَقِّباتُ مِن أمر الله، وقال لهذين: {إن الله لا يغيرُ ما بقومٍ حتى يغيروا ما بأنفسهم} حتى بلغ: {وما دُعاءُ الكافرينَ إلا في ضلالٍ}. وقال لبيد في أخيه أرْبَدَ وهو يَبكيه: أخشى على أرْبَدَ الحُتُوفَ ولا … أرهبُ نَوْءَ السِّماكِ والأَسَد فجَّعني الرعدُ والصواعقُ بالـ … ـفارس يوم الكريهة النَّجِدِ."}, "38805": {"num": 38805, "aya": 11, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس، {إن الله لا يغير ما بقوم حتى يغيروا ما بأنفسهم}، قال: لا يُغيِّر ما بهم مِن النعمة حتى يعملوا بالمعاصي، فيرفع اللهُ عنهم النِّعَم."}, "38806": {"num": 38806, "aya": 11, "qail": "إبراهيم النخعي", "tabaqa": "تابعي", "bab": "", "text": "عن إبراهيم النَّخَعي -من طريق جهم- قال: أوحى اللهُ إلى نبيٍّ مِن أنبياء بني إسرائيل: أن قُل لقومك: إنّه ليس مِن أهل قريةٍ، ولا أهل بيت يكونون على طاعة الله فيتحوَّلون منها إلى معصية الله؛ إلّا تحوَّل اللهُ مِمّا يُحِبُّون إلى ما يكرهون. ثم قال: إنّ تصديق ذلك في كتاب الله: {إن الله لا يغيرُ ما بقومٍ حتى يُغيروا ما بأنفسهمْ}."}, "38807": {"num": 38807, "aya": 11, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد بن بشير- في قوله: {إن الله لا يُغيرُ ما بقومٍ حتىَّ يغيروا ما بأنفسهم}، قال: إنّما يجِيء التغييرُ مِن الناس، والتَّيسير مِن الله، فلا تُغَيِّروا ما بكم مِن نِعَم الله."}, "39320": {"num": 39320, "aya": 39, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق عكرمة- {وعنده أمُّ الكتابِ}، أي: جُمْلَةُ الكتابِ."}, "39321": {"num": 39321, "aya": 39, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق علي بن أبي طلحة- في قوله: {وعندهُ أمُّ الكتابِ}، يقولُ: وجملةُ ذلك عنده في أمِّ الكتابِ؛ الناسخُ والمنسوخُ، وما يُبَدَّل وما يُثْبَتُ، كل ذلك في كتابٍ."}, "39322": {"num": 39322, "aya": 39, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق حجاج - في قوله: {وعندهُ أمُّ الكتابِ}، قال: الذِّكرُ."}, "39317": {"num": 39317, "aya": 39, "qail": "عبد الملك ابن جريج", "tabaqa": "تابع التابعين", "bab": "", "text": "عن عبد الملك ابن جُرَيْج -من طريق حجّاج- {يمحُوا اللهُ ما يشاءُ}، قال: يَنسَخُ."}, "39324": {"num": 39324, "aya": 39, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر، {وعندهُ أمُّ الكتابِ}، قال: الذِّكْرُ."}, "39319": {"num": 39319, "aya": 39, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "", "text": "عن عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- في الآية، قال: {يمحُوا اللهُ ما يشاءُ} مما يُنَزِّل على الأنبياء، {ويُثبتُ} ما يشاءُ مِمّا يُنَزِّلُ على الأنبياء."}, "38814": {"num": 38814, "aya": 11, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق سعيد بن جبير- في قوله: {له معقبات} الآية، قال: الملوكُ يتَّخذون الحَرَس؛ يحفظونه مِن أمامه ومِن خلفه، وعن يمينه وعن شماله، يحفظونه مِن القتل، ألم تسمع أنّ الله تعالى يقول: {وإذا أراد الله بقومٍ سوءًا فلا مردَّ له}. أي: إذا أراد سوءًالم يُغْنِ الحَرَسُ عنه شيئًا."}, "39318": {"num": 39318, "aya": 39, "qail": "مقاتل بن سليمان", "tabaqa": "تابع التابعين", "bab": "", "text": "قال مقاتل بن سليمان، في قوله: {يمحوا الله ما يشاء} يقول: ينسخ الله ما يشاء مِن القرآن، {ويثبت} يقول: ويُقِرُّ مِن حُكْم الناسخِ ما يشاء فلا ينسخه."}, "39325": {"num": 39325, "aya": 39, "qail": "الضحاك بن مزاحم", "tabaqa": "تابعي", "bab": "", "text": "عن الضَّحّاك بن مُزاحِم -من طريق جُوَيْبِر- في الآية، قال: {وعندهُ أمُّ الكتابِ}، قال: جملةُ الكتابِ وعِلْمُه، يعني بذلك: ما ينسخُ منه وما يُثبتُ."}, "39329": {"num": 39329, "aya": 39, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- وقولُه: {وعندهُ أمُّ الكتابِ}، أي: جملةُ الكتاب وأصله."}, "39331": {"num": 39331, "aya": 39, "qail": "عبد الملك ابن جريج", "tabaqa": "تابع التابعين", "bab": "", "text": "عن عبد الملك ابن جُرَيْج -من طريق حجّاج- {وعندهُ أمُّ الكتابِ}، قال: الذِّكْرُ."}, "39333": {"num": 39333, "aya": 39, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "", "text": "عن عبد الرحمن بن زيد بن أسلم -من طريق ابن وهْب- في قوله: {وعندهُ أمُّ الكتابِ} لا يُغيَّرُ ولا يُبَدَّلُ."}, "39337": {"num": 39337, "aya": 41, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق عطاء- في قوله: {ننقُصُها منْ أطرافها}، قال: مَوْتُ علمائِها وفقهائِها، وذهابُ خيارِ أهلِها."}, "39338": {"num": 39338, "aya": 41, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق عكرمة- في قوله: {أو لم يروا أنا نأتي الأرض ننقصها من أطرافها}، قال: أولم يروا أنّا نفتح لمحمد الأرضَ بعد الأرض."}, "39339": {"num": 39339, "aya": 41, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق عكرمة- في قوله: {أو لم يَروا أنّا نأتي الأرضَ ننقصها من أطرافها}، قال: أولم يروا إلى القرية تخربُ حتى يكون العُمرانُ في ناحية منها؟."}, "39340": {"num": 39340, "aya": 41, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق العوفي- في قوله: {أولم يروا أنا نأتي الأرض ننقصها من أطرافها}، يعني بذلك: ما فَتَحَ اللهُ على محمد صلى الله عليه وسلم، فذلك نُقصانُها."}, "39341": {"num": 39341, "aya": 41, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق علي بن أبي طلحة- في قوله: {ننقصُهُا من أطرافها}، يقولُ: نُقصانُ أهلِها وبَرَكتِها."}, "39342": {"num": 39342, "aya": 41, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس، في الآية، قال: إنّما تنقصُ الأنفسُ والثمراتُ، وأمّا الأرضُ فلا تنقُصُ."}, "39344": {"num": 39344, "aya": 41, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق منصور- {ألم يروا أنا نأتي الأرض ننقصها من أطرافها}، قال: الموت."}, "39345": {"num": 39345, "aya": 41, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- {ننقصها من أطرافها}، قال: مَوْت أهلِها."}, "39346": {"num": 39346, "aya": 41, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق عبد الوهاب- في قوله: {ننقصها من أطرافها}، قال: مَوْت العلماء."}, "39347": {"num": 39347, "aya": 41, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ليث- في قوله: {ننقصها من أطرافها}، قال: في الأنفس، وفي الثمرات، وفي خَراب الأرض."}, "39348": {"num": 39348, "aya": 41, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق الأعرج- في قوله: {ننقُصُها من أطرافها}، قال: خرابُها."}, "39349": {"num": 39349, "aya": 41, "qail": "الضحاك بن مزاحم", "tabaqa": "تابعي", "bab": "", "text": "عن الضَّحّاك بن مُزاحِم، {أولمْ يروا أنّا نأتي الأرض ننقصها من أطرافها}، قال: أو لم يروا أنّا نفتحُ لمحمدٍ أرضًا بعدَ أرضٍ؟!."}, "39350": {"num": 39350, "aya": 41, "qail": "الضحاك بن مزاحم", "tabaqa": "تابعي", "bab": "", "text": "عن الضحاك بن مزاحم -من طريق سلمة بن نُبَيْط- قال: ما تَغَلَّبْتَ عليه مِن أرضِ العَدُوِّ."}, "39351": {"num": 39351, "aya": 41, "qail": "الضحاك بن مزاحم", "tabaqa": "تابعي", "bab": "", "text": "عن الضحاك بن مزاحم -من طريق عبيد بن سليمان- في قوله: {أو لم يروا أنّا نأتي الأرض ننقصها من أطرافها}، قال: يعني: أنّ نبيَّ الله صلى الله عليه وسلم كان يُنتقص له ما حوله من الأرضين، ينظرون إلى ذلك فلا يَعْتَبِرُون. وقال الله في سورة الأنبياء [44]: {نأتي الأرض ننقصها من أطرافها أفهم الغالبون}. قال: بل نبيُّ الله صلى الله عليه وسلم وأصحابُه هم الغالبون."}, "39352": {"num": 39352, "aya": 41, "qail": "قتادة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة، في قوله: {أولم يروا أنا نأتي الأرض ننقصها من أطرافها}، قال: كان عكرمة مولى ابن عباس يقول: هو قَبْضُ الناس."}, "39266": {"num": 39266, "aya": 38, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "", "text": "عن الحسن البصري -من طريق قتادة- في قوله: {لكلِ أجلِ كتابٌ}، قال: آجال بني آدم في كتابٍ."}, "39267": {"num": 39267, "aya": 38, "qail": "مقاتل بن سليمان", "tabaqa": "تابع التابعين", "bab": "", "text": "قال مقاتل بن سليمان، في قوله: {لكل أجل كتاب}، يقول: لا ينزِل مِن السماء كتابٌ إلا بأجل."}, "38846": {"num": 38846, "aya": 13, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر: أنّ رجلا سأله عن الرعد، فقال: ملَكُ يُسبِّح بحمده."}, "39271": {"num": 39271, "aya": 39, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "نزول الآية", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- قال: قالت قريشٌ حين أُنزِل: {وما كان لرسولٍ أن يأتي بآيةٍ إلا بإذن الله}: ما نراك -يا محمدُ- تملِك من شيءٍ، ولقد فُرِغ مِن الأمر. فأنزلت هذه الآية تخويفًا لهم ووعيدًا لهم: {يمحُوا الله ما يشاءُ ويُثْبتُ}."}, "38869": {"num": 38869, "aya": 13, "qail": "أنس بن مالك", "tabaqa": "صحابي", "bab": "نزول الآية", "text": "عن أنس بن مالك: أنّ رسول الله صلى الله عليه وسلم بعث رجلًا مِن أصحابه إلى رأس مِن رؤساءِ المشركين يدْعُوه إلى الله، فقال المشركُ: هذا الإلهُ الذي تدْعوني إليه أمِن ذهبٍ هو، أم من فضةٍ، أم من نُحاسٍ؟ فتَعاظَمَ مقالتَه، فرجع إلى النبيِّ صلى الله عليه وسلم، فأخبره، فقال: «ارْجِع إليه». فرجع إليه، فأعاد عليه القولَ الأول، فرجع، فأعاده الثالثة، فبينما هما يتراجعان الكلام بينهما إذ بعث اللهُ سحابةً حِيال رأسِه، فرعدت وأبرقت، ووقعت منها صاعقةٌ، فذهبت بقِحْفِ رأسه؛ فأنزل الله تعالى: {ويرسلُ الصَّواعقَ فيُصيبُ بها مَن يشاءُ} الآية."}, "38873": {"num": 38873, "aya": 13, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "نزول الآية", "text": "عن قتادة بن دعامة -من طريق سعيد- ذُكِر لنا: أنّ رجلًا أنكَر القرآنَ، وكذَّب النبيَّ صلى الله عليه وسلم، فأرسل الله عليه صاعقةً، فأهلكته؛ فأنزل الله فيه: {وهُمْ يجادلُون في الله} الآية."}, "38874": {"num": 38874, "aya": 13, "qail": "عبد الملك ابن جريج", "tabaqa": "تابع التابعين", "bab": "نزول الآية", "text": "عن عبد الملك ابن جُرَيْج -من طريق حجّاج- في قوله: {ويرسل الصواعق}، قال: نزلت في عامر بن الطُّفيل، وفي أرْبَدَ بن قيس، أقبل عامرٌ فقال: إنّ لي حاجةً. فقال له النبيُّ صلى الله عليه وسلم: «اقتَرِب». فاقتَرَب حتى حنى على النبيِّ صلى الله عليه وسلم، وسَلَّ أرْبَدُ بعضَ سيفه، فلما رأى النبيُّ صلى الله عليه وسلم بَرِيقَهُ تعوَّذ بآيةٍ مِن القرآن كان يتعوَّذ بها، فأَيْبَسَ اللهُ يد أرْبَدَ على السيف، وأرسل عليه صاعقةً، فاحترق، فذلك قولُ أخيه: أخشى على أرْبِدَ الحتوفَ … ولا أرْهبُ نَوْءَ السِّماك والأسدِ فجَّعني البرق والصواعق بالـ … ـفارس يومَ الكريهة النَّجِدِ."}, "39273": {"num": 39273, "aya": 39, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس: أنّ النبي صلى الله عليه وسلم سُئِل عن قوله: {يمحُوا الله ما يشاءُ ويثبتُ}. قال: «ذلك كلَّ ليلة القدر، يرفعُ، ويجبُرُ، ويرزقُ، غيرَ الحياةِ والموتِ، والشقاوةِ والسعادةِ؛ فإنّ ذلك لا يُبَدَّلُ»."}, "39274": {"num": 39274, "aya": 39, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس، قال: كان أبو روميٍّ مِن شرِّ أهل زمانه، وكان لا يدع شيئًا مِن المحارم إلا ارتكبه، وكان النبيُّ صلى الله عليه وسلم -يقول: «لَئِن رأيتُ أبا روميٍّ في بعض أزِقَّة المدينةِ لَأَضْرِبَنَّ عنقه». وإنّ بعض أصحاب النبيِّ صلى الله عليه وسلم أتاه ضَيْفٌ له، فقال لامرأته: اذهبي إلى أبي رُومِيٍّ، فخُذي لنا منه بدرهم طعامًا حتى يُيَسِّره الله. فقالت له: إنّك لتبعثني إلى أبي رُوميٍّ وهو مِن أفسقِ أهل المدينة؟! فقالَ: اذهبي، فليس عليك مِنه بأسٌ -إن شاء اللهُ-. فانطلَقَتْ إليه فضربتْ عليه الباب، فقال: مَن هذا؟ فقالت: فلانةُ. قال: ما كُنتِ لنا بزوّارة! ففتح لها البابَ، فأخذها بكلام رَفَثٍ، ومدَّ يده إليها، فأخذها رعدةٌ شديدة، فقال لها: ما شأنُكِ؟ قالت: إنّ هذا عَمَلٌ ما عَمِلْتُه قطُّ. قال أبو روميٌّ: ثَكِلَتْ أبا روميٍّ أمُّه، هذا عَمَلٌ عَمِلَه منذُ هو صغيرٌ، لا تأخذه رِعْدَةٌ ولا يُبالي، على أبي رومي عهدُ الله إن عاد لشيءٍ مِن هذا أبدًا. فلمّا أصبح غدا على النبي صلى الله عليه وسلم، فقال: «مرحبًا بأبي روميٍّ». وأخذ يُوَسِّع له بالمكان، وقال له: «يا أبا روميٍّ، ما عَمِلْتَ البارحة؟». فقال: ما عسى أن أعمل، يا نبيَّ الله؟! أنا شرُّ أهلِ الأرض. فقال النبيُّ صلى الله عليه وسلم: «إن الله قد حوَّل مَكْتَبَكَ إلى الجنة». فقال: {يمحوا الله ما يشاءُ ويثبتُ}."}, "39275": {"num": 39275, "aya": 39, "qail": "ابن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن ابن عباس، قال: كان أبو روميٍّ مِن شرِّ أهل زمانه، وكان لا يَدَعُ شيئًا مِن المحارم إلا ارتكبه، فلمّا غدا على النبيِّ صلى الله عليه وسلم، فلما رآه النَّبِيُّ صلى الله عليه وسلم مِن بعيد قال: «مرحبًا بأبي روميٍّ». وأخَذ يُوَسِّع له المكانَ، فقال له: «يا أبا روميٍّ، ما عملتَ البارحة؟». قال: ما عسى أن أعمل، يا نبيَّ الله؟ أنا شرُّ أهلِ الأرضِ. فقال له النبيُّ صلى الله عليه وسلم: «إنّ اللهَ قد جعل مَكْتَبَكَ إلى الجنة». فقال: {يمحُوا الله ما يشاءُ ويثبتُ وعندهُ أمُّ الكتاب}."}, "39276": {"num": 39276, "aya": 39, "qail": "عبد الله بن عمر", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عمر: سمعتُ رسولَ الله صلى الله عليه وسلم يقول: «{يمحو اللهُ ما يشاءُ ويثبتُ} إلا الشّقوة والسعادة، والحياة والموت»."}, "38893": {"num": 38893, "aya": 13, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن مجاهد بن جبر، {وهُو شديدُ المحالِ}، قال: شديدُ الانتقام."}, "38894": {"num": 38894, "aya": 13, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن مجاهد بن جبر -من طريق أبي يحيى- {وهو شديد المحال}، قال: شديد القُوَّة."}, "38895": {"num": 38895, "aya": 13, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن مجاهد بن جبر -من طريق خصيف- في قوله تعالى: {وهو شديد المحال}، قال: العَداوة."}, "39277": {"num": 39277, "aya": 39, "qail": "محمد بن السائب الكلبي", "tabaqa": "تابع التابعين", "bab": "", "text": "عن محمد بن السائب الكلبي، في الآية، قال: «يمحو مِن الرِّزق ويزيدُ فيه، ويمحو مِن الأجل ويزيدُ فيه». فقيل له: مَن حدَّثك بهذا؟ قال: أبو صالحٍ، عَن جابر بن عبد الله بن رئاب الأنصاريِّ، عن النبيِّ صلى الله عليه وسلم."}, "38900": {"num": 38900, "aya": 13, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن قتادة بن دعامة -من طريق سعيد- {وهُوَ شديدُ المحالِ}، أي: شديد القُوَّة والحيلة."}, "38906": {"num": 38906, "aya": 14, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق علي بن أبي طلحة- في قوله: {له دعوة الحق}، قال: شهادةُ أن لا إله إلا الله."}, "38907": {"num": 38907, "aya": 14, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- قوله: {له دعوة الحق}، قال: لا إله إلا الله."}}, "n_athar": {"0": 13, "1": 16, "2": 25, "3": 23, "4": 47, "5": 9, "6": 17, "7": 30, "8": 37, "9": 2, "10": 19, "11": 71, "12": 18, "13": 69, "14": 19, "15": 15, "16": 15, "17": 16, "18": 11, "19": 9, "20": 2, "21": 4, "22": 21, "23": 20, "24": 16, "25": 10, "26": 11, "27": 3, "28": 11, "29": 45, "30": 8, "31": 70, "32": 3, "33": 22, "34": 1, "35": 8, "36": 11, "37": 3, "38": 9, "39": 66, "40": 2, "41": 32, "42": 4, "43": 38}, "muh": ["ابن جرير", "ابن عطية", "ابن كثير", "ابن تيمية", "ابن القيم"], "ords": ["الأول", "الثاني", "الثالث", "الرابع", "الخامس", "السادس", "السابع", "الثامن", "التاسع", "العاشر"], "index": "فهرس.html"});